#      명령 분류기가 그 둘을 막으므로, **사람이 이 파일을 돌려야** 한다.
#      이 파일을 쓴 쪽은 **한 번도 굽지 않았다** — 재기만 했다.
#
# ── 이번에 굽는 것 — **이미지 둘.** 묶음은 **안 만든다** ──────────────
#     ① A/S 앱    dss-as:6.5            → dss-as:6.6              커밋 2
#     ② A/S 도구  dss-as-tools:32       → dss-as-tools:33         🔴 --target tools
#     ③ 🔵 **묶음 없음** — 올릴 .sql 이 **0건**이다(4절이 값으로 잰다).
