# ══ 🔴🔴 **이번 범위의 값은 여기 한자리에만 적는다** ══════════════════
#   아래 세 표(REPOS · CHANGED · NPMCOUNT)가 **이번 범위를 말하는 유일한 자리**다.
#   🔴 **같은 수를 다른 데 손으로 적지 마라** — 범위가 늘면 여기만 고치면 되게.
#   🔵 **끝 SHA 는 어디에도 안 적는다** — 늘 main 을 본다(git 이 그때그때 센다).
#      그래서 커밋이 더 밀려도 **고칠 자리는 커밋 수와 파일 수뿐**이다.
#
# ── 🔴 저장소 **하나** (74번과 같다) ──────────────────────────────────
#   열쇠|폴더|사람이 부르는 이름|기준 SHA|기준→main 커밋 수|개발 포트|public 이 있나
#   🔴 기준 SHA 의 출처 — **실측으로 확인했다**:
#      A/S  158d6211  일흔째(74번)가 올린 마지막 커밋
#                     — 「[A/S] 파일 올릴 때 적는 칸을 파일 이름에서 폴더 이름으로 바꾼다」
#                     🔵 그 뒤 커밋 **2**(ccf8785c 기술 절차 권한 · f0e3f957 미리보기).
#   🔵 **이번 범위에는 「이미지에 자취가 없는 커밋」이 없다** — 74번의 de818843
#      (현황판 HTML 한 장짜리) 같은 것이 하나도 없다. 그래서 2절의 커밋 수가
#      어긋나면 **5-ㅁ 의 파일 수도 함께 어긋난다**(둘이 짝으로 움직인다).
