#      이번 범위에 한 줄도 없다. 까닭과 되살리는 법은 머리말의 「왜 없는가」 ① 에 있다.
#   🔵 **public 칸이 yes 다** — A/S 는 **9개**다(아래 PUBLIC_WANT).
REPOS='
as|RF_Service_System|A/S관리|158d6211|2|3000|yes
'
REPOS_WANT=1
# 🔵 DB 는 dss-pg-app(5442) · dss-pg-auth(5444)가 개발 PC 에 떠 있다. 🔴 **끄지
