# ══ 🔴 **도구를 굽는 까닭** — 값으로 가린다 ═══════════════════════════
#   ㄴ) tools 스테이지가 담는 것 중 바뀐 파일 수.
#      🔴 A/S 는 **40 중 40**(src/ 39 + scripts/ 1).
#      🔵 **이번 범위에는 drizzle/ 이 0장**이라 74번의 「3장이 빠진다」가 안 걸린다.
#         🔴 그래도 5-ㄱ 의 as|drizzle|no 줄은 **그대로 둔다** — 그 줄이 「왜 묶음을
#         따로 보내야 하는가」의 근거이고, 1건이 생기는 날 그대로 일한다.
#
#   🔴🔴 **정규식을 | 로 나누는 표에 넣지 않는다 — 정규식 안에 | 가 들어 있다.**
#      [실측 2026-11-25 · 73번의 첫 --go] 처음에는 「열쇠|정규식|기대 수」 로 적었는데,
#      IFS='|' read 가 **정규식을 토막 내어** RE 가 「^(src/」 가 됐다. 그래서
#        grep: Unmatched ( or \(
#      로 grep 이 죽고 수가 **?** 가 되어 **⚠️ 둘**이 났다. 기대값 칸에는 정규식의
#      꼬리가 들어가 메시지까지 깨졌다.
#      🔵 **정규식은 스칼라로 두고** 표에는 **열쇠와 기대 수만** 둔다.
#   🔵 **INV_PAYLOAD_RE 가 없다** — 재고가 이번 판에 없다(머리말 「왜 없는가」 ①).
#      🔴 재고가 다시 올라가는 판에서는 **73-build.sh:660 에서 되살려라** — 그 집은
#         **drizzle/ 를 담고 vendor/ 를 안 담는다**(A/S 와 **정반대**다).
AS_PAYLOAD_RE='^(src/|scripts/|vendor/|package\.json|tsconfig\.json|drizzle\.config\.ts)'
payload_re() { # 1 집 열쇠
  case "$1" in
    as) printf '%s' "$AS_PAYLOAD_RE" ;;
  esac
}
TOOLS_PAYLOAD='
as|40
'
TOOLS_PAYLOAD_WANT=1
