# ══ 🔴 Dockerfile 이 담는 길 — **A/S 네 줄** ══════════════════════════
#   열쇠|정규식|있어야 하나(yes/no)|사람이 읽을 말
#   🔴 **drizzle 줄의 기대값이 no 다** — A/S 는 **볼륨이 정본**이기 때문이다.
#      🔴🔴 **재고는 그 줄이 yes 였다**(73-build.sh:706) — 집마다 **정반대**인 줄이
