as|^COPY .*src \./src|yes|🔴 A/S tools 가 src/ 를 담는다 — 바뀐 39장이 전부 여기다
as|^COPY .*vendor \./vendor|yes|🔴 A/S tools 가 vendor/ 를 담는다 — 🔵 이번 판은 그 안이 **안 움직였다**(3-ㅁ 이 뒷걸음으로 잰다)
as|^COPY .*drizzle \./drizzle|no|🔴 A/S tools 는 drizzle/ 을 **안 담는다** — 볼륨이 정본이다. 🔵 이번 판은 올릴 .sql 이 0건이라 묶음을 안 만든다
'
