# ══ 🔴 앱 번들에서 쓸 표식 — **전부 리터럴·칸 이름 · 기능 넷이 다 ASCII** ══
#   열쇠|갈래(feature|keep|side)|글자|사람이 읽을 말
#   🔴 **공백이 든 표식이 있고 한글이 여덟이다**(전부 **뒷걸음** 쪽이다).
#      그래서 이 표는 tr -d ' ' 로 읽지 않고 **here 문서 + IFS='|' read** 로만 읽는다.
#   🔴 **표식에 | 가 든 것은 하나도 없다**[값으로 확인] — 정규식을 이 꼴의 표에
#      넣었다가 깨진 자리가 따로 있다(TOOLS_PAYLOAD 의 주석).
#
#   🔴🔴 **기능 표식을 「코드 줄」에서 따오지 않았다** — minify 가 지역 이름을 갈아
#      치우고, 웹팩이 production 에서 **export 이름까지 줄인다**(mangleExports).
#      71번이 그 함정에 데었다: part.drawingNo, part.note 가 소스에는 1줄인데
#      **번들에서는 0/0** 이었다.
#   🔵 **이번 기능 표식 넷은 문자열 리터럴 하나와 객체 칸 이름 셋**이다.
#      · technicalProcedures.create — 권한 **열쇠 문자열**(minify 가 내용을 안 바꾼다)
#      · remarkAlign · labelPx · remarkFitPx — **객체 칸 이름**(property mangling 은
#        꺼져 있다 — 71번이 번들에서 shareDocRelativePath 23 · faultTags 19 를 센
#        것이 그 증거다). 🔴 **지역 이름이 아니다** — part. 같은 접두사를 안 붙였다.
#   🔵 **74번과 달리 ASCII 기능 표식이 있다** — 한글 경계가 깨져도 기능 판정은 산다.
#      🔴 **그래도 1-ㄷ 절을 안 뺐다**(뒷걸음 여덟이 한글이다).
#
#   🔴🔴 **아래 수는 전부 「소스에서 센 값」이다 — 번들 수가 아니다.**
#      이 파일은 **한 번도 굽지 않았다 — 재기만 했다.** 🔴 --go 가 번들 수를
#      **처음** 찍는다. 그때 기능 표식이 0 으로 나오면 **되돌리기 전에 --verify 로
#      다시 재고 이 주석부터 보라.**
#      🔵 71번이 번들에서 실제로 센 값 중 이 판에도 쓰는 것(참고):
#        shareDocRelativePath 23 · 도번 / 비고 2 · hasLiveApproval 3 ·
#        domesticOrders.completedEdit 5 · faultTags 19 · radiogroup 5 ·
#        "ORDER_ISSUED" 2 · domestic-order-status-filter 2 ·
#        portal_approval_delegations 23 · domesticOrders.view 8
#      🔵 **74·73번의 기능 표식 일곱과 NO_WAITING_REPAIR_STEP 은 번들 수가 안 적혀
#         있다** — 다만 74·73·72번이 그것을 **기능 표식**으로 두고 --preload 를 지나
#         --go 까지 갔으므로 dss-as:6.5 · 6.4 · 6.3 번들에서 **≥1 이었다**
#         (0 이었으면 그 모드가 거기서 멈춘다).
#         🔴 **뒷걸음이 0 이면 진짜 결함이다.**
#
#   🔴 feature = 기준 0 → 지금 1 이상이어야 한다(안 그러면 아무것도 안 가른다)
#      keep    = 기준에도 지금에도 1 이상이어야 한다(뒷걸음을 재는 자리)
#      side    = 🔵 **판정에 안 쓴다.** 값만 찍는다.
APPMARKS='
as|feature|technicalProcedures.create|🔵 **ASCII** · ㄱ갈래의 **새 권한 열쇠** (ccf8785c) — 기준 0 → 지금 9파일
as|feature|remarkAlign|🔵 **ASCII** · ㄴ갈래 — 비고 맞춤을 양식에서 읽어 넘기는 칸 이름 (f0e3f957) — 기준 0 → 지금 5파일
as|feature|labelPx|🔵 **ASCII** · ㄴ갈래 — 칸 폭을 px 로 넘기는 칸 이름 (f0e3f957) — 기준 0 → 지금 8파일
as|feature|remarkFitPx|🔵 **ASCII** · ㄴ갈래 — 넘침을 픽셀로 재는 칸 이름 (f0e3f957) — 기준 0 → 지금 3파일
as|side|INVENTORY_RETURN_REQUEST_TYPE|🔵 곁들이 — 예순아홉째 상수의 **export 이름**. 기준 4 → 지금 4. 🔴 판정에 안 쓴다(mangleExports 가 줄인다)
as|side|canAuthorTechnicalTemplatesByDefault|🔵 곁들이 — 이번 판의 **export 이름**. 기준 0 → 지금 4파일. 🔴 판정에 안 쓴다(웹팩이 줄일 수 있다)
as|side|DATA: "DATA"|🔵 곁들이 — 일흔째의 **소스 꼴**(공백 있음). 기준 1 → 지금 1파일. 🔴 번들에는 공백이 지워져 안 남을 것이다
as|side|DATA:"DATA"|🔵 곁들이 — 일흔째의 **minify 꼴**(공백 없음). 소스에는 0 이 맞다. 🔵 번들에서 ≥1 이면 다음 판이 이것을 기능 표식으로 쓸 수 있다
as|keep|폴더 이름 (선택)|🔴 **한글** · 일흔째의 기능 표식이 내려왔다 — 기준 8 → 지금 8파일
as|keep|폴더 이름에 경로 글자|🔴 **한글** · 일흔째의 거절 글귀가 내려왔다 — 기준 1 → 지금 1파일
as|keep|확장자는 원본과 같게 유지됩니다|🔴 **한글** · 일흔째의 창 안내가 내려왔다 — 기준 1 → 지금 1파일
as|keep|파일 이름에 경로 글자|🔴 **한글** · 일흔째의 거절 글귀가 내려왔다 — 기준 1 → 지금 1파일
as|keep|반환 요청|🔴 **한글** · 예순아홉째가 올린 글자 — 기준 8 → 지금 8파일
as|keep|return-candidates|🔵 **ASCII** · 예순아홉째가 올린 글자 — 기준 3 → 지금 3파일
as|keep|부품 신청 거두기|🔴 **한글** · 예순아홉째가 올린 글자 — 기준 1 → 지금 1파일
