# ══ 표를 읽는 길 ══════════════════════════════════════════════════════
#   🔴 **공백이 든 표(COPYRULES·APPMARKS)는 tr -d ' ' 로 읽지 않는다** — 말이 뭉개진다.
#      그 표는 while IFS='|' read 로만 읽는다.
rows_of() { printf '%s\n' "$1" | grep -v '^[[:space:]]*$'; }
field() { printf '%s' "$1" | cut -d'|' -f"$2"; }
row_by_key() { # 1 표 2 열쇠
  rows_of "$1" | while IFS= read -r r; do
    [ "$(field "$r" 1)" = "$2" ] && printf '%s' "$r"
  done
}
repo_dir()  { printf '%s/%s' "$DEV" "$(field "$(row_by_key "$REPOS" "$1")" 2)"; }
repo_name() { field "$(row_by_key "$REPOS" "$1")" 3; }
repo_base() { field "$(row_by_key "$REPOS" "$1")" 4; }
# 🔴 도구 열쇠(astools)에서 저장소 열쇠(as)를 뽑는다 — IMAGES 표의 둘째 칸을
#    믿지 않고 이름 규칙으로 뽑으면 표를 고친 날 한 곳만 바뀐다. 그래서 **표에서**
#    저장소 폴더를 꺼내 쓰고, 이 함수는 **표식 표를 찾는 데만** 쓴다.
repo_key_of() { printf '%s' "${1%tools}"; }

# 「기준 SHA 때 그 글자가 든 src/ 파일 수」 — 🔴 pathspec 에 글롭이 든 경로를
# 넘기지 않는다(src 하나만 넘긴다).
mark_was() { git -C "$1" grep -lF -- "$3" "$2" -- src 2>/dev/null </dev/null | wc -l | tr -d ' '; }
mark_now() { grep -rlF -- "$2" "$1/src" 2>/dev/null | wc -l | tr -d ' '; }

# 🔴 **자주 쓰는 자리는 여기서 한 번 계산한다** — check_all 안에서만 잡으면
#    --verify 가 그 함수를 건너뛰는 날 빈 값으로 돈다(아무것도 안 재는 ✓).
ASD="$DEV/$(field "$(row_by_key "$REPOS" as)" 2)"
COREDIR="$ASD/vendor/dss-core"
UIDIR="$ASD/vendor/dss-ui"
# 🔵 **IVD · IVUIDIR 이 없다** — 재고가 이번 판에 없다(머리말 「왜 없는가」 ①).
#    🔴 재고가 다시 올라가는 판에서는 **73-build.sh:1046-1047 에서 되살려라** —
#       그 집의 서브모듈은 **dss-ui 하나**이고(그 집에는 dss-core 가 없다), 3절의
#       핀 검사와 3-ㄷ 의 작업본 검사가 **셋**이 된다.

# ══════════════════════════════════════════════════════════════════════
check_all() {
PASS=0; FAIL=0; UNK=0

# ── 0. 🔴 Git Bash 인가 (WSL 이면 ✗ 가 흩어져 난다) ──────────────────
step "0. 🔴 Git Bash 에서 도는가 — WSL 이면 여기서 멈춘다"
say "뿌리 경로: $DEV"
case "$DEV" in
  /mnt/*)
    bad "🔴 **WSL 에서 돌고 있다**(뿌리가 /mnt/ 로 시작한다) — 여기서 구우면 유령 diff 가 난다"
    say "    → PowerShell 에서 이렇게 부르세요:"
    say "       & \"C:\\Program Files\\Git\\bin\\bash.exe\" ./75-build.sh $MODE"
    ;;
  /[a-z]/*)
    ok "Git Bash 다 (뿌리가 /c/ 꼴이다)"
    ;;
  *)
    unk "셸 갈래" "뿌리가 /mnt/ 도 /c/ 도 아니다 — $DEV"
    ;;
esac
u=$(uname -s 2>/dev/null)
say "uname -s: ${u:-못 읽음}"
case "${u:-}" in
  MINGW*|MSYS*) ok "uname 도 Git Bash 를 가리킨다 ($u)" ;;
  Linux)        bad "uname 이 Linux 다 — **WSL 이다**" ;;
  *)            note "uname 이 ${u:-못 읽음} 다 — 사람이 보세요" ;;
esac

# ── 1. 도커가 도는가 ──────────────────────────────────────────────────
step "1. 도커가 도는가"
if docker version --format '{{.Server.Version}}' >/dev/null 2>&1; then
  v=$(docker version --format '{{.Server.Version}}' 2>/dev/null)
  ok "도커가 돈다 (서버 ${v:-판 못 읽음})"
else
  bad "도커가 안 돈다 — Docker Desktop 을 켜세요"
fi

# ── 1-ㄴ. 🔴 **경로 번역이 정말 꺼졌는가** — 값으로 잰다 (결함 ②) ────
#   🔴 이 절이 없어서 쉰여덟째의 첫 굽기에 **가짜 ✗ 일곱**이 났다. 번역이 켜져
#      있으면 아래 절들의 ✗ 가 **진짜 결함처럼 보인다.**
#   🔵 컨테이너가 하나 필요하다 — 옛 판이든 새 판이든 **있는 것**을 쓴다.
say ""
say "── 1-ㄴ. 🔴 Git Bash 의 경로 번역이 꺼졌는가 (MSYS_NO_PATHCONV)"
PROBE_IMG=""
PROBEIMG_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  PROBEIMG_SEEN=$((PROBEIMG_SEEN+1))
  t=$(field "$r" 3)
  if [ -z "${PROBE_IMG:-}" ] && docker image inspect "$t" >/dev/null 2>&1; then PROBE_IMG=$t; fi
  t2=$(field "$r" 5); t2=$(printf '%s' "${t2%.tar}" | sed 's/-\([0-9][0-9.]*\)$/:\1/')
  if [ -z "${PROBE_IMG:-}" ] && docker image inspect "$t2" >/dev/null 2>&1; then PROBE_IMG=$t2; fi
done <<ENDPROBEIMG
$(rows_of "$IMAGES")
ENDPROBEIMG
say "잴 후보로 본 줄 ${PROBEIMG_SEEN}개 (기대 $HOWMANY)"
if [ "$PROBEIMG_SEEN" != "$HOWMANY" ]; then
  bad "IMAGES 표를 ${PROBEIMG_SEEN}줄만 읽었다 — ${HOWMANY}줄을 기대했다. 표가 깨졌다"
fi
if [ -z "${PROBE_IMG:-}" ]; then
  unk "경로 번역" "잴 이미지가 하나도 없다 — 옛 판도 새 판도 이 PC 에 없다"
  say "      🔴 **이 줄이 ? 면 아래 이미지 안 검사를 믿지 마세요.**"
else
  say "재는 데 쓴 이미지: $PROBE_IMG"
  v=$(dockr run --rm -e DSSPROBE="/app/dss-pathconv-probe" --entrypoint sh "$PROBE_IMG" -c 'printf "%s" "$DSSPROBE"' 2>/dev/null | tr -d '\r')
  say "넘긴 값 [/app/dss-pathconv-probe] → 컨테이너가 받은 값 [${v:-못 읽음}]"
  if [ "${v:-}" = "/app/dss-pathconv-probe" ]; then
    ok "경로 번역이 **꺼져 있다** (아래 이미지 안 검사를 믿을 수 있다)"
  elif [ -z "${v:-}" ]; then
    unk "경로 번역" "컨테이너에서 값을 못 받았다"
  else
    bad "🔴 경로 번역이 **살아 있다** — 받은 값이 [${v}] 다"
    say "      🔴 이대로 두면 아래의 표식·파일 검사가 **가짜 ✗** 를 냅니다."
    say "      → PowerShell 에서 이렇게 부르세요(Git Bash 로):"
    say "         & \"C:\\Program Files\\Git\\bin\\bash.exe\" ./75-build.sh $MODE"
    say "      → 그래도 안 꺼지면 이 파일 맨 위의 dockr() 줄을 보세요."
  fi
fi

# ── 1-ㄷ. 🔴🔴 **한글이 컨테이너 경계를 글자 그대로 건너가는가** ─────
#   🔴 **70번에서 통째로 가져왔다**(70-build.sh:741-786). 이 판의 뒷걸음 표식 하나가
#      **한글**이기 때문이다 — 그 까닭은 KO_MARKS 의 주석에 길게 적어 두었다.
#   🔵 길은 1-ㄴ 과 **같다**: 보내고 **되돌려 받아** 글자와 **바이트 수**를 맞댄다.
#      🔴 8진 이스케이프로 우회하지 않았다. 백슬래시 한 겹이 조용히 삼켜지는
#         함정이 이 PC 에 적혀 있어 **그 길이 더 위험**하다.
say ""
say "── 1-ㄷ. 🔴🔴 **한글이 컨테이너 안까지 글자 그대로 가는가** (표식 여덟이 한글이다)"
say "🔴 이 줄이 ✗ 면 **이미지가 아니라 검사가 깨진 것**입니다 — 아래 한글 표식의"
say "   0 을 결함으로 읽지 마세요."
say "🔴🔴 **이번 판은 기능 표식 넷이 전부 한글이고 ASCII 기능 표식이 하나도 없습니다** —"
say "   그래서 이 절이 더 중요해졌습니다. 경계가 깨지면 **기능 넷이 한꺼번에 ✗** 입니다."
say "🔵 **대조는 뒷걸음 쪽이 맡습니다** — return-candidates · shareDocRelativePath(둘 다"
say "   ASCII)가 ✓ 인데 **한글만 0** 이면 그것 자체가 「한글 grep 이 안 되는 것」이라는"
say "   증거입니다. 🔴 **그때는 이미지를 되돌리지 마세요.**"
if [ -z "${PROBE_IMG:-}" ]; then
  unk "한글 경계" "잴 이미지가 없다 (1-ㄴ 과 같은 까닭)"
else
  KO_SEEN=0; KO_OK=0
  ko_probe() { # 1 글자
    local hb v got cb
    KO_SEEN=$((KO_SEEN+1))
    hb=$(printf '%s' "$1" | wc -c | tr -d ' ')
    v=$(dockr run --rm -e DSSKO="$1" --entrypoint sh "$PROBE_IMG" -c \
      'printf "%s|%s\n" "$DSSKO" "$(printf "%s" "$DSSKO" | wc -c | tr -d " ")"' 2>/dev/null | tr -d '\r')
    got=$(printf '%s' "$v" | cut -d'|' -f1)
    cb=$(printf '%s' "$v" | cut -d'|' -f2)
    printf '      보낸 [%s] %s바이트 → 받은 [%s] %s바이트\n' "$1" "$hb" "${got:-못 읽음}" "${cb:-?}"
    if [ "${got:-}" = "$1" ] && [ "${cb:-x}" = "$hb" ]; then
      KO_OK=$((KO_OK+1))
    else
      bad "한글이 경계에서 **달라졌다** — 받은 [${got:-못 읽음}] ${cb:-?}바이트 (보낸 ${hb}바이트)"
      say "      🔴 **이미지를 의심하지 마세요.** 로케일이나 인자 전달이 깨진 것입니다."
      doubt
    fi
  }
  while IFS= read -r km; do
    [ -n "$km" ] || continue
    ko_probe "$km"
  done <<ENDKO
$(rows_of "$KO_MARKS")
ENDKO
  say "본 한글 ${KO_SEEN}개 · 그대로 건너간 것 ${KO_OK}개 (기대 $KO_MARKS_WANT · $KO_MARKS_WANT)"
  if [ "$KO_SEEN" = "$KO_MARKS_WANT" ] && [ "$KO_OK" = "$KO_MARKS_WANT" ]; then
    ok "한글 ${KO_MARKS_WANT}개가 **컨테이너까지 글자 그대로 간다** (번들의 0 을 결함으로 읽어도 된다)"
    say "      🔵 [실측 2026-11-26 · 개발 PC] 보낸 바이트: [도번 / 비고] 15 ·"
    say "         [재고 관리에서 찾기] 26 · [반환 요청] 13 · [부품 신청 거두기] 23 ·"
    say "         [폴더 이름 (선택)] 22 · [폴더 이름에 경로 글자] 30 ·"
    say "         [파일 이름에 경로 글자] 30 · [확장자는 원본과 같게 유지됩니다] 45."
    say "         🔵 앞의 넷은 70·71·73번이 잰 값과 **같습니다.**"
  else
    bad "본 것 ${KO_SEEN} · 그대로인 것 ${KO_OK} 다 — ${KO_MARKS_WANT} 를 기대했다"
    say "      🔴 **아래 한글 표식의 ✗ 는 전부 이 줄의 결과입니다.** 이미지를 되돌리지 마세요."
  fi
fi

# ── 2. 🔴 저장소 **둘** ───────────────────────────────────────────────
step "2. 🔴 저장소 **하나** — 깨끗한가 · 올라가 있나 · 범위가 맞나"
say "🔴 구운 이미지는 **그때 그 작업 폴더의 사진**입니다. 커밋 안 된 줄이 섞이면"
say "   나중에 같은 이미지를 다시 못 만듭니다."
say "🔵 **73번은 집이 둘이라 고리가 두 바퀴 돌았습니다** — 이번엔 한 바퀴입니다."
say "   🔴 **고리 꼴을 안 건드렸습니다** — 집이 다시 둘이 되는 날 표에 줄만 더하면 됩니다."
REPO_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  RK=$(field "$r" 1); RD="$DEV/$(field "$r" 2)"; RN=$(field "$r" 3)
  RB=$(field "$r" 4); RC=$(field "$r" 5)
  REPO_SEEN=$((REPO_SEEN+1))
  printf '\n    ── %s (%s)\n' "$RN" "$RD"
  if [ ! -d "$RD/.git" ]; then
    bad "$RN — 저장소가 없다 ($RD)"
    continue
  fi
  br=$(git -C "$RD" rev-parse --abbrev-ref HEAD 2>/dev/null)
  [ "$br" = "main" ] && ok "$RN 가지가 main 이다" || bad "$RN 가지가 ${br:-못 읽음} 다 — main 이어야 한다"
  dirty=$(git -C "$RD" status --porcelain=v1 2>/dev/null | wc -l | tr -d ' ')
  if [ "${dirty:-1}" = "0" ]; then ok "$RN 미커밋 0줄"
  else
    bad "$RN 에 미커밋이 ${dirty}줄 있다 — 굽기 전에 정리하세요"
    git -C "$RD" status --porcelain=v1 2>/dev/null | head -8 | sed 's/^/        /'
  fi
  h=$(git -C "$RD" rev-parse --short HEAD 2>/dev/null)
  o=$(git -C "$RD" rev-parse --short origin/main 2>/dev/null)
  say "HEAD $h · origin/main ${o:-없음}"
  if [ -n "${o:-}" ] && [ "$h" = "$o" ]; then
    ok "$RN main == origin/main (올라가 있다)"
  else
    ab=$(git -C "$RD" rev-list --left-right --count main...origin/main 2>/dev/null)
    bad "$RN main 과 origin/main 이 다르다 (왼쪽=안 올린 것 오른쪽=안 받은 것: ${ab:-못 읽음})"
    say "      🔴 **「미푸시 0」은 받았다는 뜻이 아닙니다** — 오른쪽 수도 보세요."
  fi
  if git -C "$RD" cat-file -e "$RB^{commit}" 2>/dev/null; then
    n=$(git -C "$RD" rev-list --count "$RB..main" 2>/dev/null)
    say "기준 $RB..main 커밋 ${n:-못 읽음}개 (적어 둔 값 $RC)"
    git -C "$RD" log --oneline "$RB..main" 2>/dev/null | head -12 | sed 's/^/        /'
    if [ "${n:-x}" = "$RC" ]; then
      ok "$RN 범위가 적어 둔 것과 같다 ($RC 커밋)"
    else
      note "$RN 커밋이 ${n:-?}개다 — $RC 을 적어 두었다. **사람이 보세요**"
      say "      🔵 ⚠️ 로만 셉니다 — 그 사이에 하나 더 밀었을 수 있습니다."
      say "      🔵 **71번에 실제로 그 일이 있었습니다** — 지시서는 50커밋이었고 재 보니"
      say "         51 이었습니다. 더 밀린 한 커밋이 진행현황 HTML 한 장짜리라 **이미지에**"
      say "         **아무 자취도 안 남겼습니다.**"
      say "      🔴🔴 **이번 범위에도 그 「자취 없는 커밋」이 하나 있습니다** —"
      say "         de818843 이 **현황판 HTML 한 장짜리**입니다[실측]. 그래서 커밋이"
      say "         늘어도 **5-ㅁ 의 파일 수가 안 어긋날 수 있습니다**(HTML 만 더 밀린 경우)."
      say "      🔴 **표식·파일 수 기대값이 전부 그 범위에서 나온 값**입니다 —"
      say "         5-ㅁ 이 함께 어긋나면 **거기서 멈추고 사람에게 알리세요.**"
      say "      🔴🔴 **drizzle/ 이 함께 어긋나면 더 크게 멈추세요** — 이번 판은"
      say "         **마이그레이션 1건**을 전제로 쓰였고, 한 장이 더 밀리면 **묶음과"
      say "         기대값(135)이 통째로 틀립니다**(4-ㄴ 이 값으로 잡습니다)."
    fi
  else
    bad "$RN 기준 SHA $RB 가 이 저장소에 없다 — 표가 틀렸다"
  fi
done <<ENDREPO
$(rows_of "$REPOS")
ENDREPO
say ""
[ "$REPO_SEEN" = "$REPOS_WANT" ] && ok "저장소 ${REPOS_WANT}곳을 다 봤다 (표본이 비지 않았다)" \
  || bad "저장소를 ${REPO_SEEN}곳만 봤다 — ${REPOS_WANT}곳을 기대했다. REPOS 표가 깨졌다"

# ── 3. 🔴 서브모듈 — **「되감기지 않았다」를 값으로 잰다** ────────────
step "3. 🔴 서브모듈 — **dss-core 가 안 움직인다.** 그것을 값으로 잰다"
say "🔴 **74번과 뜻이 다시 뒤집힌 절입니다**(머리말 ④) — 74번은 「**움직였는가**」를"
say "   쟀고 이 판은 73번처럼 「**되감기지 않았는가**」를 잽니다."
say "   🔴 **재는 값과 변수는 한 글자도 안 바꿨습니다** — 판정 글만 뒤집었습니다."
say "🔴 [실측 2026-11-27 · git ls-tree 로 기준판과 지금을 둘 다 쟀다]"
say "   dss-core **${AS_CORE_PIN:0:8} 그대로** · dss-ui **${UI_PIN:0:8} 그대로**."
say "   🔵 옛 핀 ${AS_CORE_PREV_PIN:0:8} → 지금 핀 사이의 커밋 $AS_CORE_MOVED_COMMITS · 파일 $AS_CORE_MOVED_FILES 은"
say "      **일흔째가 옮긴 폭**입니다(이번 판이 옮긴 폭이 아닙니다)."
say "🔵 **서브모듈이 둘입니다**(73번은 셋이었고 셋째가 **재고의** dss-ui 였습니다)."
say "🔴 **README.md:558 의 옛 핀(b79e5ab8)을 베끼지 마세요** — 그것은 쉰여덟째 때"
say "   값입니다. 예순두째가 1e9ec85 로, 예순일곱째가 ${AS_CORE_PREV_PIN:0:8} 로, 일흔째가"
say "   ${AS_CORE_PIN:0:8} 로 옮겼고 **이 판은 안 옮깁니다.**"
say "🔴 핀 글자가 맞아도 **안이 비어 있을 수 있습니다** — 3-ㄷ 이 안의 파일을 값으로"
say "   세고, **3-ㄹ 이 예순일곱째의 칸 넷**, **3-ㅁ 이 일흔째의 enum 값**을 봅니다"
say "   (둘 다 **뒷걸음**을 재는 자리입니다)."
ASD="$DEV/$(field "$(row_by_key "$REPOS" as)" 2)"
COREDIR="$ASD/vendor/dss-core"
UIDIR="$ASD/vendor/dss-ui"
pin_of() { git -C "$1" submodule status "$2" 2>/dev/null </dev/null | awk '{print $1}' | tr -d '+-'; }
SUB_SEEN=0
check_pin() { # 1 저장소 2 서브모듈경로 3 기대 핀 4 사람이 읽을 말
  local p
  SUB_SEEN=$((SUB_SEEN+1))
  p=$(pin_of "$1" "$2")
  if [ -z "${p:-}" ]; then
    bad "$1 의 $2 포인터를 못 읽었다 — 서브모듈이 없거나 init 이 안 됐다"
    return
  fi
  if [ "$p" = "$3" ]; then ok "$2 = ${3:0:8} — **적어 둔 핀과 같다** ($4)"
  else
    bad "$2 가 ${p:0:8} 다 — ${3:0:8} 을 기대했다 (🔴 **이 배포본의 전제가 깨졌다**)"
    say "      🔴 멈추고 알리세요. 이 배포본은 그 핀을 전제로 쓰였습니다."
    doubt
  fi
}
say ""
say "── 3-ㄱ. 핀 값 — 🔴 **둘 다 그대로여야 한다** (서브모듈 **둘**을 본다)"
check_pin "$ASD" vendor/dss-core "$AS_CORE_PIN" "🔵 일흔째가 올린 핀 그대로다 — 되감기면 ${AS_CORE_PREV_PIN:0:8} 가 된다"
check_pin "$ASD" vendor/dss-ui   "$UI_PIN"      "🔵 안 움직였다"
[ "$SUB_SEEN" = "2" ] && ok "서브모듈 핀 둘을 다 봤다 (표본이 비지 않았다)" \
  || bad "서브모듈 핀을 ${SUB_SEEN}개만 봤다 — 2개를 기대했다"
say "      🔵 73번은 여기가 **셋**이었습니다(A/S 둘 + 재고의 dss-ui). 재고가 다시"
say "         올라가는 판에서는 **73-build.sh:1281 에서 셋째 줄을 되살리세요.**"
# 🔴 **옛 핀 그대로가 아닌가**를 따로 묻는다 — 위의 ✓ 는 「적어 둔 값과 같다」일
#    뿐이고, 적어 둔 값 자체를 잘못 베껴 왔으면 그 ✓ 가 **옛 핀을 통과시킨다.**
#    🔴 **74번과 뜻이 다시 뒤집힌 자리다**(머리말 ④) — 74번에서는 「옛 핀이면
#       **이번 판이 안 올라간 것**」이었고, 여기서는 「옛 핀이면 **되감긴 것**」이다.
#    🔴 **코드는 한 글자도 안 바꿨다** — 글만 뒤집었다.
cp0=$(pin_of "$ASD" vendor/dss-core)
say "dss-core 핀: ${cp0:-못 읽음} (옛 핀 $AS_CORE_PREV_PIN 이면 안 된다)"
if [ -z "${cp0:-}" ]; then
  unk "dss-core 핀이 옛 것인가" "포인터를 못 읽었다"
elif [ "$cp0" = "$AS_CORE_PREV_PIN" ]; then
  bad "🔴 dss-core 가 **일흔째 이전의 핀으로 되감겼다** — 그 판이 올린 것이 사라진다"
  say "      🔴 그대로 구우면 공용 스키마에 **DATA 가 없는 채**로 돕니다 — 운영 DB 의"
  say "         enum 에는 그 값이 있는데 코드가 그 값을 모르는 꼴이 됩니다."
  doubt
else
  ok "dss-core 가 옛 핀(${AS_CORE_PREV_PIN:0:8})이 **아니다** — 되감기지 않았다"
fi

say ""
say "── 3-ㄴ. 🔴 **이번 범위가 vendor/ 를 건드렸는가** — **0줄**이어야 한다"
say "🔴 **74번과 기대값이 반대입니다**(거기는 1줄이어야 했습니다). 🔵 이번 판은 공용"
say "   묶음을 안 건드립니다 — 1 이상이면 **누가 포인터를 움직인 것**이고, 그러면"
say "   굽는 까닭과 도구 표식의 전제가 함께 어긋납니다(5-ㄹ 이 같은 값으로 잽니다)."
CHROW=$(row_by_key "$CHANGED" as)
CH_VENDOR=$(field "$CHROW" 6)
VEN_SEEN=0; VEN_OK=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  RK=$(field "$r" 1); RD="$DEV/$(field "$r" 2)"; RN=$(field "$r" 3); RB=$(field "$r" 4)
  VEN_SEEN=$((VEN_SEEN+1))
  WV=$(field "$(row_by_key "$CHANGED" "$RK")" 6)
  VL=$(git -C "$RD" diff --name-only "$RB..main" 2>/dev/null | tr -d '\r' | grep -E '^(vendor/|\.gitmodules)' || true)
  vn=$(printf '%s\n' "$VL" | grep -c . || true)
  say "$RN 의 vendor/ · .gitmodules 변경 ${vn:-?}줄 (기대 $WV)"
  [ -n "${VL:-}" ] && printf '%s\n' "$VL" | sed 's/^/        /'
  if [ "${vn:-x}" = "$WV" ]; then
    VEN_OK=$((VEN_OK+1))
    ok "$RN 범위가 vendor/ 를 **${WV}줄 건드렸다** (공용 묶음이 안 움직였다)"
  else
    bad "$RN 의 vendor/ 변경이 ${vn:-?}줄이다 — $WV 을 기대했다"
    say "      🔴 **멈추고 알리세요.** 1 이상이면 포인터가 움직인 것이고, 그러면"
    say "         3-ㅁ 의 뜻(뒷걸음)과 5-ㄹ 의 기대값이 함께 어긋납니다."
    doubt
  fi
done <<ENDVEN
$(rows_of "$REPOS")
ENDVEN
[ "$VEN_SEEN" = "$REPOS_WANT" ] && [ "$VEN_OK" = "$REPOS_WANT" ] \
  && ok "집 ${REPOS_WANT}곳의 vendor/ 를 다 봤다 (표본이 비지 않았다)" \
  || bad "본 집 ${VEN_SEEN} · 맞는 집 ${VEN_OK} 다 — ${REPOS_WANT} 을 기대했다"
say "      🔵 그래서 **굽는 까닭 ㄹ 은 이번에 안 걸립니다** — 굽는 까닭은 **ㄴ 하나**"
say "         (tools 가 담는 것 중 바뀐 파일 40장)입니다(5-ㄹ)."
# 🔴 서브모듈 **안으로 들어가** 센다 — 포인터 글자만 맞대면 「같은 핀을 다른
#    저장소가 들고 있는」 꼴을 못 가른다.
CORE_ORIGIN_OK=0
if [ -d "$COREDIR/.git" ] || [ -f "$COREDIR/.git" ]; then
  if git -C "$COREDIR" cat-file -e "$AS_CORE_PIN^{commit}" 2>/dev/null; then
    n=$(git -C "$COREDIR" rev-list --count "$AS_CORE_PIN..HEAD" 2>/dev/null)
    say "dss-core 안: 적어 둔 핀 → 지금 HEAD 커밋 ${n:-못 읽음}개 (기대 $AS_CORE_COMMITS_WANT)"
    if [ "${n:-x}" = "$AS_CORE_COMMITS_WANT" ]; then
      ok "dss-core 작업본이 **그 핀 위에 서 있다** (핀보다 앞선 커밋이 없다)"
    else
      bad "dss-core 작업본이 핀보다 ${n:-?}커밋 앞서 있다 — $AS_CORE_COMMITS_WANT 을 기대했다"
      say "      🔴 앞서 있으면 **아직 A/S 에 안 올린 커밋을 굽는 것**입니다."
      git -C "$COREDIR" log --oneline "$AS_CORE_PIN..HEAD" 2>/dev/null | head -5 | sed 's/^/        /'
    fi
  else
    unk "dss-core 커밋 수" "적어 둔 핀 ${AS_CORE_PIN:0:8} 가 그 저장소에 없다"
  fi
  # 🔴 **옛 핀 → 지금 핀 사이에 무엇이 들었나** — 🔵 **이 판에서는 「일흔째가 올린
  #    것」**이다(이번 판이 올린 것이 아니다). 🔴 그 수가 0 이면 **되감긴 것**이고,
  #    2 이상이면 **누가 더 올린 것**이다.
  if git -C "$COREDIR" cat-file -e "$AS_CORE_PREV_PIN^{commit}" 2>/dev/null; then
    mc=$(git -C "$COREDIR" rev-list --count "$AS_CORE_PREV_PIN..$AS_CORE_PIN" 2>/dev/null)
    mf=$(git -C "$COREDIR" diff --name-only "$AS_CORE_PREV_PIN..$AS_CORE_PIN" 2>/dev/null | tr -d '\r' | grep -c . || true)
    say "dss-core 옛 핀 → 지금 핀: 커밋 ${mc:-?}개 · 바뀐 파일 ${mf:-?}장 (기대 $AS_CORE_MOVED_COMMITS · $AS_CORE_MOVED_FILES)"
    git -C "$COREDIR" log --oneline "$AS_CORE_PREV_PIN..$AS_CORE_PIN" 2>/dev/null | sed 's/^/        /'
    git -C "$COREDIR" diff --name-only "$AS_CORE_PREV_PIN..$AS_CORE_PIN" 2>/dev/null | sed 's/^/        /'
    if [ "${mc:-x}" = "$AS_CORE_MOVED_COMMITS" ] && [ "${mf:-x}" = "$AS_CORE_MOVED_FILES" ]; then
      ok "**일흔째가 옮긴 폭이 그대로다** (커밋 ${AS_CORE_MOVED_COMMITS}개 · 파일 ${AS_CORE_MOVED_FILES}장)"
    else
      note "dss-core 가 커밋 ${mc:-?} · 파일 ${mf:-?} 만큼 움직였다 — $AS_CORE_MOVED_COMMITS · $AS_CORE_MOVED_FILES 를 기대했다. **사람이 보세요**"
      say "      🔵 늘었으면 누가 공용 묶음을 더 올린 것입니다 — 3-ㅁ 의 표도 함께 보세요."
    fi
  else
    unk "dss-core 가 움직인 폭" "옛 핀 ${AS_CORE_PREV_PIN:0:8} 가 그 저장소에 없다"
  fi
  # 🔴🔴 **origin 에 올라가 있는가** — 안 올라가 있으면 다른 PC 가 그 핀을 못 받아
  #    submodule update 가 그 자리에서 죽는다. 🔵 이 PC 에서는 멀쩡히 구워진다 —
  #    그래서 **여기서 안 재면 영영 안 드러난다.**
  ro=$(git -C "$COREDIR" rev-parse origin/main 2>/dev/null)
  say "dss-core origin/main: ${ro:-못 읽음} (핀 $AS_CORE_PIN 과 같아야 한다)"
  if [ -z "${ro:-}" ]; then
    unk "dss-core 가 origin 에 올라갔는가" "origin/main 을 못 읽었다 — 원격이 없거나 fetch 전이다"
  elif [ "$ro" = "$AS_CORE_PIN" ]; then
    CORE_ORIGIN_OK=1
    ok "dss-core 의 그 커밋이 **origin/main 에 올라가 있다** (다른 PC 도 받을 수 있다)"
  else
    if git -C "$COREDIR" merge-base --is-ancestor "$AS_CORE_PIN" "$ro" 2>/dev/null; then
      CORE_ORIGIN_OK=1
      ok "핀이 origin/main 의 **조상이다** — 올라가 있다 (origin 이 ${ro:0:8} 로 더 앞서 있을 뿐)"
    else
      bad "🔴 dss-core 의 핀이 **origin 에 없다** — 다른 PC 는 그 핀을 못 받는다"
      say "      🔴 먼저 vendor/dss-core 를 밀어 두세요. 안 그러면 submodule update 가"
      say "         그 자리에서 죽고, 이 PC 에서만 되는 이미지가 됩니다."
      doubt
    fi
  fi
else
  bad "vendor/dss-core 가 **비어 있다**(.git 이 없다) — submodule update --init 이 필요하다"
fi

say ""
say "── 3-ㄷ. 🔴 **핀만 보면 빈 서브모듈도 통과한다** — 안의 파일을 값으로 센다"
SUBFILE_SEEN=0
check_sub() { # 1 폴더 2 이름
  SUBFILE_SEEN=$((SUBFILE_SEEN+1))
  local n d
  n=$(ls -1 "$1" 2>/dev/null | wc -l | tr -d ' ')
  if [ "${n:-0}" -ge 3 ] 2>/dev/null; then ok "$2 작업본에 파일이 ${n}개 있다"
  else bad "$2 작업본이 비었다(${n:-?}개) — submodule update --init 이 필요하다"; fi
  d=$(git -C "$1" status --porcelain=v1 2>/dev/null | wc -l | tr -d ' ')
  if [ "${d:-1}" = "0" ]; then ok "$2 미커밋 0줄"
  else bad "$2 에 미커밋이 ${d}줄 있다 — 🔴 서브모듈 안을 고치지 마세요"; fi
}
check_sub "$COREDIR" "A/S-core"
check_sub "$UIDIR"   "A/S-ui"
[ "$SUBFILE_SEEN" = "2" ] && ok "서브모듈 작업본 둘을 다 봤다 (표본이 비지 않았다)" \
  || bad "서브모듈 작업본을 ${SUBFILE_SEEN}개만 봤다 — 2개를 기대했다"
say "      🔴 **dss-ui 가 비어 있으면 앱이 Module not found 로 안 구워집니다**"
say "         — 메뉴바와 종이 @dss/ui 에서 옵니다."
if [ -f "$COREDIR/$AS_CORE_KEEP_FILE" ]; then
  ok "쉰여덟째가 올린 공용 스키마가 **작업본에 있다** ($AS_CORE_KEEP_FILE)"
  n=$(grep -cF "$AS_CORE_KEEP_TABLE" "$COREDIR/$AS_CORE_KEEP_FILE" 2>/dev/null || true)
  if isnum "${n:-}" && [ "${n:-0}" -ge 1 ]; then
    ok "그 파일이 표 이름 $AS_CORE_KEEP_TABLE 을 적는다 (${n}줄)"
  else
    bad "그 파일에 표 이름 $AS_CORE_KEEP_TABLE 이 없다 — 다른 것을 보고 있다"
  fi
else
  bad "공용 스키마 파일이 **작업본에 없다** — 🔴 핀만 맞고 **파일이 비었다**"
  say "      🔴 그대로 구우면 도구가 @dss/core/schema 에서 그 표를 **못 찾습니다.**"
  say "      → git -C \"$ASD\" submodule update --init --recursive"
fi
n=$(grep -c "$AS_CORE_KEEP_EXPORT" "$COREDIR/src/schema/index.ts" 2>/dev/null || true)
if isnum "${n:-}" && [ "${n:-0}" -ge 1 ]; then
  ok "index.ts 가 그 스키마를 **내보낸다** (${n}줄)"
  say "      🔵 안 내보내면 도구가 Cannot find export 로 죽습니다 — 2026-09-21 에"
  say "         운영에서 도구가 전부 죽은 그 자리입니다."
else
  bad "index.ts 가 그 스키마를 안 내보낸다 — Cannot find export 가 난다"
fi

# 🔴 **예순일곱째가 그 안에 더한 칸 넷이 아직 있는가** — 하나라도 없으면 그 기능이
#    조용히 죽는다(화면은 뜨고 그 칸만 사라진다).
say ""
say "── 3-ㄹ. 🔴 **예순일곱째가 공용 스키마에 더한 칸 넷이 아직 있는가** (뒷걸음 방지)"
say "🔴 **이 절의 뜻은 73·74번 그대로입니다** — 「이번 판이 더했는가」가 아니라"
say "   「**아직 있는가**」입니다. 🔴 **빼지 않았습니다** — 빼면 서브모듈이 되감긴 날"
say "   아무도 못 잡습니다. 🔵 바로 아래 3-ㅁ 도 이번 판에는 **같은 뜻**입니다."
say "🔵 칸 이름(snake)과 속성 이름(camel)을 **둘 다** 봅니다 — 한쪽만 있으면 선언이 반쪽입니다."
NEWCOL_SEEN=0; NEWCOL_OK=0
while IFS='|' read -r CF CN CP; do
  [ -n "${CF:-}" ] || continue
  NEWCOL_SEEN=$((NEWCOL_SEEN+1))
  if [ ! -f "$COREDIR/$CF" ]; then
    bad "$CF 이 **작업본에 없다** — 서브모듈을 안 받았다"
    continue
  fi
  a=$(grep -cF -- "$CN" "$COREDIR/$CF" 2>/dev/null || true)
  b=$(grep -cF -- "$CP" "$COREDIR/$CF" 2>/dev/null || true)
  printf '      %-44s [%s] %s줄 · [%s] %s줄\n' "$CF" "$CN" "${a:-?}" "$CP" "${b:-?}"
  if [ "${a:-0}" -ge 1 ] 2>/dev/null && [ "${b:-0}" -ge 1 ] 2>/dev/null; then
    NEWCOL_OK=$((NEWCOL_OK+1))
  else
    bad "$CF 에 $CN / $CP 가 없다 — 칸 이름 ${a:-?}줄 · 속성 ${b:-?}줄 (둘 다 1 이상이어야 한다)"
  fi
done <<ENDNEWCOL
$(rows_of "$AS_CORE_NEW")
ENDNEWCOL
say "본 칸 ${NEWCOL_SEEN} · 갖춘 칸 ${NEWCOL_OK} (기대 $AS_CORE_NEW_WANT · $AS_CORE_NEW_WANT)"
if [ "$NEWCOL_SEEN" = "$AS_CORE_NEW_WANT" ] && [ "$NEWCOL_OK" = "$AS_CORE_NEW_WANT" ]; then
  ok "공용 스키마가 **예순일곱째의 칸 넷을 아직 다 선언한다** (되감기지 않았다)"
else
  bad "본 칸 ${NEWCOL_SEEN} · 갖춘 칸 ${NEWCOL_OK} 다 — $AS_CORE_NEW_WANT 을 기대했다"
  say "      🔴 **서브모듈을 안 받았거나 옛 핀으로 되감겼습니다.** 3-ㄱ 을 다시 보세요."
  doubt
fi

# 🔴🔴 **일흔째가 공용 스키마에 더한 것이 아직 있는가** — 뜻이 뒷걸음으로 바뀌었다.
say ""
say "── 3-ㅁ. 🔴🔴 **일흔째가 공용 스키마에 더한 것이 아직 있는가** (옛 핀 0줄 → 지금 1줄)"
say "🔴 **74번에서 이 절을 한 글자도 안 바꿨습니다** — 뜻만 「이번에 더했는가」에서"
say "   「**아직 있는가**」로 뒤집혔습니다(이번 판은 공용 스키마를 안 건드립니다)."
say "🔴 **기준은 옛 핀의 그 파일**에서 셉니다 — 지금 파일만 보면 「원래 있던 것」과"
say "   못 가릅니다. 🔵 **옛 핀 0 · 지금 1** 이면 일흔째의 그 값이 그대로 서 있는 것이고,"
say "   **지금이 0 이면 되감긴 것**입니다."
say "🔵 **글자를 \"DATA\", 로 고른 까닭**: 그냥 DATA 로 세면 OSCILLOSCOPE_DATA 때문에"
say "   기준판에도 걸려 **아무것도 안 가릅니다**[실측 · 기준 5파일]."
CTH_SEEN=0; CTH_OK=0
while IFS='|' read -r CF CM CWAS CNOW; do
  [ -n "${CF:-}" ] || continue
  CTH_SEEN=$((CTH_SEEN+1))
  if [ ! -f "$COREDIR/$CF" ]; then
    bad "$CF 이 **작업본에 없다** — 서브모듈을 안 받았다"
    continue
  fi
  was=$(git -C "$COREDIR" show "$AS_CORE_PREV_PIN:$CF" 2>/dev/null </dev/null | grep -cF -- "$CM" || true)
  now=$(grep -cF -- "$CM" "$COREDIR/$CF" 2>/dev/null || true)
  printf '      %-40s [%s] 옛 핀 %s줄 → 지금 %s줄 (기대 %s → %s)\n' \
    "$CF" "$CM" "${was:-?}" "${now:-?}" "$CWAS" "$CNOW"
  if [ "${was:-x}" = "$CWAS" ] && [ "${now:-x}" = "$CNOW" ]; then
    CTH_OK=$((CTH_OK+1))
  elif [ "${was:-x}" != "$CWAS" ]; then
    bad "$CF 의 옛 핀에 그 글자가 ${was:-?}줄 있다 — $CWAS 를 기대했다"
    say "      🔴 0 이 아니면 그 표식은 **이 판을 안 가릅니다.** 다른 글자를 고르세요."
    doubt
  else
    bad "$CF 의 지금 줄이 ${now:-?} 다 — $CNOW 을 기대했다. 🔴 **서브모듈이 되감겼다**"
    doubt
  fi
done <<ENDCTH
$(rows_of "$AS_CORE_THIS")
ENDCTH
say "본 것 ${CTH_SEEN} · 맞는 것 ${CTH_OK} (기대 $AS_CORE_THIS_WANT · $AS_CORE_THIS_WANT)"
if [ "$CTH_SEEN" = "$AS_CORE_THIS_WANT" ] && [ "$CTH_OK" = "$AS_CORE_THIS_WANT" ]; then
  ok "공용 스키마에 **일흔째의 값(enum 의 DATA)이 아직 있다**"
  say "      🔴 **그 값이 사라진 채로 구우면** 운영 DB 의 enum 에는 그 값이 있는데"
  say "         코드는 그 값을 모르는 꼴이 됩니다 — 화면은 뜨고 그 분류만 사라집니다."
else
  bad "본 것 ${CTH_SEEN} · 맞는 것 ${CTH_OK} 다 — $AS_CORE_THIS_WANT 을 기대했다"
  doubt
fi
# 🔵 **enum 이름도 같은 파일에서 한 번 본다** — 「다른 파일을 보고 있다」를 가른다.
n=$(grep -cF -- "$AS_ENUM_NAME" "$COREDIR/src/schema/attachments.ts" 2>/dev/null || true)
say "      그 파일이 enum 이름 [$AS_ENUM_NAME] 을 적는가: ${n:-?}줄 (기대 1 이상)"
[ "${n:-0}" -ge 1 ] 2>/dev/null && ok "enum 이름이 같은 파일에 있다 (과녁을 제대로 보고 있다)" \
  || bad "그 파일에 enum 이름 $AS_ENUM_NAME 이 없다 — **다른 파일을 보고 있다**"

# ── 4. 🔴🔴 마이그레이션 — **0건이다.** (74번의 절 다섯을 그대로 둔다) ──
step "4. 🔴🔴 마이그레이션 — **0건** (A/S $AS_SQL_WAS 장 **그대로**)"
say "🔴 **74번은 1건이었습니다.** 🔴 **절을 하나도 안 뺐습니다** — 기대값만 0 으로"
say "   두었습니다(4-ㄱ 잣대 표본 · 4-ㄴ 수 세기 · 4-ㄷ 장마다 생김새 · 4-ㄹ 창 안 ·"
say "   4-ㅁ 묶음 지문). 🔵 1건이 생기는 날 AS_NEW_MIGS 에 번호를 적고"
say "   AS_NEW_MIGS_WANT 를 올리면 **그대로 되살아납니다.**"
say "🔵 **이번 판은 DB 를 한 글자도 안 바꿉니다** — 새 권한 열쇠"
say "   (technicalProcedures.create)는 role_permissions.area_key 가 **text** 라"
say "   마이그레이션이 필요 없습니다[실측 2026-11-27]."
say "🔵 **drizzle 는 밀린 것을 한 트랜잭션에 넣습니다** — 밀린 것이 **0건**이라"
say "   그 함정 자체가 안 걸립니다."

# 4-ㄱ. 🔴 **잣대가 살아 있는가를 먼저 잰다** — 표본 여덟
say ""
say "── 4-ㄱ. 🔴 지우는 문장 잣대가 **살아 있는가** (표본 여덟으로 먼저 잰다)"
say "🔴 표본이 비어서 공짜로 통과하는 일을 막는 절입니다. 잣대가 죽어 있으면"
say "   다음 판의 「지우는 문장 0줄」이 **아무것도 안 재는 ✓** 가 됩니다."
say "🔴🔴 **이번 판은 잴 .sql 이 0장입니다. 그래도 표본 여덟을 하나도 안 뺐습니다** —"
say "   여기서 재는 것은 **잣대 자신**이지 이번 범위가 아닙니다."
PROBE_SEEN=0
probe_destructive() { # 1 글 2 기대(hit|miss) 3 이름
  local n
  PROBE_SEEN=$((PROBE_SEEN+1))
  n=$(printf '%s\n' "$1" | grep -v "$SQL_COMMENT_RE" | grep -ciE "$DESTRUCTIVE_RE" || true)
  case "$2" in
    hit)  if [ "${n:-0}" -ge 1 ] 2>/dev/null; then ok "잣대가 $3 를 **잡는다**"; else bad "잣대가 $3 를 **못 잡는다** — 잣대가 죽었다"; fi ;;
    miss) if [ "${n:-1}" = "0" ]; then ok "잣대가 $3 를 **안 센다** (맞다)"; else bad "잣대가 $3 를 **센다** — 멀쩡한 판이 ✗ 가 된다"; fi ;;
  esac
}
probe_destructive 'DROP TABLE "x";'                          hit  "DROP TABLE"
probe_destructive 'TRUNCATE "x";'                            hit  "TRUNCATE"
probe_destructive 'DELETE FROM "x" WHERE id = 1;'            hit  "DELETE FROM"
probe_destructive '-- DELETE FROM "x" 는 안 한다'            miss "주석 속 DELETE FROM"
probe_destructive 'ALTER TABLE "x" ADD COLUMN "y" text;'     miss "ADD COLUMN (71번의 실물)"
probe_destructive 'ALTER TABLE "x" DROP COLUMN "y";'         hit  "DROP COLUMN (뒤집은 짝)"
probe_destructive 'REFERENCES "u"("id") ON DELETE restrict'  miss "ON DELETE restrict (0133 의 실물)"
probe_destructive 'ALTER TYPE "p"."c" ADD VALUE (quote)D(quote) BEFORE (quote)O(quote);' miss "🔴 ADD VALUE (0134 의 실물)"
say "본 표본 ${PROBE_SEEN}개 (기대 8)"
[ "$PROBE_SEEN" = "8" ] && ok "잣대 표본 여덟을 다 돌았다 (표본이 비지 않았다)" \
  || bad "잣대 표본을 ${PROBE_SEEN}개만 돌았다 — 8개를 기대했다"
say "🔵 다섯째·여섯째가 **짝**입니다 — ADD COLUMN 은 안 세고, 글자 하나 다른"
say "   DROP COLUMN 은 잡습니다. 하나만 두면 잣대가 어느 쪽으로 죽었는지 모릅니다."
say "🔴 **여덟째는 74번이 넣은 표본**입니다 — 0134 의 실물꼴입니다. 🔴 **안 뺐습니다.**"
say "   🔵 작은따옴표는 (quote) 로 적었습니다 — 이 파일 안에서 따옴표를 겹치지 않으려고"
say "      그랬고, 잣대가 보는 것은 DROP/TRUNCATE/DELETE FROM 뿐이라 판정이 안 달라집니다."

# 4-ㄴ. 수 세기 — 🔴 **A/S 135 그대로**
say ""
say "── 4-ㄴ. 저장소 drizzle/ 을 센다 (.sql 수 == meta/_journal.json 의 idx 수)"
MIGCK_SEEN=0
s=$(ls -1 "$ASD/drizzle"/*.sql 2>/dev/null | wc -l | tr -d ' ')
j=$(grep -o '"idx"' "$ASD/drizzle/meta/_journal.json" 2>/dev/null | wc -l | tr -d ' ')
MIGCK_SEEN=$((MIGCK_SEEN+1))
say "A/S .sql ${s:-?}장 · idx ${j:-?}개 (기대 $AS_SQL_WANT · $AS_SQL_WANT)"
if [ "${s:-x}" = "$AS_SQL_WANT" ] && [ "${j:-x}" = "$AS_SQL_WANT" ]; then
  ok "A/S drizzle/ 이 ${AS_SQL_WANT}장이고 목록도 ${AS_SQL_WANT}개다 (🔵 운영 ${AS_SQL_WAS}장과 **같다**)"
else
  bad "A/S 가 .sql ${s:-?} · idx ${j:-?} 다 — ${AS_SQL_WANT}·${AS_SQL_WANT} 를 기대했다"
  say "      🔴 **.sql 과 idx 가 다르면** 목록에 없는 파일이 있다는 뜻이고,"
  say "         drizzle 이 그것을 **아예 모릅니다**(적용이 0건으로 조용히 끝납니다)."
  doubt
fi
MIGCK_SEEN=$((MIGCK_SEEN+1))
dn=$(git -C "$ASD" diff --name-only "$(repo_base as)..main" -- drizzle 2>/dev/null | tr -d '\r' | grep -c . || true)
say "A/S 범위의 drizzle/ 변경 ${dn:-?}줄 (기대 $AS_DRIZZLE_DIFF_WANT)"
git -C "$ASD" diff --name-only "$(repo_base as)..main" -- drizzle 2>/dev/null | sed 's/^/        /'
if [ "${dn:-x}" = "$AS_DRIZZLE_DIFF_WANT" ]; then
  ok "A/S 범위가 drizzle/ 을 **${AS_DRIZZLE_DIFF_WANT}줄 건드렸다** — 🔵 **올릴 마이그레이션이 없다**"
  say "      🔵 그래서 이 파일은 **묶음을 안 만들고**, 75-deploy.sh 의 --migrate 는"
  say "         **볼륨을 한 글자도 안 건드립니다**(place_migs 가 앞에서 멈춥니다)."
  say "      🔴 **그래도 --migrate 모드를 안 뺐습니다** — 거기서 덤프 · compose 사본 ·"
  say "         도구 태그 갈기 · db:preflight 가 그대로 돌고, 1건이 생기는 날 뒤가 이어집니다."
else
  bad "A/S 의 drizzle/ 변경이 ${dn:-?}줄이다 — $AS_DRIZZLE_DIFF_WANT 을 기대했다"
  say "      🔴 이 배포본은 **0건**을 전제로 쓰였습니다. 1 이상이면 **묶음을 만들어야**"
  say "         하고 --migrate 의 기대값이 통째로 달라집니다. **멈추고 알리세요.**"
  doubt
fi
MIGCK_SEEN=$((MIGCK_SEEN+1))
TN=0; TNSEEN=0
for t in $AS_NEW_MIGS; do
  TNSEEN=$((TNSEEN+1))
  a=$(ls -1 "$ASD/drizzle/${t}"_*.sql 2>/dev/null | wc -l | tr -d ' ')
  b=$(ls -1 "$ASD/drizzle/meta/${t}"_snapshot.json 2>/dev/null | wc -l | tr -d ' ')
  printf '      %-6s .sql %s개 · 스냅샷 %s개 (기대 1 · 1)\n' "$t" "${a:-0}" "${b:-0}"
  [ "${a:-0}" = "1" ] && [ "${b:-0}" = "1" ] && TN=$((TN+1))
done
say "이번 판이 올릴 ${AS_NEW_MIGS_WANT}장 — 본 것 ${TNSEEN}장 · 짝으로 있는 것 ${TN}장"
if [ "$TNSEEN" = "$AS_NEW_MIGS_WANT" ] && [ "$TN" = "$AS_NEW_MIGS_WANT" ]; then
  if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
    ok "올릴 .sql 이 **0장이고 고리도 0바퀴 돌았다** (🔵 이 판은 DB 를 안 건드린다)"
    say "      🔴 **고리를 지우지 않았습니다** — 1건이 생기는 날 AS_NEW_MIGS 에 번호를"
    say "         적으면 그대로 돕니다(74번이 0134 로 그렇게 썼습니다)."
  else
    ok "$AS_NEW_MIGS 이 .sql·스냅샷 짝으로 있다 (**이 배포의 목적물이다**)"
  fi
else
  bad "이번 판이 올릴 .sql 이 본 것 ${TNSEEN} · 짝 ${TN} 다 — ${AS_NEW_MIGS_WANT} 을 기대했다"
  doubt
fi
# 🔴 **「없다」만 재면 번호가 빗나가도 통과한다** — 반대쪽을 같은 줄에서 함께 센다.
MIGCK_SEEN=$((MIGCK_SEEN+1))
lastn=$(ls -1 "$ASD/drizzle/${AS_LAST_MIG}"_*.sql 2>/dev/null | wc -l | tr -d ' ')
nx=$(ls -1 "$ASD/drizzle/${AS_NEXT_MIG}"_*.sql 2>/dev/null | wc -l | tr -d ' ')
say "$AS_LAST_MIG 이 있는가: ${lastn:-?}개 (기대 1) · $AS_NEXT_MIG 이 생겼는가: ${nx:-?}개 (기대 0)"
if [ "${lastn:-0}" = "1" ] && [ "${nx:-1}" = "0" ]; then
  ok "마지막이 $AS_LAST_MIG 이고 $AS_NEXT_MIG 은 없다 (적용 대기 **${AS_NEW_MIGS_WANT}건**)"
  say "      🔵 **이 판에서 이 줄의 뜻은 뒷걸음입니다** — 일흔째가 올린 0134 가 아직"
  say "         있고, 그 뒤로 **아무도 새 .sql 을 안 만들었다**는 뜻입니다."
  say "      🔵 **두 쪽을 함께 세는 까닭**: 「$AS_NEXT_MIG 이 없다」만 재면 번호를"
  say "         잘못 적어 둔 날에도 **영영 ✓** 가 됩니다(70번이 그 꼴로 두 판 연속 샜습니다)."
  say "      🔴 **0135 가 생기면 이 배포본의 전제가 깨집니다** — 묶음도 --migrate 의"
  say "         기대값도 통째로 달라집니다."
elif [ "${lastn:-0}" != "1" ]; then
  bad "$AS_LAST_MIG 이 ${lastn:-?}개다 — 1 을 기대했다. 🔴 **번호가 빗나갔거나 안 올라왔다**"
  doubt
else
  bad "$AS_NEXT_MIG 이 **생겼다** — 이 배포본은 $AS_LAST_MIG 까지를 전제로 쓰였다. 멈추고 알릴 것"
fi
[ "$MIGCK_SEEN" = "4" ] && ok "마이그레이션 수 검사 넷을 다 돌았다 (표본이 비지 않았다)" \
  || bad "마이그레이션 수 검사를 ${MIGCK_SEEN}개만 돌았다 — 4개를 기대했다"

# 4-ㄷ. 🔴 **장마다** 생김새를 본다 — 🔵 **이번 판은 0바퀴 돈다**
say ""
say "── 4-ㄷ. 🔴 **새 .sql 의 생김새** — **장마다** 본다 (🔵 이번 판은 **0장**이다)"
say "🔴 **고리 꼴을 한 글자도 안 건드렸습니다** — 71번은 두 장, 74번은 한 장이었고"
say "   이번은 **0장**입니다. 🔴 **「0 이니 빼자」가 아닙니다** — 빼면 1건이 생기는 날"
say "   아무도 다시 안 넣습니다. 🔵 아래가 「0장을 다 봤다」를 값으로 단언합니다."
MIGSHAPE_SEEN=0; MIGSHAPE_OK=0; AVSUM=0; ACSUM=0
for t in $AS_NEW_MIGS; do
  MIGSHAPE_SEEN=$((MIGSHAPE_SEEN+1))
  P=$(ls -1 "$ASD/drizzle/${t}"_*.sql 2>/dev/null | head -1)
  if [ -z "${P:-}" ] || [ ! -f "$P" ]; then
    bad "$t 의 .sql 을 못 찾았다"
    continue
  fi
  REL=${P#"$ASD/"}
  added=$(git -C "$ASD" diff --diff-filter=A --name-only "$(repo_base as)..main" -- drizzle 2>/dev/null | tr -d '\r' | grep -cFx "$REL" || true)
  raw=$(grep -ciE "$DESTRUCTIVE_RE" "$P" 2>/dev/null || true)
  net=$(grep -v "$SQL_COMMENT_RE" "$P" 2>/dev/null | grep -ciE "$DESTRUCTIVE_RE" || true)
  ct=$(grep -v "$SQL_COMMENT_RE" "$P" 2>/dev/null | grep -c 'CREATE TABLE' || true)
  ins=$(grep -v "$SQL_COMMENT_RE" "$P" 2>/dev/null | grep -c 'INSERT INTO' || true)
  upd=$(grep -v "$SQL_COMMENT_RE" "$P" 2>/dev/null | grep -c 'UPDATE ' || true)
  rn=$(grep -ciE 'RENAME' "$P" 2>/dev/null || true)
  ac=$(grep -v "$SQL_COMMENT_RE" "$P" 2>/dev/null | grep -c 'ADD COLUMN' || true)
  av=$(grep -v "$SQL_COMMENT_RE" "$P" 2>/dev/null | grep -c 'ADD VALUE' || true)
  en=$(grep -cF "$AS_ENUM_NAME" "$P" 2>/dev/null || true)
  ev=$(grep -cF "$AS_ENUM_VALUE" "$P" 2>/dev/null || true)
  eb=$(grep -cF "$AS_ENUM_BEFORE" "$P" 2>/dev/null || true)
  isnum "${av:-}" && AVSUM=$((AVSUM + av))
  isnum "${ac:-}" && ACSUM=$((ACSUM + ac))
  printf '      %-6s %s\n' "$t" "$REL"
  printf '        새파일 %s · 지우는문장 날것 %s/걷은뒤 %s(기대 %s) · ADD VALUE %s(기대 1 이상) · ADD COLUMN %s(기대 0)\n' \
    "${added:-0}" "${raw:-?}" "${net:-?}" "$MIG_DROP_WANT" "${av:-?}" "${ac:-?}"
  printf '        CREATE TABLE %s(기대 0) · INSERT %s(기대 0) · UPDATE %s(기대 0) · RENAME %s(기대 0)\n' \
    "${ct:-?}" "${ins:-?}" "${upd:-?}" "${rn:-?}"
  printf '        enum 이름 [%s] %s줄 · 값 [%s] %s줄 · 자리 [%s] %s줄 (셋 다 1 이상이어야 한다)\n' \
    "$AS_ENUM_NAME" "${en:-?}" "$AS_ENUM_VALUE" "${ev:-?}" "$AS_ENUM_BEFORE" "${eb:-?}"
  if [ "${added:-0}" = "1" ] && [ "${net:-x}" = "$MIG_DROP_WANT" ] && [ "${ins:-1}" = "0" ] \
     && [ "${upd:-1}" = "0" ] && [ "${ct:-1}" = "0" ] && [ "${rn:-1}" = "0" ] \
     && [ "${av:-0}" -ge 1 ] 2>/dev/null && [ "${ac:-1}" = "$AS_ADDCOL_WANT" ] \
     && [ "${en:-0}" -ge 1 ] 2>/dev/null && [ "${ev:-0}" -ge 1 ] 2>/dev/null && [ "${eb:-0}" -ge 1 ] 2>/dev/null; then
    MIGSHAPE_OK=$((MIGSHAPE_OK+1))
    ok "$t 이 **이번 범위의 새 파일**이고 **enum 값을 더하기만 한다**"
  else
    bad "$t 이 기대와 다르다 — 새파일 ${added:-?} · 지우는문장 ${net:-?} · INSERT ${ins:-?} · UPDATE ${upd:-?} · CREATE TABLE ${ct:-?} · RENAME ${rn:-?} · ADD VALUE ${av:-?} · ADD COLUMN ${ac:-?}"
    say "      🔴 **UPDATE 나 INSERT 가 0 이 아니면 멈추세요** — 같은 트랜잭션에서 새 enum"
    say "         값을 쓰는 판이고, 그러면 **쪼개도 안 넘어갑니다.**"
    say "      🔴 RENAME 이 0 이 아니면 **칸이 둔갑하는 판**입니다 — db:generate 가 TTY"
    say "         없이 물어볼 수 없을 때 「이름 바꾸기」로 답한 판이 그런 꼴로 나옵니다."
    doubt
  fi
done
say "본 장 ${MIGSHAPE_SEEN} · 온전한 장 ${MIGSHAPE_OK} (기대 $AS_NEW_MIGS_WANT · $AS_NEW_MIGS_WANT)"
say "ADD VALUE 합 ${AVSUM} (기대 $AS_ADDVALUE_WANT) · ADD COLUMN 합 ${ACSUM} (기대 $AS_ADDCOL_WANT)"
if [ "$MIGSHAPE_SEEN" = "$AS_NEW_MIGS_WANT" ] && [ "$MIGSHAPE_OK" = "$AS_NEW_MIGS_WANT" ]; then
  if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
    ok "**0장을 다 봤다** (고리가 0바퀴 돌았고 그것이 맞다)"
  else
    ok "그 장을 **다 보고 다 온전했다** (표본이 비지 않았다)"
  fi
else
  bad "본 장 ${MIGSHAPE_SEEN} · 온전한 장 ${MIGSHAPE_OK} 다 — $AS_NEW_MIGS_WANT 을 기대했다"
fi
# 🔴 **두 쪽을 같은 줄에서 센다** — 한쪽만 재면 과녁이 빗나가도 통과한다.
if [ "$AVSUM" = "$AS_ADDVALUE_WANT" ] && [ "$ACSUM" = "$AS_ADDCOL_WANT" ]; then
  ok "ADD VALUE 가 ${AS_ADDVALUE_WANT}개이고 ADD COLUMN 은 ${AS_ADDCOL_WANT}개다 (🔵 이 판은 **DB 를 안 건드린다**)"
else
  note "ADD VALUE ${AVSUM} · ADD COLUMN ${ACSUM} 이다 — $AS_ADDVALUE_WANT · $AS_ADDCOL_WANT 를 기대했다. **사람이 보세요**"
  say "      🔵 ADD COLUMN 이 1 이상이면 **칸이 함께 생기는 판**이라 75-deploy.sh 의"
  say "         NEWCOLS 표에 그 칸을 **더해야** 합니다(71번이 그 꼴이었습니다)."
fi

# 4-ㄹ. 🔵 창 안 여덟 — 🔵 **이 판에서는 뒷걸음을 재는 자리다**
say ""
say "── 4-ㄹ. 🔵 창 안 여덟($AS_KEEP_MIGS) — .sql 과 스냅샷이 짝으로 있는가"
say "🔵 **이 판에서 이 절의 뜻은 뒷걸음입니다** — 묶음을 안 만들므로 「통째로 갈아"
say "   끼울 때 빠지면 안 된다」가 아니라 「**지난 판들이 넣어 둔 것이 아직 짝으로"
say "   있는가**」입니다. 🔴 한 장이라도 스냅샷이 빠지면 다음 판의 db:generate 가"
say "   엉뚱한 차이를 만들어 냅니다."
say "🔵 71번은 일곱이었습니다(0127~0133). **74번이 0134 를 더해 여덟**이고 그대로입니다."
KEEP_MISS=""
KEEP_SEEN=0
for t in $AS_KEEP_MIGS; do
  KEEP_SEEN=$((KEEP_SEEN+1))
  a=$(ls -1 "$ASD/drizzle/${t}"_*.sql 2>/dev/null | wc -l | tr -d ' ')
  b=$(ls -1 "$ASD/drizzle/meta/${t}"_snapshot.json 2>/dev/null | wc -l | tr -d ' ')
  printf '      %-6s .sql %s · 스냅샷 %s\n' "$t" "${a:-0}" "${b:-0}"
  [ "${a:-0}" -ge 1 ] 2>/dev/null || KEEP_MISS="$KEEP_MISS $t(sql)"
  [ "${b:-0}" -ge 1 ] 2>/dev/null || KEEP_MISS="$KEEP_MISS $t(snapshot)"
done
if [ "$KEEP_SEEN" = "$AS_KEEP_MIGS_WANT" ] && [ -z "${KEEP_MISS:-}" ]; then
  ok "창 안 ${AS_KEEP_MIGS_WANT}장이 .sql 과 스냅샷을 다 갖췄다"
else
  bad "본 것 ${KEEP_SEEN}장 · 빠진 것:${KEEP_MISS:- 없음} (${AS_KEEP_MIGS_WANT}장을 기대했다)"
fi

# 4-ㅁ. 🔴🔴 묶음 지문 — 🔵 **이번 판은 묶음을 안 만든다**
say ""
say "── 4-ㅁ. 🔴🔴 **묶음 지문** — 🔵 **이번 판은 묶음을 안 만듭니다**"
say "🔴 **74번과 뜻이 반대입니다.** 거기서는 「incoming 의 묶음이 옛 것이면 ✗」였고,"
say "   이 판은 **묶음을 아예 안 보내므로** 거기 있는 것이 **일흔째의 135장짜리이면"
say "   정상**입니다 — ${OLD_MIGTAR_SIZE}바이트 · md5 ${OLD_MIGTAR_MD5}."
say "   🔵 그 값은 **찍기만** 합니다(✗ 를 안 냅니다)."
say "🔴 **여기서 ✗ 를 내는 자리는 하나입니다** — 산출물 폴더에 **묶음이 남아 있는 것**."
say "   🔵 그것이 있으면 사람이 **보낼 것이 셋인 줄 알고** 옛 판을 올립니다"
say "      (쉰여섯째·쉰일곱째가 두 판 연속 그 자리를 밟았습니다)."
if [ -f "$MIGTAR" ]; then
  msz0=$(stat -c %s "$MIGTAR" 2>/dev/null || wc -c < "$MIGTAR")
  mm50=$(md5sum "$MIGTAR" 2>/dev/null | awk '{print $1}')
  say "산출물 폴더에 묶음이 **있습니다** — ${msz0:-?}바이트 · md5 ${mm50:-?}"
  if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
    bad "🔴 **이번 판은 묶음을 안 보냅니다** — 산출물 폴더의 그 파일을 지우세요"
    say "      🔴 두고 보내면 **이미 적용된 판**(또는 더 옛 판)이 볼륨을 덮습니다."
    say "      → rm \"$MIGTAR\""
  elif [ "${mm50:-x}" = "$OLD_MIGTAR_MD5" ]; then
    bad "🔴 그것은 **지난 판의 묶음**입니다 — 이번 것이 아닙니다. 지우고 --go 로 다시 만드세요"
  else
    say "      🔵 --go 는 **지우고 다시 만듭니다** — 지금 값은 참고입니다."
  fi
else
  if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
    ok "산출물 폴더에 묶음이 **없다** (🔵 이번 판은 안 만드는 것이 맞다)"
  else
    say "산출물 폴더에 묶음이 아직 없습니다 — **--go 가 만듭니다**(--check 는 아무것도 안 만듭니다)."
  fi
fi

say ""
say "🔵 **운영이 지금 들고 있어야 하는 수** — $PROD_MIGS_NOTE"
say "   🔴 **개발 PC 에서는 못 잽니다.** 75-deploy.sh --check 가 DB 에 물어 확인하고,"
say "      어긋나면 **거기서 멈춥니다.** 어긋나면 그것은 **이 배포와 무관한 다른 사고**입니다."
say "   🔴 A/S 는 마이그레이션이 **볼륨**에서 돕니다(/volume1/dss/as-migrations) —"
say "      **이미지 안에는 .sql 이 한 장도 없습니다**(5절이 값으로 잽니다). 🔵 그 볼륨은"
say "      일흔째가 이미 $AS_SQL_WANT 장으로 만들어 두었고 **이번 판은 안 건드립니다.**"
say "   🔴 **옛 폴더(_images-58 … _images-74)의 묶음을 보내지 마세요** — 그것들은"
say "      128·129·131·132·134·135장짜리이고, 보내면 **엉뚱한 판이 볼륨을 덮습니다.**"
say "      🔵 **이번 판은 묶음을 아예 안 보냅니다** — 보낼 것은 tar **둘**과 양식 **넷**뿐입니다."
say "   🔵 **재고관리는 반대입니다** — 그 집은 .sql 이 **도구 이미지 안**에서 돕니다."
say "      이번 판은 그 집을 안 구우므로 여기서 셀 자리가 없고, **75-deploy.sh 의"
say "      2-ㄷ-2 가 운영의 그 이미지를 열어 28장을 셉니다**(뒷걸음)."

# ══════════════════════════════════════════════════════════════════════
# ── 5. 🔴 담는 길 · 굽는 까닭 · 소스가 새 코드를 담고 있나 ────────────
# ══════════════════════════════════════════════════════════════════════
step "5. 🔴 담는 길 · 굽는 까닭 · 소스가 새 코드를 담고 있나"

# 5-ㄱ. Dockerfile 이 담는 길
say "── 5-ㄱ. Dockerfile 의 COPY 줄 — 🔴 **drizzle 줄의 기대값이 no 다**"
say "🔴 A/S 의 「drizzle 을 **안 담는다**」는 **볼륨이 정본**이라는 뜻입니다."
say "   🔵 **이번 판은 그 drizzle/ 이 한 줄도 안 바뀝니다**(0건) — 그래서 묶음이 없습니다."
say "   🔴 **그래도 이 줄을 안 뺐습니다** — 1건이 생기는 날 「왜 묶음을 따로 보내야"
say "      하는가」의 근거가 이 줄 하나뿐입니다."
say "   🔵 73번에는 재고 줄 넷이 더 있었고, 거기서는 **drizzle 이 yes · vendor 가 no** 로"
say "      **A/S 와 정반대**였습니다. 🔴 한 줄로 베끼면 둘 중 하나가 **가짜 ✗** 가 됩니다"
say "      (62-build.sh:34-35 의 경고 — 재고를 되살릴 때 73-build.sh:699-709 를 보세요)."
COPY_SEEN=0
while IFS='|' read -r RK RE WANT MSG; do
  [ -n "${RK:-}" ] || continue
  COPY_SEEN=$((COPY_SEEN+1))
  DF="$(repo_dir "$RK")/Dockerfile"
  if [ ! -f "$DF" ]; then bad "$(repo_name "$RK") 의 Dockerfile 이 없다 ($DF)"; continue; fi
  n=$(grep -cE "$RE" "$DF" 2>/dev/null || true)
  ln=$(grep -nE "$RE" "$DF" 2>/dev/null | head -1 | cut -d: -f1)
  if [ "$WANT" = "yes" ]; then
    if [ "${n:-0}" -ge 1 ] 2>/dev/null; then ok "$MSG (${ln:-?}줄)"
    else bad "$(repo_name "$RK") 의 Dockerfile 에 그 COPY 가 **없다** — $MSG"; doubt; fi
  else
    if [ "${n:-1}" = "0" ]; then ok "$MSG"
    else bad "$(repo_name "$RK") 의 Dockerfile 에 그 COPY 가 **있다**(${ln}줄) — $MSG"; doubt; fi
  fi
done <<ENDCOPY
$(rows_of "$COPYRULES")
ENDCOPY
[ "$COPY_SEEN" = "$COPYRULES_WANT" ] && ok "COPY 규칙 ${COPYRULES_WANT}줄을 다 봤다 (표본이 비지 않았다)" \
  || bad "COPY 규칙을 ${COPY_SEEN}줄만 봤다 — ${COPYRULES_WANT}줄을 기대했다. 표가 깨졌다"

# 5-ㄴ. .dockerignore 가 .next 를 막는가 — **집마다**
say ""
say "── 5-ㄴ. .dockerignore 가 .next 를 막는가 — 막아야 dev 서버를 안 내려도 된다"
DI_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  RK=$(field "$r" 1); RN=$(field "$r" 3)
  DI_SEEN=$((DI_SEEN+1))
  DI="$(repo_dir "$RK")/.dockerignore"
  if [ ! -f "$DI" ]; then bad "$RN 에 .dockerignore 가 없다 — 🔴 호스트의 .next 가 섞여 들어간다"; continue; fi
  n=$(grep -c '^\.next' "$DI" 2>/dev/null || true)
  say "$RN 의 .dockerignore 에 ^.next 줄 ${n:-?}개 (기대 1 이상)"
  [ "${n:-0}" -ge 1 ] 2>/dev/null && ok "$RN .dockerignore 가 .next 를 막는다" \
    || bad "$RN .dockerignore 가 .next 를 **안 막는다** — dev 서버를 내리고 구워야 한다"
done <<ENDDI
$(rows_of "$REPOS")
ENDDI
[ "$DI_SEEN" = "$REPOS_WANT" ] && ok ".dockerignore 를 ${REPOS_WANT}집에서 다 봤다" \
  || bad ".dockerignore 를 ${DI_SEEN}집만 봤다"

# 5-ㄷ. 🔴 **굽는 까닭 ㄱ** — npm 명령 수 (집마다)
say ""
say "── 5-ㄷ. 🔴 굽는 까닭 **ㄱ** — npm 명령이 늘었나 (scripts 블록 안만 센다)"
say "🔴 「안 걸린다」도 **값으로 잽니다.** 바뀌었는데 0 으로 적어 두면 다음 판이"
say "   그 거짓을 근거로 「안 구워도 된다」를 꺼냅니다(41번이 Missing script 로 데였습니다)."
NPM_SEEN=0
while IFS='|' read -r RK WAS NOW; do
  [ -n "${RK:-}" ] || continue
  NPM_SEEN=$((NPM_SEEN+1))
  RD=$(repo_dir "$RK"); RN=$(repo_name "$RK"); RB=$(repo_base "$RK")
  a=$(git -C "$RD" show "$RB:package.json" 2>/dev/null </dev/null | count_scripts)
  b=$(count_scripts < "$RD/package.json")
  say "$RN npm 명령 — 기준 ${a:-?} → 지금 ${b:-?} (적어 둔 값 $WAS → $NOW)"
  if [ "${a:-x}" = "$WAS" ] && [ "${b:-x}" = "$NOW" ]; then
    if [ "$WAS" = "$NOW" ]; then ok "$RN npm 명령이 안 늘었다 — **ㄱ 잣대가 안 걸린다**"
    else ok "$RN npm 명령이 $WAS → $NOW 로 늘었다 — 🔴 **ㄱ 잣대가 걸린다**"; fi
  else
    bad "$RN npm 명령이 ${a:-?} → ${b:-?} 다 — $WAS → $NOW 를 기대했다"
    say "      🔴 늘었으면 **도구를 안 구우면 Missing script** 가 납니다."
    doubt
  fi
  pk=$(git -C "$RD" diff --numstat "$RB..main" -- package.json package-lock.json tsconfig.json drizzle.config.ts 2>/dev/null | wc -l | tr -d ' ')
  say "   $RN 의 의존성·설정 파일 넷 중 바뀐 것 ${pk:-?}장 (기대 0)"
  if [ "${pk:-1}" = "0" ]; then
    ok "$RN 의 의존성·설정 파일이 **한 장도 안 바뀌었다**"
  else
    note "$RN 에서 그 넷 중 ${pk}장이 바뀌었다 — 0을 기대했다. **이미지 크기가 뛸 수 있습니다.** 사람이 보세요"
  fi
done <<ENDNPM
$(rows_of "$NPMCOUNT")
ENDNPM
[ "$NPM_SEEN" = "$NPMCOUNT_WANT" ] && ok "npm 명령 수를 ${NPMCOUNT_WANT}집에서 다 봤다" \
  || bad "npm 명령 수를 ${NPM_SEEN}집만 봤다"
say "🔴 **둘 다 strict 로 둔 근거가 위 두 줄입니다** — 라이브러리가 한 개도 안 늘었습니다."
say "   🔵 A/S 는 명령이 **39개**이고 그 안에 **db:preflight 와 check:* 가 있습니다** —"
say "      75-deploy.sh 의 --migrate 가 그 집에서 **db:preflight 를 돌려 대기 0건**을"
say "      값으로 받는 까닭입니다(🔵 74번은 **1건**이 기대값이었습니다). 🔴 명령이 없는"
say "      집(재고 17개)에 그것을 부르면 **Missing script** 로 멈춥니다(41번의 그 실패)."
# 🔵 뒷걸음 — 쉰여덟째가 더한 heic2any 가 그대로 있는가(빠지면 아이폰 사진이 다시 막힌다)
n=$(grep -c '"heic2any"' "$ASD/package.json" 2>/dev/null || true)
say "heic2any (쉰여덟째가 더한 것) — ${n:-?}줄 (기대 1)"
[ "${n:-x}" = "1" ] && ok "heic2any 가 그대로 있다 (뒷걸음친 나무가 아니다)" \
  || bad "heic2any 가 ${n:-?}줄이다 — 1 을 기대했다"

# 5-ㄹ. 🔴 **굽는 까닭 ㄴ·ㄷ·ㄹ**
say ""
say "── 5-ㄹ. 🔴 굽는 까닭 **ㄴ** — tools 가 담는 것 중 바뀐 파일"
AS_LIST=$(git -C "$ASD" diff --name-only "$(repo_base as)..main" 2>/dev/null | tr -d '\r')
# 🔵 **INV_LIST 가 없다** — 재고가 이번 판에 없다(머리말 「왜 없는가」 ①).
#    🔴 **고리와 case 꼴은 그대로 뒀다** — 집이 다시 둘이 되는 날 줄만 더하면 된다.
PAY_SEEN=0
while IFS='|' read -r RK WANT; do
  [ -n "${RK:-}" ] || continue
  PAY_SEEN=$((PAY_SEEN+1))
  RN=$(repo_name "$RK")
  # 🔴 **정규식은 표가 아니라 스칼라에서 꺼낸다**(그 까닭은 표 주석에).
  RE=$(payload_re "$RK")
  if [ -z "${RE:-}" ]; then
    bad "$RN 의 담기는 길 정규식을 못 꺼냈다 — payload_re 에 그 열쇠가 없다"
    continue
  fi
  # 🔴 **잣대부터 잰다** — 정규식이 깨져 있으면 아래 수가 통째로 거짓이 된다.
  #    [실측 2026-11-25] 처음 판은 여기가 없어서 깨진 정규식이 ⚠️ 로만 새어 나왔다.
  ph=$(printf '%s\n' "$PAYLOAD_PROBE_HIT" | grep -cE "$RE" 2>/dev/null || true)
  pm=$(printf '%s\n' "$PAYLOAD_PROBE_MISS" | grep -cE "$RE" 2>/dev/null || true)
  say "$RN 잣대 표본 — [$PAYLOAD_PROBE_HIT] ${ph:-?}(기대 1) · [$PAYLOAD_PROBE_MISS] ${pm:-?}(기대 0)"
  if [ "${ph:-x}" = "1" ] && [ "${pm:-x}" = "0" ]; then
    ok "$RN 의 담기는 길 정규식이 **살아 있다** (아래 수를 믿을 수 있다)"
  else
    bad "$RN 의 정규식이 **깨졌다** — 표본이 ${ph:-?}·${pm:-?} 다 (1·0 을 기대했다)"
    say "      🔴 grep 이 Unmatched ( 로 죽으면 아래 수가 **?** 가 됩니다 — 그 꼴을"
    say "         이 줄이 먼저 잡습니다(2026-11-25 에 실제로 그 일이 있었습니다)."
    doubt
    continue
  fi
  case "$RK" in
    as) L="$AS_LIST" ;;
    *)  L="" ;;
  esac
  all=$(printf '%s\n' "$L" | grep -c . || true)
  pay=$(printf '%s\n' "$L" | grep -cE "$RE" || true)
  say "$RN — tools 가 담는 것 중 바뀐 파일 ${pay:-?} / ${all:-?} 장 (적어 둔 값 $WANT)"
  if [ "${pay:-x}" = "$WANT" ]; then
    if [ "${pay:-0}" -ge 1 ] 2>/dev/null; then
      ok "🔴 $RN 의 **ㄴ 잣대가 걸린다** — ${pay}장이 도구 이미지 안으로 들어간다"
    else
      ok "$RN 의 ㄴ 잣대가 안 걸린다 (도구가 담는 것 중 바뀐 것이 0장이다)"
    fi
  else
    note "$RN 의 ㄴ 수가 ${pay:-?} 다 — $WANT 을 기대했다. **사람이 보세요**"
    say "      🔵 커밋이 하나 더 밀렸으면 여기가 먼저 어긋납니다(2절의 ⚠️ 와 짝입니다)."
  fi
done <<ENDPAY
$(rows_of "$TOOLS_PAYLOAD")
ENDPAY
[ "$PAY_SEEN" = "$TOOLS_PAYLOAD_WANT" ] && ok "ㄴ 잣대를 ${TOOLS_PAYLOAD_WANT}집에서 다 봤다" \
  || bad "ㄴ 잣대를 ${PAY_SEEN}집만 봤다"
say "🔵 **이번 판은 빠지는 것이 하나도 없습니다** — **40 중 40** 입니다."
say "   · **drizzle/ 0장** — 이 범위에 그 폴더가 안 바뀌었습니다(74번은 3장이 빠졌습니다)."
say "   · **현황판 HTML 0장** — 이 범위에 그 파일이 없습니다(71·73·74번은 1장이 빠졌습니다)."
say "   🔴 **그 둘이 1 이상이 되는 날 「빠지는 것」을 결함으로 읽지 마세요** — A/S tools 는"
say "      drizzle/ 을 **안 담고**(5-ㄱ), 현황판 HTML 은 **어느 COPY 에도 안 걸립니다.**"
say "   🔵 73번에는 **재고의 「39 중 26」**(tests/ 12장과 API.md 를 .dockerignore 가"
say "      막는다)이 함께 적혀 있었습니다 — 되살릴 때 69번의 그 글도 함께 보세요."

say ""
say "ㄷ) 🔵 **도구의 import 닫힘** — 🔴 **이번 판에도 안 걸린다.** 잣대만 재 둔다"
say "🔴 **그래도 절을 빼지 않습니다** — 빼면 다음 판이 「ㄷ 는 원래 없는 절」로 읽고,"
say "   그 둘이 옛 몸통으로 도는 사고를 아무도 못 잡습니다."
IMP_SEEN=0; IMP_OK=0
tn=$(printf '%s\n' "$AS_LIST" | grep -cFx "$TOOL_IMPORT_TARGET" || true)
say "바뀐 목록에 $TOOL_IMPORT_TARGET 이 ${tn:-?}줄 (기대 $TOOL_IMPORT_TARGET_WANT)"
if [ "${tn:-x}" = "$TOOL_IMPORT_TARGET_WANT" ]; then
  ok "그 모듈이 **이번 범위에 ${TOOL_IMPORT_TARGET_WANT}줄이다** — ㄷ 잣대는 안 걸린다"
else
  note "그 모듈이 바뀐 목록에 ${tn:-?}줄이다 — $TOOL_IMPORT_TARGET_WANT 을 기대했다. **사람이 보세요**"
  say "      🔵 1 이면 ㄷ 가 되살아난 것이라 **굽는 까닭이 하나 더 는 것**입니다 —"
  say "         그래서 ⚠️ 로만 셉니다(막을 일이 아닙니다)."
fi
while IFS='|' read -r F IMP; do
  [ -n "${F:-}" ] || continue
  IMP_SEEN=$((IMP_SEEN+1))
  if [ ! -f "$ASD/$F" ]; then bad "$F 가 없다 — 표가 틀렸다"; continue; fi
  n=$(grep -cF -- "$IMP" "$ASD/$F" 2>/dev/null || true)
  printf '      %-48s [%s] %s줄\n' "$F" "$IMP" "${n:-?}"
  if [ "${n:-0}" -ge 1 ] 2>/dev/null; then IMP_OK=$((IMP_OK+1))
  else bad "$F 가 그 모듈을 안 부른다 — 표가 틀렸다"; fi
done <<ENDIMP
$(rows_of "$TOOL_IMPORTERS")
ENDIMP
say "본 것 ${IMP_SEEN} · 부르는 것 ${IMP_OK} (기대 $TOOL_IMPORTERS_WANT · $TOOL_IMPORTERS_WANT)"
if [ "$IMP_SEEN" = "$TOOL_IMPORTERS_WANT" ] && [ "$IMP_OK" = "$TOOL_IMPORTERS_WANT" ]; then
  ok "ㄷ 잣대가 **살아 있다** — 도구 스크립트 ${IMP_OK}장이 아직 그 모듈을 부른다"
else
  bad "본 것 ${IMP_SEEN} · 부르는 것 ${IMP_OK} 다 — ${TOOL_IMPORTERS_WANT} 을 기대했다"
  doubt
fi

say ""
say "ㄹ) 🔴 **공용 스키마(vendor/*)가 움직였나** — 🔵 **이번에는 안 걸린다**"
say "   🔵 3-ㄴ 과 **같은 값을 여기서 다시 셉니다** — 3절은 「포인터가 움직였는가」를,"
say "      여기는 「**굽는 까닭이 되는가**」를 말합니다. 뜻이 다르면 질의도 따로 두는"
say "      것이 이 저장소의 규율입니다. 🔴 **절을 빼지 않았습니다.**"
ven0=$(printf '%s\n' "$AS_LIST" | grep -cE '^(vendor/|\.gitmodules)' || true)
say "   A/S 의 vendor/ · .gitmodules ${ven0:-?}줄 (기대 $CH_VENDOR)"
if [ "${ven0:-x}" = "$CH_VENDOR" ]; then
  if [ "${ven0:-0}" -ge 1 ] 2>/dev/null; then
    ok "🔴 **ㄹ 잣대가 걸린다** — 공용 스키마가 움직였다"
    say "      🔴 **도구를 안 구우면 옛 스키마로 db:migrate 를 돌리게 됩니다.**"
  else
    ok "ㄹ 잣대가 **안 걸린다** (공용 스키마가 안 움직였다 — 73번과 같다)"
    say "      🔵 그래도 **도구는 굽습니다** — ㄴ 하나로 충분합니다(40장)."
    say "      🔵 그리고 **옛 핀으로 되감기지 않았는지**는 3-ㄱ 이 따로 쟀습니다."
  fi
else
  bad "A/S 의 vendor/ 변경이 ${ven0:-?}줄이다 — $CH_VENDOR 을 기대했다"
  doubt
fi
say "   그 핀이 origin 에 올라가 있나: ${CORE_ORIGIN_OK:-0} (기대 1 — 3-ㄴ 에서 쟀다)"
[ "${CORE_ORIGIN_OK:-0}" = "1" ] && ok "지금 핀의 커밋이 **origin 에도 있다** (다른 PC 가 같은 이미지를 만들 수 있다)" \
  || bad "그 커밋이 origin 에 없다 — **이 PC 에서만 되는 이미지가 된다.** 3-ㄴ 을 보세요"
say ""
say "ㅁ) 🔵 **마이그레이션이 0건이다** — 4절이 값으로 쟀다"
say "   🔵 **그래서 이 파일은 묶음을 안 만듭니다.** 🔴 **그 절을 지우지는 않았습니다** —"
say "      「셋째 산출물」 자리가 그대로 있고, AS_NEW_MIGS_WANT 가 0 이라 **안 만들고**"
say "      대신 **산출물 폴더에 옛 묶음이 섞여 있지 않은지**를 잽니다."
say "   🔴 A/S tools 가 drizzle/ 을 **안 담는다**는 사실(5-ㄱ)은 그대로입니다 —"
say "      운영에서는 /app/drizzle 에 **볼륨**이 붙고, 그 볼륨은 **이미 $AS_SQL_WANT 장**입니다."
say "      🔴 1건이라도 생기면 **묶음을 안 보낼 때 db:migrate 가 0건으로 조용히 끝나고**"
say "         겉으로는 성공으로 보입니다(31·39번이 겪었습니다)."
say "   🔵 **재고는 그 반대입니다** — .sql 이 **도구 이미지 안에** 구워져 갑니다."
say "      거기 마이그레이션이 생기는 판에서는 **묶음이 아니라 도구 태그**를 올립니다."
say ""
say "🔴 **결론: 둘을 굽는다. 묶음은 안 만든다.**"
say "   · **ㄴ(40장) 하나가 걸립니다.**"
say "     ㄱ(npm 명령 39→39) · ㄷ(import 닫힘) · ㄹ(공용 스키마) · ㅁ(마이그레이션 0건)은"
say "     **안 걸립니다.**"
say "   🔴 **도구를 꼭 굽습니다** — src/ **39장**이 도구 이미지 안으로 들어가고, 그 안에서"
say "      db:preflight·check:* 가 **그 소스로** 돕니다. 안 구우면 운영의 도구가"
say "      **옛 몸통**으로 돕니다."
say "   🔵 반대 방향의 사고도 이 저장소에 적혀 있습니다 — 「마이그레이션 0건이니"
say "      도구는 안 굽는다」가 틀려 비상구 둘을 못 올린 적이 있고, 이튿날에는"
say "      거꾸로 「명령이 늘어난 것」을 놓쳐 Missing script 가 났습니다."

# 5-ㅁ. 바뀐 파일 수
say ""
say "── 5-ㅁ. 바뀐 파일 수 (🔴 2절의 ⚠️ 와 짝인 자리다)"
CH_SEEN=0
while IFS='|' read -r RK WALL WSRC WSCR WDRZ WVEN WNEW WDEL WPAR WBRK WTST; do
  [ -n "${RK:-}" ] || continue
  CH_SEEN=$((CH_SEEN+1))
  RD=$(repo_dir "$RK"); RN=$(repo_name "$RK"); RB=$(repo_base "$RK")
  case "$RK" in
    as) L="$AS_LIST" ;;
    *)  L="" ;;
  esac
  all=$(printf '%s\n' "$L" | grep -c . || true)
  src=$(printf '%s\n' "$L" | grep -c '^src/' || true)
  scr=$(printf '%s\n' "$L" | grep -c '^scripts/' || true)
  drz=$(printf '%s\n' "$L" | grep -c '^drizzle/' || true)
  ven=$(printf '%s\n' "$L" | grep -cE '^(vendor/|\.gitmodules)' || true)
  par=$(printf '%s\n' "$L" | grep -cF '(' || true)
  brk=$(printf '%s\n' "$L" | grep -cF '[' || true)
  tst=$(printf '%s\n' "$L" | grep -cE '\.test\.tsx?$' || true)
  new=$(git -C "$RD" diff --diff-filter=A --name-only "$RB..main" 2>/dev/null | grep -c . || true)
  del=$(git -C "$RD" diff --diff-filter=D --name-only "$RB..main" 2>/dev/null | grep -c . || true)
  printf '      %-10s 전체 %-4s src %-4s scripts %-3s drizzle %-3s vendor %-2s 새 %-3s 지움 %-2s 괄호 %-2s 대괄호 %-2s 시험 %s\n' \
    "$RN" "${all:-?}" "${src:-?}" "${scr:-?}" "${drz:-?}" "${ven:-?}" "${new:-?}" "${del:-?}" "${par:-?}" "${brk:-?}" "${tst:-?}"
  printf '      %-10s (적어 둔 값) %-4s     %-4s         %-3s         %-3s        %-2s    %-3s      %-2s      %-2s        %-2s      %s\n' \
    "" "$WALL" "$WSRC" "$WSCR" "$WDRZ" "$WVEN" "$WNEW" "$WDEL" "$WPAR" "$WBRK" "$WTST"
  if [ "${all:-x}" = "$WALL" ] && [ "${src:-x}" = "$WSRC" ] && [ "${scr:-x}" = "$WSCR" ] \
     && [ "${drz:-x}" = "$WDRZ" ] && [ "${ven:-x}" = "$WVEN" ] && [ "${new:-x}" = "$WNEW" ] \
     && [ "${par:-x}" = "$WPAR" ] && [ "${brk:-x}" = "$WBRK" ] && [ "${tst:-x}" = "$WTST" ]; then
    ok "$RN 바뀐 파일 수가 적어 둔 것과 전부 같다"
  else
    note "$RN 바뀐 파일 수가 적어 둔 것과 다르다 — **사람이 보세요**"
    say "      🔴 **2절에서 커밋 수가 어긋났고 여기까지 어긋나면 멈추세요** — 그때는"
    say "         **코드가 더 밀린 것**이고, 아래 표식 기대값이 전부 그 범위에서 나온"
    say "         값이라 함께 어긋납니다."
  fi
  if [ "${del:-1}" = "$WDEL" ]; then ok "$RN 지운 파일 ${WDEL}장"
  else bad "🔴 $RN 이 파일을 ${del}장 **지웠다** — $WDEL 을 기대했다. 멈추고 알릴 것"; fi
done <<ENDCH
$(rows_of "$CHANGED")
ENDCH
[ "$CH_SEEN" = "$CHANGED_WANT" ] && ok "바뀐 파일 수를 ${CHANGED_WANT}집에서 다 봤다" \
  || bad "바뀐 파일 수를 ${CH_SEEN}집만 봤다"
say "🔵 **이번 범위에는 괄호가 4장 · 대괄호가 3장 있습니다**(74번은 괄호 0 · 대괄호 3):"
say "   괄호가 든 경로(아래 — **넷입니다**):"
printf '%s\n' "$AS_LIST" | grep -F '(' | sed 's/^/        /'
say "   대괄호가 든 경로(아래 — **셋입니다** · 넷 중 셋이 괄호와 겹칩니다):"
printf '%s\n' "$AS_LIST" | grep -F '[' | sed 's/^/        /'
say "   🔴 **그 셈을 빼지 않았습니다** — 67번이 0 이었는데 안 빼서 68번의 [id] 를"
say "      잡았습니다. 🔵 **이번에는 둘 다 범위 안에 있습니다** — 그래서 AS_KEY_FILES 의"
say "      글롭 잣대 **셋이 전부 이번에 바뀐 파일**입니다(74번은 둘을 범위 밖에서"
say "      끌어왔습니다)."
say "   🔴🔴 **시험 목록 파일에서는 대괄호를 별표로 적습니다** — 🔵 **이번 범위에는 그"
say "      실물이 없습니다.** 🔴 그래도 5-ㅇ 의 그 절을 **안 뺐습니다** — 범위 **밖**의"
say "      실물 하나를 잣대로 그대로 묻습니다. 이미지 안에서 [ -f ] 로 묻는 자리와는"
say "      **꼴이 다릅니다.**"
say "   🔵 목록을 넘기는 길은 here 문서 + grep -Fx 로만 썼고 컨테이너 안에서는"
say "      set -f 로 글롭을 끕니다."

# 5-ㅂ. 🔴 표식 — 소스에서 먼저 센다
say ""
say "── 5-ㅂ. 🔴 표식 — **소스에서 먼저 센다** (기능 0→N · 뒷걸음 N→N · 곁들이는 찍기만)"
say "🔵 **이번 기능 표식은 넷이고 전부 ASCII** 입니다(74번은 넷이 전부 한글) —"
say "   문자열 리터럴 하나(권한 열쇠)와 **객체 칸 이름 셋**입니다."
say "   🔵 칸 이름은 minify 가 안 줄입니다(property mangling 이 꺼져 있습니다) —"
say "      71번이 번들에서 shareDocRelativePath 23 · faultTags 19 를 센 것이 그 증거입니다."
say "🔴 **「마지막 커밋의 글자」를 넣었습니다** — [remarkAlign]·[labelPx]·[remarkFitPx] 가"
say "   전부 f0e3f957(**마지막 커밋**)의 것입니다. 🔴 그것이 0 이면 **커밋 하나가 빠진"
say "   판**을 구운 것입니다."
say "🔵 **ㄱ 갈래(권한)도 번들 표식이 있습니다** — technicalProcedures.create 는 **열쇠"
say "   문자열**이라 번들에 글자 그대로 남습니다(74번의 DATA 갈래와 다릅니다)."
say "🔴 **export 이름은 곁들이로만 둡니다** — 웹팩이 production 에서 줄입니다."
say "🔴 **아래 수는 전부 소스에서 센 값입니다** — 번들 수는 --go 가 처음 찍습니다."
MK_SEEN=0; MK_FEAT=0; MK_KEEP=0; MK_SIDE=0
while IFS='|' read -r RK KIND MK NOTE1; do
  [ -n "${RK:-}" ] || continue
  MK_SEEN=$((MK_SEEN+1))
  RD=$(repo_dir "$RK"); RN=$(repo_name "$RK"); RB=$(repo_base "$RK")
  a=$(mark_was "$RD" "$RB" "$MK"); b=$(mark_now "$RD" "$MK")
  printf '      %-10s %-7s %-44s 기준 %-4s → 지금 %-4s  (%s)\n' "$RN" "$KIND" "[$MK]" "${a:-?}" "${b:-?}" "$NOTE1"
  case "$KIND" in
    feature)
      MK_FEAT=$((MK_FEAT+1))
      if [ "${a:-x}" = "0" ] && [ "${b:-0}" -ge 1 ] 2>/dev/null; then
        ok "$RN 기능 표식 [$MK] 이 **이번 판에만 있다**"
      else
        bad "$RN 기능 표식 [$MK] 이 기준 ${a:-?} → 지금 ${b:-?} 다 — 0 → 1 이상을 기대했다"
        say "      🔴 기준판에도 있으면 그 표식은 **아무것도 안 가릅니다.**"
        doubt
      fi
      ;;
    keep)
      MK_KEEP=$((MK_KEEP+1))
      if [ "${a:-0}" -ge 1 ] 2>/dev/null && [ "${b:-0}" -ge 1 ] 2>/dev/null; then
        ok "$RN 뒷걸음 표식 [$MK] 이 기준에도 지금에도 있다 (뒷걸음을 잴 수 있다)"
      else
        bad "$RN 뒷걸음 표식 [$MK] 이 기준 ${a:-?} · 지금 ${b:-?} 다 — 둘 다 1 이상이어야 한다"
        doubt
      fi
      ;;
    side)
      MK_SIDE=$((MK_SIDE+1))
      say "      🔵 **판정에 안 씁니다** — 번들에서 함께 찍어 ✗ 의 까닭을 가르는 데만 씁니다."
      ;;
  esac
done <<ENDMK
$(rows_of "$APPMARKS")
ENDMK
say "본 표식 ${MK_SEEN} (기대 $MARKS_WANT) · 기능 ${MK_FEAT}(기대 $MARKS_FEATURE_WANT) · 뒷걸음 ${MK_KEEP}(기대 $MARKS_KEEP_WANT) · 곁들이 ${MK_SIDE}(기대 $MARKS_SIDE_WANT)"
if [ "$MK_SEEN" = "$MARKS_WANT" ] && [ "$MK_FEAT" = "$MARKS_FEATURE_WANT" ] \
   && [ "$MK_KEEP" = "$MARKS_KEEP_WANT" ] && [ "$MK_SIDE" = "$MARKS_SIDE_WANT" ]; then
  ok "표식 ${MARKS_WANT}개를 갈래별로 다 봤다 (표본이 비지 않았다)"
else
  bad "표식 수가 어긋난다 — APPMARKS 표가 깨졌다"
fi
say "🔵 뒷걸음 표식이 **열여덟**인 까닭: 지난 판들이 올린 글자를 하나씩 잡고 있습니다 —"
say "   **하나도 빼지 마세요.**"
say "🔴🔴 **이번에 넷이 늘었습니다** — 74번의 기능 표식 [폴더 이름 (선택)] ·"
say "   [폴더 이름에 경로 글자] · [확장자는 원본과 같게 유지됩니다] · [파일 이름에 경로"
say "   글자] 가 어제 올라가 오늘은 「있다」가 아무것도 안 가르므로 **뒷걸음으로"
say "   내렸습니다**(기준 8·1·1·1 → 지금 8·1·1·1)."
say "   🔴 **넷을 다 내린 까닭**: 그 넷이 **KO 경계를 재는 표본**(1-ㄷ 의 여덟 중 넷)이고,"
say "      되감긴 날 그 기능이 통째로 사라지는 것을 잡는 자리가 여기뿐입니다."
say "🔴 그중 [도번 / 비고] 도 **한글입니다**(예순여섯째가 올린 것)."
say "   🔴 71번이 그 자리에서 데었습니다 — ASCII 로 쓰려고 같은 커밋의"
say "      part.drawingNo, part.note 를 골랐는데, 그것은 70번의 **도구 이미지용**"
say "      표식이라 **번들에서 0/0** 이었습니다(part 가 지역 이름이라 minify 가"
say "      갈아 치웁니다). [실측 2026-11-25 · dss-as:6.2]"
say "   🔵 한글이 경계를 건너가는지는 **1-ㄷ 절이 바이트로** 쟀습니다(이번엔 여덟)."

# 5-ㅅ. 🔴 도구 이미지용 표식 — **넷 (두 갈래를 다 가린다)**
say ""
say "── 5-ㅅ. 🔴 **도구 이미지용 표식 넷** — 두 갈래를 다 가린다 · 소스에서 먼저 센다"
say "🔴 도구에는 소스가 **글자 그대로** 들어 있어 minify 를 안 탑니다 — 번들에서"
say "   「없다」가 「코드가 없다」와 같은 말이 아니므로 **여기서 한 번 더** 가릅니다."
say "🔴 **기준에 0줄이었다는 것도 git 에서 직접 셉니다**(적어 둔 값을 안 믿습니다)."
say "🔴 **과녁 넷 다 기준판에도 있던 파일**입니다 — 새로 생긴 파일을 과녁으로 삼으면"
say "   「기준 0줄」이 **파일이 없어서 0** 인 것이라 아무것도 안 가릅니다."
say "   🔵 그래서 새 파일 둘(excel-column-width.ts ·"
say "      technical-procedure-settings-gate.test.ts)은 과녁으로 안 쓰고 **짝**으로 둡니다."
say "🔵 **둘째 줄이 export 이름**입니다 — 도구 이미지에는 소스가 그대로 있어 여기서는"
say "   안전합니다(번들이었으면 mangleExports 때문에 못 씁니다)."
say "🔵 넷째 과녁은 **괄호와 대괄호가 함께 든 경로**입니다 — 이미지 안에서도 글롭 잣대가 됩니다."
TM_SEEN=0
while IFS='|' read -r TK MK FILE WAS_WANT NOW_WANT; do
  [ -n "${TK:-}" ] || continue
  TM_SEEN=$((TM_SEEN+1))
  RK=$(repo_key_of "$TK")
  RD=$(repo_dir "$RK"); RN=$(repo_name "$RK"); RB=$(repo_base "$RK")
  if [ ! -f "$RD/$FILE" ]; then bad "$RN — $FILE 이 없다 (표식을 둘 자리가 없다)"; continue; fi
  # 🔴 **과녁 파일이 기준판에도 있었는가** — 없었으면 「기준 0줄」이 공짜 ✓ 다.
  if git -C "$RD" cat-file -e "$RB:$FILE" 2>/dev/null; then
    ok "$RN 의 과녁 파일이 **기준판에도 있었다** (「기준 0줄」이 공짜 ✓ 가 아니다)"
  else
    bad "$RN 의 과녁 파일이 기준판에 **없었다** — 그러면 기준 0줄은 아무것도 안 가른다"
    say "      🔴 기준판에도 있던 파일을 과녁으로 고르세요."
    doubt
  fi
  was=$(git -C "$RD" show "$RB:$FILE" 2>/dev/null </dev/null | grep -cF -- "$MK" || true)
  n=$(grep -cF -- "$MK" "$RD/$FILE" 2>/dev/null || true)
  say "$RN [$MK] in $FILE — 기준 ${was:-?}줄 → 지금 ${n:-?}줄 (기대 $WAS_WANT → $NOW_WANT)"
  if [ "${was:-x}" = "$WAS_WANT" ]; then
    ok "$RN 의 그 파일 안에서는 기준판에 **${WAS_WANT}줄**이었다 (이 표식이 판을 **가른다**)"
  else
    bad "$RN 의 기준판 그 파일에 그 글자가 ${was:-?}줄 있다 — $WAS_WANT 을 기대했다"
    say "      🔴 0 이 아니면 그 표식은 **이 판을 안 가릅니다.** 다른 글자를 고르세요."
    doubt
  fi
  if [ "${n:-x}" = "$NOW_WANT" ]; then ok "$RN 의 도구 표식이 그 파일에 ${n}줄 있다"
  elif [ "${n:-0}" -ge 1 ] 2>/dev/null; then note "$RN 에서 그 글자가 ${n}줄이다 — $NOW_WANT 을 기대했다. 사람이 보세요"
  else bad "$RN 의 도구 표식이 그 파일에 **없다** — 표가 틀렸다"; fi
done <<ENDTM
$(rows_of "$TOOLMARKS")
ENDTM
[ "$TM_SEEN" = "$TOOLMARKS_WANT" ] && ok "도구 표식 ${TOOLMARKS_WANT}개를 다 봤다 (두 갈래를 다 가렸다)" \
  || bad "도구 표식을 ${TM_SEEN}개만 봤다 — ${TOOLMARKS_WANT}개를 기대했다. TOOLMARKS 표가 깨졌다"
# 🔴 그 표식이 가리키는 **짝 파일**이 작업본에 있는가
TP_SEEN=0
while IFS='|' read -r TK PF; do
  [ -n "${TK:-}" ] || continue
  TP_SEEN=$((TP_SEEN+1))
  RD=$(repo_dir "$(repo_key_of "$TK")")
  if [ -f "$RD/$PF" ]; then ok "짝 파일이 작업본에 있다 ($PF)"
  else bad "$PF 이 작업본에 **없다** — 화면이 import 에서 죽는다"; fi
done <<ENDTP
$(rows_of "$TOOLMARK_PAIRS")
ENDTP
[ "$TP_SEEN" = "$TOOLMARK_PAIRS_WANT" ] && ok "짝 파일 ${TOOLMARK_PAIRS_WANT}장을 다 봤다" \
  || bad "짝 파일을 ${TP_SEEN}장만 봤다 — ${TOOLMARK_PAIRS_WANT}장을 기대했다"
say "🔵 **짝 파일 둘은 전부 이번에 생긴 새 파일**입니다 — 과녁(옛 파일)이 「새 글자가"
say "   들어왔는가」를 재고, 짝이 「**새 파일이 담겼는가**」를 잽니다. 🔴 새 파일이"
say "   빠지면 도구와 앱이 **import 에서 죽습니다.**"
# 🔴🔴 **일흔째가 지운 파일이 아직도 없는가** — 🔵 이번 판은 지운 파일이 0장이라
#    뜻이 **뒷걸음**으로 바뀐다. 🔵 **같은 줄에서 반대쪽도 센다** — 대신 선 파일은 있어야 한다.
say ""
say "   🔴🔴 **일흔째가 지운 둘이 아직도 없는가** (🔵 이번 판은 지운 파일이 0장이다)"
say "      🔴 표를 **안 뺐습니다** — 되살아나는 날 잡는 자리가 여기와 이미지 안 둘뿐입니다."
TG_SEEN=0; TG_OK=0
while IFS='|' read -r TK GF RF; do
  [ -n "${TK:-}" ] || continue
  TG_SEEN=$((TG_SEEN+1))
  RD=$(repo_dir "$(repo_key_of "$TK")")
  g=no; [ -f "$RD/$GF" ] && g=yes
  r2=no; [ -f "$RD/$RF" ] && r2=yes
  printf '      지운 것 [%s] %s (기대 no) · 대신 선 것 [%s] %s (기대 yes)\n' "$GF" "$g" "$RF" "$r2"
  if [ "$g" = "no" ] && [ "$r2" = "yes" ]; then
    TG_OK=$((TG_OK+1))
  elif [ "$g" = "yes" ]; then
    bad "$GF 이 **작업본에 되살아났다** — 일흔째가 지운 파일이다. 사람이 보세요"
    doubt
  else
    bad "$RF 이 **작업본에 없다** — 지운 자리를 대신할 파일이 없다"
    doubt
  fi
done <<ENDTG
$(rows_of "$TOOLMARK_GONE")
ENDTG
say "   본 것 ${TG_SEEN} · 맞는 것 ${TG_OK} (기대 $TOOLMARK_GONE_WANT · $TOOLMARK_GONE_WANT)"
[ "$TG_SEEN" = "$TOOLMARK_GONE_WANT" ] && [ "$TG_OK" = "$TOOLMARK_GONE_WANT" ] \
  && ok "일흔째가 지운 ${TOOLMARK_GONE_WANT}장이 **아직도 없고** 대신 선 파일이 다 있다" \
  || bad "본 것 ${TG_SEEN} · 맞는 것 ${TG_OK} 다 — ${TOOLMARK_GONE_WANT} 을 기대했다"
say "   🔵 **이미지 안에서도 같은 것을 묻습니다**(inside_check 의 astools 가지) —"
say "      작업본에서 없어진 것이 **이미지에도 없는지**는 다른 질문입니다."
# 5-ㅇ. 🔴🔴 시험 등록 — **A/S 는 목록 파일이다. 적어야 돈다**
say ""
say "── 5-ㅇ. 🔴🔴 시험 등록 — **A/S 는 목록 파일이다**(scripts/test-lists/*.txt)"
say "🔴 **방식이 저장소마다 다릅니다.** 한 집의 방식을 다른 집에 베끼면 그 집의"
say "   시험 등록이 **아무 검사도 안 받습니다.**"
say "   🔵 73번에는 여기에 **재고의 글롭 절(ㄴ)**이 더 있었습니다 — 그 집은 적을 목록이"
say "      없고 **「글롭이 닿는 자리에 있는가」**를 재야 합니다(73-build.sh:2137-2221)."
say "   🔵 71번에는 **포털 절**이 있었습니다 — package.json 의 test 줄에 **경로를"
say "      나열**하는 **또 다른 셋째 방식**입니다. 🔴 되살릴 때 베껴 쓰지 마세요."
say "🔴 적어야 도는 방식이라 **빠뜨리면 그 시험은 오류 없이 조용히 안 돕니다.**"
TL=$(cat "$ASD"/scripts/test-lists/*.txt 2>/dev/null | tr -d '\r')
lines=$(printf '%s\n' "$TL" | grep -c . || true)
TLBASE=0; TLB_SEEN=0
while IFS= read -r f; do
  [ -n "$f" ] || continue
  TLB_SEEN=$((TLB_SEEN+1))
  n=$(git -C "$ASD" show "$(repo_base as):$f" 2>/dev/null </dev/null | tr -d '\r' | grep -c . || true)
  isnum "${n:-}" || n=0
  TLBASE=$((TLBASE + n))
done <<ENDTLB
$(rows_of "$AS_TESTLIST_FILES")
ENDTLB
say "목록 줄 수 — 기준 ${TLBASE} (본 파일 ${TLB_SEEN}장) → 지금 ${lines:-?} (적어 둔 값 $AS_TESTLIST_LINES_WAS → $AS_TESTLIST_LINES_WANT)"
if [ "$TLB_SEEN" != "$AS_TESTLIST_FILES_WANT" ]; then
  bad "기준판 목록을 ${TLB_SEEN}장만 봤다 — ${AS_TESTLIST_FILES_WANT}장을 기대했다"
fi
if ! isnum "${lines:-}" || [ "${lines:-0}" -lt "$AS_TESTLIST_MIN_LINES" ]; then
  bad "목록을 ${lines:-못 읽음}줄밖에 못 읽었다 — 🔴 **빈 결과는 삼켜진 오류일 수 있다.** 아래를 못 믿는다"
elif [ "${TLBASE:-0}" -lt "$AS_TESTLIST_MIN_LINES" ]; then
  bad "기준판 목록이 ${TLBASE}줄이다 — git show 가 비었을 수 있다. 아래를 못 믿는다"
elif [ "${lines}" -lt "${TLBASE}" ]; then
  bad "목록이 ${TLBASE} → ${lines} 로 **줄었다** — 🔴 누가 시험 등록을 **지웠다**"
  say "      🔴 등록이 빠지면 그 시험은 **오류 없이 조용히 안 돕니다.** 멈추고 알리세요."
  say "      🔵 **이번 판은 시험을 한 장도 안 지웠습니다** — 줄면 그것 자체가 결함입니다."
elif [ "${lines}" = "${TLBASE}" ]; then
  bad "목록 줄 수가 ${lines} **그대로다** — 새 시험이 ${AS_NEW_TESTS_WANT}장인데 한 줄도 안 늘었다"
  say "      🔴 **등록이 통째로 빠졌습니다.** 그 하나는 조용히 안 돕니다."
  doubt
else
  ok "목록이 ${TLBASE} → ${lines} 로 **늘었다** (새 시험 ${AS_NEW_TESTS_WANT}장이 등록된 꼴이다)"
  say "      🔴 **줄 수만으로는 「등록됐다」를 말할 수 없습니다** — 이 저장소의 목록"
  say "         파일은 **까닭을 적은 주석**도 담습니다(이번에 늘어난 6줄 중 시험 경로는"
  say "         **하나**뿐이고 다섯은 **주석**입니다). 아래가 **경로를 하나씩** 묻습니다."
  [ "${lines}" = "$AS_TESTLIST_LINES_WANT" ] && ok "적어 둔 값 $AS_TESTLIST_LINES_WANT 과도 같다" \
    || note "적어 둔 값은 $AS_TESTLIST_LINES_WANT 인데 ${lines} 다 — 사람이 보세요"
  [ "${TLBASE}" = "$AS_TESTLIST_LINES_WAS" ] && ok "기준판 줄 수도 적어 둔 값 $AS_TESTLIST_LINES_WAS 과 같다" \
    || note "기준판이 ${TLBASE}줄이다 — $AS_TESTLIST_LINES_WAS 을 기대했다. 사람이 보세요"
fi
nt=$(git -C "$ASD" diff --diff-filter=A --name-only "$(repo_base as)..main" 2>/dev/null | tr -d '\r' | grep -cE '\.test\.tsx?$' || true)
dt=$(git -C "$ASD" diff --diff-filter=D --name-only "$(repo_base as)..main" 2>/dev/null | tr -d '\r' | grep -cE '\.test\.tsx?$' || true)
# 🔴🔴 **이번 범위가 지운 시험 수**는 AS_DELETED_TESTS 표의 줄 수와 **다른 값**이다
#    (74번은 우연히 같아 한 변수를 둘로 썼다 — 이 판에서 갈라 두었다).
say "A/S 에서 **새로 생긴** 시험 ${nt:-?}개 (기대 $AS_NEW_TESTS_WANT) · **지운** 시험 ${dt:-?}개 (기대 $AS_DELETED_TESTS_NOW)"
if [ "${nt:-x}" = "$AS_NEW_TESTS_WANT" ] && [ "${dt:-x}" = "$AS_DELETED_TESTS_NOW" ]; then
  ok "새 시험 ${AS_NEW_TESTS_WANT}개 · 지운 시험 ${AS_DELETED_TESTS_NOW}개다 (🔴 **둘 다 등록을 재야 한다** — 아래가 잰다)"
else
  bad "새 시험 ${nt:-?}개 · 지운 시험 ${dt:-?}개다 — $AS_NEW_TESTS_WANT · $AS_DELETED_TESTS_NOW 을 기대했다"
  doubt
fi
if [ "${lines:-0}" -ge "$AS_TESTLIST_MIN_LINES" ] 2>/dev/null; then
  # ── ① 새 시험 하나가 목록에 등록돼 있는가 (이 절의 본체다)
  got=0; seen=0
  while IFS= read -r t; do
    [ -n "$t" ] || continue
    seen=$((seen+1))
    n=$(printf '%s\n' "$TL" | grep -cFx -- "$t" || true)
    if [ "${n:-0}" -ge 1 ] 2>/dev/null; then got=$((got+1)); else printf '        🔴 안 적힘 %s\n' "$t"; fi
  done <<ENDNEWT
$(rows_of "$AS_NEW_TESTS")
ENDNEWT
  probe=$(printf '%s\n' "$TL" | grep -cFx -- "$PROBE_MISS" || true)
  say "새 시험 — 본 것 ${seen} · 적혀 있는 것 ${got} (기대 $AS_NEW_TESTS_WANT · $AS_NEW_TESTS_WANT) · 없는 경로 ${probe:-?}줄(기대 0)"
  if [ "${probe:-1}" != "0" ]; then
    bad "**없는 경로가 목록에 있다고 나왔다** — 줄 전체 일치가 깨졌다. 위 수도 못 믿는다"
  elif [ "$seen" = "$AS_NEW_TESTS_WANT" ] && [ "$got" = "$AS_NEW_TESTS_WANT" ]; then
    ok "🔴 **새 시험 ${AS_NEW_TESTS_WANT}개가 전부 목록에 등록돼 있다** (조용히 안 도는 시험이 없다)"
    say "      🔵 **그 하나에는 대괄호가 든 경로가 없습니다** — 있으면 목록에는 **별표로**"
    say "         적어야 하고, 이 표에도 **그 꼴로** 적어야 합니다(AS_NEW_TESTS 의 주석)."
  else
    bad "등록된 것이 ${got}/${AS_NEW_TESTS_WANT} 개다 — 🔴 **빠진 것은 오류 없이 조용히 안 돈다**"
    doubt
  fi
  # ── ② 🔴🔴 **일흔째가 지운 시험이 목록에서 아직도 빠져 있는가** (뒷걸음)
  #    🔴 되살아나 있으면 npm test 가 없는 파일을 찾다 깨진다.
  #    🔵 **같은 줄에서 반대쪽도 센다** — 대신 선 시험은 **적혀 있어야** 한다.
  #    🔵 [실측] 목록의 **주석에는 옛 이름이 아직 남아 있다** — 그래서 **-Fx 로만** 센다.
  say ""
  say "   🔴🔴 **일흔째가 지운 시험이 목록에서 아직도 빠져 있는가** (🔵 뒷걸음을 재는 자리)"
  dgot=0; dseen=0
  while IFS='|' read -r DT RT; do
    [ -n "${DT:-}" ] || continue
    dseen=$((dseen+1))
    a=$(printf '%s\n' "$TL" | grep -cFx -- "$DT" || true)
    b=$(printf '%s\n' "$TL" | grep -cFx -- "$RT" || true)
    c=$(printf '%s\n' "$TL" | grep -cF -- "$(basename "$DT")" || true)
    printf '        지운 것 [%s] 줄전체 %s(기대 0) · 글자만 %s(참고)\n' "$DT" "${a:-?}" "${c:-?}"
    printf '        대신 선 것 [%s] 줄전체 %s(기대 1 이상)\n' "$RT" "${b:-?}"
    if [ "${a:-1}" = "0" ] && [ "${b:-0}" -ge 1 ] 2>/dev/null; then dgot=$((dgot+1))
    elif [ "${a:-1}" != "0" ]; then
      bad "지운 시험이 목록에 **되살아났다** — npm test 가 없는 파일을 찾다 깨진다"
      doubt
    else
      bad "대신 선 시험이 목록에 **없다** — 그 자리가 통째로 비었다"
      doubt
    fi
  done <<ENDDELT
$(rows_of "$AS_DELETED_TESTS")
ENDDELT
  say "   본 것 ${dseen} · 맞는 것 ${dgot} (기대 $AS_DELETED_TESTS_WANT · $AS_DELETED_TESTS_WANT)"
  [ "$dseen" = "$AS_DELETED_TESTS_WANT" ] && [ "$dgot" = "$AS_DELETED_TESTS_WANT" ] \
    && ok "일흔째가 지운 시험이 **아직도 목록에 없고** 대신 선 시험이 적혀 있다" \
    || bad "본 것 ${dseen} · 맞는 것 ${dgot} 다 — $AS_DELETED_TESTS_WANT 을 기대했다"
  say "      🔵 **「글자만」 수가 0 이 아니어도 괜찮습니다** — 목록 파일의 주석이 그 이름을"
  say "         까닭으로 적어 두었기 때문입니다. 🔴 **그래서 줄 전체(-Fx)로만 판정합니다.**"
  # ── ③ 🔴🔴 **대괄호가 든 시험은 별표로 적혀 있어야 한다**
  #    🔴 두 쪽을 같은 줄에서 센다 — 실제 경로 꼴은 **0**, 별표 꼴은 **1 이상**.
  say ""
  say "   🔴🔴 **대괄호가 든 시험은 목록에 별표로 적혀 있어야 한다**"
  say "      🔵 **이번 범위에는 그 실물이 없습니다** — 범위 **밖**의 실물 하나를 **잣대**로"
  say "         그대로 묻습니다(지난 판이 넣어 둔 등록이 아직 별표 꼴인가)."
  say "      🔵 App Router 의 [id] 를 그대로 적으면 node 가 **글롭 문자클래스**로 읽어"
  say "         「tests 0」 으로 지나갑니다(scripts/run-test-list.mjs 머리말)."
  sgot=0; sseen=0
  while IFS='|' read -r RT ST; do
    [ -n "${RT:-}" ] || continue
    sseen=$((sseen+1))
    a=$(printf '%s\n' "$TL" | grep -cFx -- "$RT" || true)
    b=$(printf '%s\n' "$TL" | grep -cFx -- "$ST" || true)
    printf '        실제 경로 꼴 %s(기대 0) · 별표 꼴 %s(기대 1 이상)\n' "${a:-?}" "${b:-?}"
    printf '          실제 [%s]\n          별표 [%s]\n' "$RT" "$ST"
    if [ "${a:-1}" = "0" ] && [ "${b:-0}" -ge 1 ] 2>/dev/null; then sgot=$((sgot+1))
    elif [ "${a:-1}" != "0" ]; then
      bad "대괄호가 든 경로가 목록에 **그대로 적혀 있다** — 그 시험은 조용히 안 돈다"
      doubt
    else
      bad "별표 꼴이 목록에 **없다** — 그 시험이 아예 등록돼 있지 않다"
      doubt
    fi
  done <<ENDSTART
$(rows_of "$AS_STAR_TESTS")
ENDSTART
  say "   본 것 ${sseen} · 맞는 것 ${sgot} (기대 $AS_STAR_TESTS_WANT · $AS_STAR_TESTS_WANT)"
  [ "$sseen" = "$AS_STAR_TESTS_WANT" ] && [ "$sgot" = "$AS_STAR_TESTS_WANT" ] \
    && ok "대괄호가 든 시험이 **별표 꼴로** 등록돼 있다 (실제 경로 꼴은 없다)" \
    || bad "본 것 ${sseen} · 맞는 것 ${sgot} 다 — $AS_STAR_TESTS_WANT 을 기대했다"
  # ── ④ 바뀐 시험 중 **새것도 지운 것도 아닌 것**이 아직 적혀 있는가 (git 에서 뽑는다)
  # 🔴🔴 **가리는 쪽도 git 에서 뽑는다.** AS_NEW_TESTS 표는 **목록 파일에 적힌 꼴**을
  #    들고 있어서 대괄호 자리가 **별표**가 될 수 있다 — git 이 주는 **실제 경로**와
  #    안 맞고, 그러면 그 한 장이 「새것이 아닌 것」으로 흘러들어 **멀쩡한 판에서
  #    seen 이 하나 더** 나온다(71번에서 실제로 그 ✗ 가 날 자리였다).
  # 🔴🔴 **지운 것도 여기서 빼야 한다** — 73번에는 지운 시험이 0장이라 그 가지가
  #    없었다. 안 빼면 **목록에 없는 것이 당연한 한 장**이 ✗ 로 샌다.
  # 🔵 대괄호가 든 옛 시험은 **별표 꼴로도 함께 묻는다**(③ 이 꼴을 못 박았다).
  got=0; seen=0
  OLDT=$(printf '%s\n' "$AS_LIST" | grep -E '\.test\.tsx?$' || true)
  NEWT=$(git -C "$ASD" diff --diff-filter=A --name-only "$(repo_base as)..main" 2>/dev/null | tr -d '\r' | grep -E '\.test\.tsx?$' || true)
  DELT=$(git -C "$ASD" diff --diff-filter=D --name-only "$(repo_base as)..main" 2>/dev/null | tr -d '\r' | grep -E '\.test\.tsx?$' || true)
  while IFS= read -r t; do
    [ -n "$t" ] || continue
    # 새 파일이면 건너뛴다 — 위 ① 이 이미 물었다.
    # 🔴 **grep -q 를 if 에 바로 물리지 않는다**(함정 ⑦) — **세어서 담는다.**
    isnew=$(printf '%s\n' "$NEWT" | grep -cFx -- "$t" || true)
    isnum "${isnew:-}" || isnew=0
    [ "${isnew}" -ge 1 ] && continue
    # 지운 파일이면 건너뛴다 — 위 ② 가 이미 물었다(목록에 **없는 것이 맞다**).
    isdel=$(printf '%s\n' "$DELT" | grep -cFx -- "$t" || true)
    isnum "${isdel:-}" || isdel=0
    [ "${isdel}" -ge 1 ] && continue
    seen=$((seen+1))
    s2=$(printf '%s' "$t" | sed 's/\[[^]]*\]/*/g')
    n=$(printf '%s\n' "$TL" | grep -cFx -- "$t" || true)
    n2=$(printf '%s\n' "$TL" | grep -cFx -- "$s2" || true)
    if [ "${n:-0}" -ge 1 ] 2>/dev/null; then got=$((got+1))
    elif [ "${n2:-0}" -ge 1 ] 2>/dev/null; then
      got=$((got+1))
      printf '        🔵 별표 꼴로 적혀 있다 %s\n' "$s2"
    else
      printf '        🔴 안 적힘 %s\n' "$t"
    fi
  done <<ENDOLDT
$OLDT
ENDOLDT
  say "바뀐 시험 중 **새것도 지운 것도 아닌 것** — 본 것 ${seen} · 적혀 있는 것 ${got} (기대 $AS_OLD_TESTS_WANT · $AS_OLD_TESTS_WANT)"
  if [ "$seen" = "$AS_OLD_TESTS_WANT" ] && [ "$got" = "$AS_OLD_TESTS_WANT" ]; then
    ok "앞선 판들이 등록한 ${AS_OLD_TESTS_WANT}장이 **아직 다 적혀 있다** (등록을 지운 사람이 없다)"
  else
    bad "본 것 ${seen} · 적혀 있는 것 ${got} 다 — ${AS_OLD_TESTS_WANT} 을 기대했다"
    say "      🔴 **본 것이 0 이면 그 고리가 안 돈 것**입니다 — 18 − 1 − 0 = 17 이 기대값입니다."
    doubt
  fi
fi
n=0; tlseen=0
while IFS= read -r f; do
  [ -n "$f" ] || continue
  tlseen=$((tlseen+1))
  [ -f "$ASD/$f" ] && n=$((n+1)) || printf '        없음 %s\n' "$f"
done <<ENDASL
$(rows_of "$AS_TESTLIST_FILES")
ENDASL
say "목록 파일 — 본 것 ${tlseen} · 있는 것 ${n} (기대 $AS_TESTLIST_FILES_WANT)"
if [ "$tlseen" = "$AS_TESTLIST_FILES_WANT" ] && [ "$n" = "$AS_TESTLIST_FILES_WANT" ]; then
  ok "A/S 시험 목록 파일 ${AS_TESTLIST_FILES_WANT}장이 다 있다"
else
  bad "A/S 목록 파일이 ${n}/${AS_TESTLIST_FILES_WANT} 장이다"
fi

# ── 6. 태그 ───────────────────────────────────────────────────────────
#   🔴 **기대값이 모드마다 뒤집힌다.**
#      --check·--go : 아직 **없어야** 한다(같은 태그를 덮으면 되돌릴 판이 사라진다)
#      --verify     : **있어야** 한다(이미 구운 것을 다시 재는 모드다)
if [ "$MODE" = "--verify" ]; then
  step "6. 태그가 **있나** — --verify 는 이미 구운 것을 다시 재는 모드다"
else
  step "6. 태그가 이미 있나 — 같은 태그를 다시 구우면 **되돌릴 판이 사라진다**"
fi
IMG_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  TAG=$(field "$r" 3)
  IMG_SEEN=$((IMG_SEEN+1))
  if docker image inspect "$TAG" >/dev/null 2>&1; then
    if [ "$MODE" = "--verify" ]; then ok "$TAG 가 있다 (이것을 다시 잰다)"
    else
      bad "$TAG 가 **이미 있다** — 다른 판을 그 태그로 덮으면 되돌릴 것이 없어진다"
      say "      🔵 이미 구우셨다면 **다시 굽지 말고** --verify 로 그것을 재세요:"
      say "         & \"C:\\Program Files\\Git\\bin\\bash.exe\" ./75-build.sh --verify"
      say "      → 정말 지우려면: docker image rm $TAG"
    fi
  else
    if [ "$MODE" = "--verify" ]; then bad "$TAG 가 **없다** — --verify 는 구운 뒤에 쓰는 모드다"
    else ok "$TAG 가 아직 없다 (새로 굽는다)"; fi
  fi
done <<ENDIMG1
$(rows_of "$IMAGES")
ENDIMG1
[ "$IMG_SEEN" = "$HOWMANY" ] && ok "태그 ${HOWMANY}개를 다 봤다 (표본이 비지 않았다)" \
  || bad "태그를 ${IMG_SEEN}개만 봤다 — ${HOWMANY}개를 기대했다. IMAGES 표가 깨졌다"
say ""
say "🔵 되돌릴 옛 판이 개발 PC 에 있는지도 찍습니다(없어도 막지 않습니다 — NAS 에 있으면 됩니다)."
OLD_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  OLD_SEEN=$((OLD_SEEN+1))
  PT=$(field "$r" 5)
  OLDTAG=$(printf '%s' "${PT%.tar}" | sed 's/-\([0-9][0-9.]*\)$/:\1/')
  if docker image inspect "$OLDTAG" >/dev/null 2>&1; then say "옛 판 있음 $OLDTAG"
  else say "옛 판 없음 $OLDTAG (개발 PC 에만 없는 것일 수 있습니다)"; fi
done <<ENDIMG2
$(rows_of "$IMAGES")
ENDIMG2
[ "$OLD_SEEN" = "$HOWMANY" ] && ok "옛 판 ${HOWMANY}개를 다 찍었다" \
  || bad "옛 판을 ${OLD_SEEN}개만 찍었다"

# ── 7. 산출물을 둘 자리 + 🔴 dev 서버 ────────────────────────────────
step "7. 산출물을 둘 자리"
if [ -d "$OUT" ]; then
  n=$(ls -1 "$OUT" 2>/dev/null | wc -l | tr -d ' ')
  if [ "$MODE" = "--verify" ]; then
    say "$OUT 안 ${n}개 (--verify 는 **이미 구운 뒤**라 차 있는 것이 정상입니다)"
    ls -1 "$OUT" 2>/dev/null | head -15 | sed 's/^/        /'
    if [ "${n:-0}" -ge 1 ] 2>/dev/null; then ok "산출물 폴더에 파일이 ${n}개 있다"
    else bad "산출물 폴더가 비었다 — --verify 는 구운 뒤에 쓰는 모드다"; fi
  elif [ "${n:-0}" = "0" ]; then ok "$OUT 가 있고 비어 있다"
  else
    note "$OUT 에 이미 파일이 ${n}개 있다 — 아래를 보세요"
    ls -1 "$OUT" | head -15 | sed 's/^/        /'
    say "      🔴 **옛 tar 가 섞여 있으면 보낼 때 헷갈립니다.** 보내기 전에 이 폴더에서"
    say "         옛 tar 를 먼저 지우세요(쉰여섯째·쉰일곱째가 **두 판 연속** 그 자리를 밟았습니다)."
    say "      🔴🔴 **이번 판은 묶음을 안 만듭니다** — 여기 as-migrations.tar.gz 가 보이면"
    say "         **지우세요**(4-ㅁ 이 그것을 ✗ 로 셉니다). 두고 보내면 **이미 적용된 판**이"
    say "         볼륨을 덮습니다."
  fi
else
  say "$OUT 가 아직 없다 — --go 때 만든다 (--check 는 아무것도 안 만든다)"
  ok "산출물 자리를 쓸 수 있다"
fi
# 🔴 7-ㄴ. dev 서버 — 🔵 **떠 있는 것이 정상이다**
say ""
say "── 7-ㄴ. dev 서버 — **막지는 않는다. 값으로 찍는다**"
say "🔵 docker build 는 dev 서버를 안 내려도 됩니다(.dockerignore 가 .next 를 막습니다 — 5-ㄴ)."
say "🔵 **A/S(3000) 와 DB 둘(5442·5444)이 떠 있는 것이 정상입니다** — 🔴 **끄지 마세요.**"
say "   🔵 5444 는 **포털 DB** 입니다 — 이번 판이 **안 건드리는 집**의 것이지만"
say "      값으로 찍어 둡니다. 🔵 73번은 재고(3800)까지 넷을 봤습니다."
say "🔴 그래도 찍는 까닭: 그 포트가 떠 있으면 **호스트의 npm run build** 가 .next 를"
say "   두고 다투고, 그 탓에 난 tsc 오류를 코드 탓으로 오해한 적이 있습니다."
say "   🔵 이 파일은 **호스트의 npm run build 를 한 번도 안 부릅니다** — docker build 만 합니다."
PORT_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  PORT_SEEN=$((PORT_SEEN+1))
  pn=$(field "$r" 6); nm=$(field "$r" 3)
  if netstat -an 2>/dev/null | grep -q "[:.]$pn[^0-9].*LISTEN"; then
    say "$nm dev 서버 ($pn) — **떠 있다** (🔵 정상입니다)"
  else
    say "$nm dev 서버 ($pn) — 안 떠 있다"
  fi
done <<ENDPORT
$(rows_of "$REPOS")
ENDPORT
for pn in $DB_PORTS; do
  PORT_SEEN=$((PORT_SEEN+1))
  if netstat -an 2>/dev/null | grep -q "[:.]$pn[^0-9].*LISTEN"; then
    say "개발 DB ($pn) — **떠 있다** (🔵 정상입니다)"
  else
    say "개발 DB ($pn) — 안 떠 있다"
  fi
done
[ "$PORT_SEEN" = "$PORTS_WANT" ] && ok "포트 ${PORTS_WANT}개를 다 봤다" \
  || bad "포트를 ${PORT_SEEN}개만 봤다 — ${PORTS_WANT}개를 기대했다"
say "🔴 **next dev 는 포트가 차면 조용히 옆으로 비켜섭니다** — 위 수만으로 「안 떠 있다」를"
say "   단정하지 마세요. 이 줄은 판정에 쓰이지 않습니다."

# ══════════════════════════════════════════════════════════════════════
# ── 8. 🔴🔴 **양식 넷 — 이번 판에만 있는 절** ────────────────────────
# ══════════════════════════════════════════════════════════════════════
#   🔴 **이 절은 74번에 없었다.** 사용자가 2026-11-27 오전에 보고서 양식 넷의
#      **비고 가로 맞춤을 가운데 → 왼쪽**으로 고쳤고, 그 파일들은 **저장소 밖**에 있어
#      **코드 배포로는 안 간다.** 안 올리면 운영에서는 비고가 계속 가운데로 나온다.
#   🔴🔴 **보내기 전에 넷의 성한 상태를 값으로 못 박는다.** 오늘 실제로 한 파일이
#      저장되면서 병합이 깨진 적이 있다(H61:AF61 이 사라져 **221 → 220**). 사용자가
#      다시 고쳐 **지금은 넷 다 221** 이다[실측 2026-11-27].
#   🔴 **tar 를 grep -q 에 안 물리는 규율이 여기도 그대로다** — unzip 을 읽는 자리는
#      **전부 세어서 담는 꼴**(grep -c · grep -o)로만 적었다.
#   🔵 보내는 차례와 되돌리는 법은 **75-deploy.sh** 의 --templates-prep ·
#      --templates-apply 가 들고 있다(README 의 **마흔일곱째 절**의 방식 그대로).
step "8. 🔴🔴 **양식 넷** — 코드 배포로는 안 가는 것 (저장소 **밖**)"
say "자리: $TPLDIR"
say "🔴 **안 올리면 운영의 비고가 계속 가운데로 나옵니다** — 새 코드가 맞춤을"
say "   **양식에서 읽기** 때문입니다(f0e3f957)."
say "🔴🔴 **운영에 새 설정 넷이 안 심겨 있으면 양식을 올려도 소용이 없습니다** —"
say "   코드가 **옛 사본 둘**(검사보고서.xlsx · 수리보고서.xlsx · 10/19)로 물러서고,"
say "   그 둘은 **아직 center** 입니다[실측 2026-11-27]. 🔵 그것을 재는 자리는"
say "   75-deploy.sh 의 templates_check 입니다(앱 안에서 설정 이름으로 묻습니다)."

# 🔴 **xlsx 를 읽는 길 — unzip 하나뿐이다.** 없으면 아래를 **못 잰다**(? 로 센다).
TPL_UNZIP=0
if command -v unzip >/dev/null 2>&1; then TPL_UNZIP=1; fi
say "unzip 이 있는가: ${TPL_UNZIP} (기대 1 — Git Bash 에 들어 있습니다)"

# 🔴 셀의 가로 맞춤 — 시트에서 그 셀의 서식 번호를 뽑고 styles.xml 의 cellXfs 에서 찾는다.
#    🔴🔴 **cellXfs 를 <xf 로 쪼개면 첫 조각은 빈 글자다** — 그래서 n번 서식은
#       **n+2 번째 조각**이다. [실측 2026-11-27] n+1 로 적었다가 네 파일이 전부
#       「center」 로 나왔다(한 칸 밀린 값이었다). **공짜 ✗ 가 아니라 공짜 ✓ 였다.**
#    🔵 그 서식에 alignment 가 없으면 빈 글자를 돌려준다 — 부르는 쪽이 그것을 가른다.
tpl_cell_style() { # 1 파일 2 셀
  unzip -p "$1" "$TPL_SHEET" 2>/dev/null \
    | grep -o "<c r=\"$2\" s=\"[0-9]*\"" | head -1 | sed 's/.*s="//; s/"//'
}
tpl_xf_align() { # 1 파일 2 서식 번호
  unzip -p "$1" xl/styles.xml 2>/dev/null | tr -d '\n' \
    | sed -n 's/.*<cellXfs[^>]*>\(.*\)<\/cellXfs>.*/\1/p' \
    | awk -v n="$2" 'BEGIN{RS="<xf "} NR==n+2 {print}' \
    | grep -o 'horizontal="[a-z]*"' | head -1 | sed 's/horizontal="//; s/"//'
}
tpl_merge_count() { # 1 파일 — mergeCells 의 count 속성(그 장의 병합 수)
  unzip -p "$1" "$TPL_SHEET" 2>/dev/null \
    | grep -o 'mergeCells count="[0-9]*"' | head -1 | sed 's/.*count="//; s/"//'
}
tpl_merge_has() { # 1 파일 2 ref — 그 병합이 몇 줄인가 (0 이면 없다)
  unzip -p "$1" "$TPL_SHEET" 2>/dev/null | grep -c "mergeCell ref=\"$2\"" || true
}

say ""
say "── 8-ㄱ. 🔴 **올릴 넷** — 있는가 · 크기·md5 가 맞는가 · **속이 성한가**"
TPLUP_SEEN=0; TPLUP_OK=0
while IFS='|' read -r TPN TPSZ TPM5; do
  [ -n "${TPN:-}" ] || continue
  TPLUP_SEEN=$((TPLUP_SEEN+1))
  P="$TPLDIR/$TPN"
  if [ ! -f "$P" ]; then
    bad "양식이 없다 — $P"
    say "      🔴 저장소 밖입니다. 그 PC 의 $TPLDIR 를 보세요."
    continue
  fi
  sz=$(stat -c %s "$P" 2>/dev/null || wc -c < "$P")
  m5=$(md5sum "$P" 2>/dev/null | awk '{print $1}')
  printf '      %-28s %s바이트 md5 %s\n' "$TPN" "${sz:-?}" "${m5:-?}"
  printf '      %-28s (적어 둔 값) %s바이트 md5 %s\n' "" "$TPSZ" "$TPM5"
  if [ "${sz:-x}" != "$TPSZ" ] || [ "${m5:-x}" != "$TPM5" ]; then
    bad "$TPN 의 크기·md5 가 적어 둔 값과 다르다 — **그 사이에 또 고치신 것**일 수 있다"
    say "      🔴 그러면 **75-deploy.sh 의 TPL_UP 표도 함께** 갈아 끼워야 합니다."
    say "      🔵 위 두 줄을 그대로 그 표에 넣으세요(이름|바이트|md5)."
    doubt
    continue
  fi
  if [ "$TPL_UNZIP" != "1" ]; then
    unk "$TPN 의 속" "unzip 이 없다 — 병합과 맞춤을 못 쟀다"
    continue
  fi
  mc=$(tpl_merge_count "$P")
  lb=$(tpl_merge_has "$P" "$TPL_LABEL_MERGE")
  pb=$(tpl_merge_has "$P" "$TPL_MERGE_PROBE")
  rm_ok=0; rm_seen=0
  for mref in $TPL_REMARK_MERGES; do
    rm_seen=$((rm_seen+1))
    v=$(tpl_merge_has "$P" "$mref")
    printf '        병합 [%s] %s줄 (기대 1)\n' "$mref" "${v:-?}"
    [ "${v:-0}" = "1" ] && rm_ok=$((rm_ok+1))
  done
  al_ok=0; al_seen=0
  for cell in $TPL_REMARK_CELLS; do
    al_seen=$((al_seen+1))
    s=$(tpl_cell_style "$P" "$cell")
    a=""
    [ -n "${s:-}" ] && a=$(tpl_xf_align "$P" "$s")
    printf '        맞춤 [%s] 서식 %s → %s (기대 %s)\n' "$cell" "${s:-못 읽음}" "${a:-없음}" "$TPL_REMARK_ALIGN_WANT"
    [ "${a:-x}" = "$TPL_REMARK_ALIGN_WANT" ] && al_ok=$((al_ok+1))
  done
  printf '        %s 의 병합 %s개(기대 %s) · 라벨 [%s] %s(기대 1) · 없는 병합 [%s] %s(기대 0)\n' \
    "$TPL_SHEET" "${mc:-?}" "$TPL_MERGE_WANT" "$TPL_LABEL_MERGE" "${lb:-?}" "$TPL_MERGE_PROBE" "${pb:-?}"
  printf '        비고 병합 %s/%s · 비고 맞춤 %s/%s\n' "$rm_ok" "$TPL_REMARK_MERGES_WANT" "$al_ok" "$TPL_REMARK_CELLS_WANT"
  if [ "${pb:-1}" != "0" ]; then
    bad "$TPN — **없는 병합을 물었는데 ${pb:-?} 가 나왔다.** 잣대가 죽었다 — 위 수를 못 믿는다"
    doubt
  elif [ "${mc:-x}" = "$TPL_MERGE_WANT" ] && [ "${lb:-0}" = "1" ] \
       && [ "$rm_seen" = "$TPL_REMARK_MERGES_WANT" ] && [ "$rm_ok" = "$TPL_REMARK_MERGES_WANT" ] \
       && [ "$al_seen" = "$TPL_REMARK_CELLS_WANT" ] && [ "$al_ok" = "$TPL_REMARK_CELLS_WANT" ]; then
    TPLUP_OK=$((TPLUP_OK+1))
    ok "$TPN 이 **성하다** (병합 ${TPL_MERGE_WANT}개 · 비고 네 줄 · 라벨 칸 · 맞춤 넷이 $TPL_REMARK_ALIGN_WANT)"
  else
    bad "$TPN 의 속이 기대와 다르다 — 병합 ${mc:-?}(기대 $TPL_MERGE_WANT) · 라벨 ${lb:-?} · 비고 병합 ${rm_ok}/${TPL_REMARK_MERGES_WANT} · 맞춤 ${al_ok}/${TPL_REMARK_CELLS_WANT}"
    say "      🔴 **병합이 $((TPL_MERGE_WANT - 1)) 이면 저장하다 한 줄이 사라진 것**입니다 — 오늘 실제로"
    say "         그 일이 있었습니다(H61:AF61). 그 파일을 Excel 에서 다시 고치세요."
    say "      🔴 **맞춤이 center 면 옛 파일**입니다 — 올려도 아무것도 안 바뀝니다."
    say "      🔴 **라벨 칸($TPL_LABEL_MERGE)이 없으면 새 코드가 양식을 읽다 던집니다** —"
    say "         작성 화면에 안내 한 줄만 남습니다(xlsx/service-report-template.ts)."
    doubt
  fi
done <<ENDTPLUP
$(rows_of "$TPL_UP")
ENDTPLUP
say "올릴 양식 — 본 것 ${TPLUP_SEEN} · 성한 것 ${TPLUP_OK} (기대 $TPL_UP_WANT · $TPL_UP_WANT)"
[ "$TPLUP_SEEN" = "$TPL_UP_WANT" ] && [ "$TPLUP_OK" = "$TPL_UP_WANT" ] \
  && ok "양식 ${TPL_UP_WANT}장이 다 있고 **속까지 성하다** (표본이 비지 않았다)" \
  || bad "본 것 ${TPLUP_SEEN} · 성한 것 ${TPLUP_OK} 다 — ${TPL_UP_WANT} 을 기대했다"

say ""
say "── 8-ㄴ. 🔵 **안 올리는 일곱** — 그 자리에 있는가 (75-deploy.sh 가 쓰는 표다)"
say "🔴 **md5 가 다르면 ⚠️ 로만 셉니다** — 운영 것과 개발 PC 것이 꼭 같아야 한다는"
say "   보증이 어디에도 없습니다(도장·계좌번호가 든 파일이라 저장소에 없습니다)."
say "🔴🔴 **옛 사본 둘(검사보고서.xlsx · 수리보고서.xlsx)의 맞춤이 center 입니다** —"
say "   운영에 새 설정 넷이 없으면 **그 둘이 쓰이고 비고가 가운데로 나옵니다.**"
TPLK_SEEN=0; TPLK_OK=0; TPLK_DIFF=0
while IFS='|' read -r TPN TPSZ TPM5; do
  [ -n "${TPN:-}" ] || continue
  TPLK_SEEN=$((TPLK_SEEN+1))
  P="$TPLDIR/$TPN"
  if [ ! -f "$P" ]; then bad "양식이 없다 — $P (75-deploy.sh 의 TPL_KEEP 표가 그것을 들고 있다)"; continue; fi
  sz=$(stat -c %s "$P" 2>/dev/null || wc -c < "$P")
  m5=$(md5sum "$P" 2>/dev/null | awk '{print $1}')
  if [ "${sz:-x}" = "$TPSZ" ] && [ "${m5:-x}" = "$TPM5" ]; then
    TPLK_OK=$((TPLK_OK+1)); printf '      같다   %-28s %s바이트\n' "$TPN" "$sz"
  else
    TPLK_DIFF=$((TPLK_DIFF+1))
    printf '      다르다 %-28s %s바이트 %s\n' "$TPN" "${sz:-?}" "${m5:-?}"
    printf '             (적어 둔 값) %s바이트 %s\n' "$TPSZ" "$TPM5"
  fi
done <<ENDTPLKEEP
$(rows_of "$TPL_KEEP")
ENDTPLKEEP
say "안 올리는 일곱 — 본 것 ${TPLK_SEEN} · 같은 것 ${TPLK_OK} · 다른 것 ${TPLK_DIFF} (기대 $TPL_KEEP_WANT · $TPL_KEEP_WANT · 0)"
if [ "$TPLK_SEEN" != "$TPL_KEEP_WANT" ]; then
  bad "안 올리는 양식을 ${TPLK_SEEN}장만 봤다 — ${TPL_KEEP_WANT}장을 기대했다. TPL_KEEP 표가 깨졌다"
elif [ "$TPLK_OK" = "$TPL_KEEP_WANT" ]; then
  ok "안 올리는 일곱이 적어 둔 값 그대로다 (75-deploy.sh 의 표를 믿을 수 있다)"
else
  note "그중 ${TPLK_DIFF}장이 적어 둔 값과 다르다 — **사람이 보세요**(그 표를 갈아 끼우세요)"
fi
# 🔴 **없는 이름을 함께 묻는다** — 「무조건 있다」인 검사인지 가른다.
if [ -f "$TPLDIR/__dss_probe_no_such_template__.xlsx" ]; then
  bad "없는 양식 이름이 **있다고 나왔다** — 위 yes 를 못 믿는다"
else
  ok "없는 양식 이름이 **없다고 나왔다** (양식을 묻는 잣대가 살아 있다)"
fi

printf '\n%s\n' "────────────────────────────────────────────────────────────"
printf '  ✓ %s   ✗ %s   ? %s\n' "$PASS" "$FAIL" "$UNK"
}

# ══════════════════════════════════════════════════════════════════════
# ══ 이미지 안을 재는 길 — 🔴 **갈래마다 다른 것을 잰다** ══════════════
# ══════════════════════════════════════════════════════════════════════
#   🔴 앱과 도구는 담긴 것이 다르다 — 앱은 **번들**, 도구는 **소스 그대로**다.
#   🔵 73번에는 여기에 **재고 가지**가 더 있었다(inventorytools) — 거기는 drizzle 의
#      기대값이 A/S 와 **반대**(28장이 있어야 ✓)였고 vendor 도 **없어야** ✓ 였다.
#      🔴 되살릴 때 **한 잣대로 베끼지 마라** — 둘 중 하나가 가짜 ✗ 가 된다
#      (73-build.sh:2642-2700 · 69-build.sh 의 같은 경고).
#   🔵 **74번이 늘린 자리 둘을 그대로 뒀다**: 공용 스키마의 **DATA**(이제 **뒷걸음**을
#      재는 자리)와 **지운 파일 둘이 아직도 없는가**(TOOLMARK_GONE · 역시 뒷걸음).
IMGFAIL=0
INSIDE_RAN=0
dock() { dockr run --rm --entrypoint sh "$@" 2>/dev/null | tr -d '\r'; }

# 🔴 목록 하나를 이미지 안에서 한 장씩 묻는다 — **없는 경로 하나를 함께** 묻는다.
#    🔴 set -f 로 글롭을 끈다. **이번 A/S 목록에는 괄호·대괄호가 든 경로가 셋 있다**
#       (이번 범위 **안**의 잣대 세 장이다 — AS_KEY_FILES 의 주석)
#       — set -f 가 없으면 그 줄이 파일 이름 확장으로 읽혀 **없는 것으로 나온다.**
ask_files() { # 1 태그 2 목록(줄바꿈) 3 기대 수 4 사람이 부르는 말
  local v got seen probe
  v=$(dockr run --rm -e DSS_FILES="$2" -e DSS_MISS="$PROBE_MISS" --entrypoint sh "$1" -c \
    'set -f; printf "%s\n%s\n" "$DSS_FILES" "$DSS_MISS" | while IFS= read -r f; do [ -n "$f" ] || continue; if [ -f "/app/$f" ]; then echo "yes $f"; else echo "no  $f"; fi; done' 2>/dev/null | tr -d '\r')
  printf '%s\n' "$v" | sed 's/^/        /'
  seen=$(printf '%s\n' "$v" | grep -c '^\(yes\|no \)' || true)
  got=$(printf '%s\n' "$v" | grep -c '^yes ' || true)
  probe=$(printf '%s\n' "$v" | grep -c "^no  $PROBE_MISS" || true)
  printf '      %s — 본 것 %s · 있는 것 %s (기대 %s · %s) · 없는 경로가 no 로 나왔나 %s(기대 1)\n' \
    "$4" "${seen:-0}" "${got:-0}" "$(( $3 + 1 ))" "$3" "${probe:-0}"
  if [ "${probe:-0}" != "1" ]; then
    printf '  ✗ **없는 경로가 no 로 안 나왔다** — 「무조건 yes」인 검사다. 위 yes 도 못 믿는다\n'; IMGFAIL=1
  elif [ "${seen:-0}" = "$(( $3 + 1 ))" ] && [ "${got:-0}" = "$3" ]; then
    printf '  ✓ %s %s장이 다 담겼다 (표본이 비지 않았다)\n' "$4" "$3"
  else
    printf '  ✗ 본 것 %s · 있는 것 %s 다 — %s 를 기대했다\n' "${seen:-0}" "${got:-0}" "$3"; IMGFAIL=1
    printf '%s\n' "      🔴 본 것이 모자라면 **목록을 넘기는 길이 끊긴 것**(글롭 함정)이고,"
    printf '%s\n' "         있는 것만 모자라면 **옛 소스가 담긴 이미지**입니다."
  fi
}

# 🔴 번들 안에서 글자 하나를 센다 — **.next/server 와 .next/static 을 둘 다** 본다.
#    🔵 넷째 인자는 **판정에 안 쓰는 곁들이 값**이다.
bundle_mark() { # 1 태그 2 글자 3 사람이 부르는 말 4 (선택) 곁들여 찍을 글자
  local v s t d ds dt
  v=$(dockr run --rm -e M="$2" --entrypoint sh "$1" -c \
    'printf "%s %s\n" "$(grep -rlF "$M" /app/.next/server 2>/dev/null | wc -l)" "$(grep -rlF "$M" /app/.next/static 2>/dev/null | wc -l)"' 2>/dev/null | tr -d '\r')
  s=$(printf '%s' "$v" | awk '{print $1}'); t=$(printf '%s' "$v" | awk '{print $2}')
  printf '      [%s] — .next/server %s개 · .next/static %s개 (🔴 합이 1 이상이어야 한다)\n' "$2" "${s:-?}" "${t:-?}"
  if [ -n "${4:-}" ]; then
    d=$(dockr run --rm -e M="$4" --entrypoint sh "$1" -c \
      'printf "%s %s\n" "$(grep -rlF "$M" /app/.next/server 2>/dev/null | wc -l)" "$(grep -rlF "$M" /app/.next/static 2>/dev/null | wc -l)"' 2>/dev/null | tr -d '\r')
    ds=$(printf '%s' "$d" | awk '{print $1}'); dt=$(printf '%s' "$d" | awk '{print $2}')
    printf '      [%s] — server %s개 · static %s개 (🔵 **판정에 안 쓰는 곁들이 값**)\n' "$4" "${ds:-?}" "${dt:-?}"
  fi
  if isnum "${s:-}" && isnum "${t:-}" && [ "$((s + t))" -ge 1 ]; then
    printf '  ✓ %s\n' "$3"
  else
    printf '  ✗ %s — **없다.** 올리지 마세요\n' "$3"; IMGFAIL=1
    printf '%s\n' "      🔵 **검사 자신을 먼저 의심하세요.** 🔴 **이 파일의 표식은 번들에서 한 번도"
    printf '%s\n' "         안 세어 봤습니다** — 이 판은 굽기 전에 쓰였고, 여기가 **처음** 세는"
    printf '%s\n' "         자리입니다(71번은 구운 뒤 열여덟을 다 세어 적었습니다)."
    printf '%s\n' "      🔵 71번이 **구운 번들에서** 확인해 둔 것(참고): 뒷걸음 열 중 아홉이 ≥1 이고"
    printf '%s\n' "         shareDocRelativePath 는 **23개**였습니다. **뒷걸음이 0 이면 진짜 결함**입니다."
    printf '%s\n' "      🔴 **기능 표식이 0 이면** 그것이 **객체 칸 이름**(autoAdvancedOnPoIssuedDate)인지"
    printf '%s\n' "         **문자열 리터럴**(NO_WAITING_REPAIR_STEP)인지 보세요 — 뒤쪽이 0 이면"
    printf '%s\n' "         **그 코드가 안 담긴 것**이고, 앞쪽만 0 이면 **minify 가 칸 이름까지 줄인 것**"
    printf '%s\n' "         입니다(그때는 이미지가 아니라 **이 검사**를 고치세요)."
    printf '%s\n' "      🔴 **그 글자가 한글이면 1-ㄷ 절부터 보세요** — ASCII 표식이 ✓ 인데"
    printf '%s\n' "         한글만 0 이면 그것은 **검사 탓**입니다(이미지를 되돌리지 마세요)."
    printf '%s\n' "      🔴 **코드 줄에서 따온 글자는 번들에 안 남습니다** — 지역 이름은 minify 가"
    printf '%s\n' "         갈아 치우고 export 이름은 웹팩이 줄입니다(part.drawingNo, part.note 가"
    printf '%s\n' "         71번에서 그 실물이었습니다 — 소스 1줄 · 번들 0/0)."
    if [ -n "${4:-}" ] && isnum "${ds:-}" && isnum "${dt:-}" && [ "$((ds + dt))" -ge 1 ]; then
      printf '%s\n' "      🔴 **곁들이 글자는 1 이상입니다** — 즉 이미지가 통째로 비어 있지는 않습니다."
      printf '%s\n' "         🔵 이 판의 곁들이는 **export 이름**(INVENTORY_RETURN_REQUEST_TYPE ·"
      printf '%s\n' "            canAuthorTechnicalTemplatesByDefault)이라 **남는 것이 오히려 뜻밖**입니다."
      printf '%s\n' "         🔵 이미지를 다시 굽기 전에 **이 검사를 먼저 보세요** — 다른 글자로"
      printf '%s\n' "            재면 지문이 안 바뀝니다(75-build.sh --verify)."
    else
      printf '%s\n' "      🔴 **곁들이 글자도 0 입니다** — 옛 소스를 구웠거나, 경로 번역이 살아"
      printf '%s\n' "         있습니다(1-ㄴ 절이 ✓ 였는지 보세요)."
      printf '%s\n' "         🔵 다만 이 판의 곁들이는 **export 이름**이라 **멀쩡한 판에서도 0 일 수**"
      printf '%s\n' "            **있습니다** — 곁들이 0 만으로 결함이라 단정하지 마세요."
    fi
  fi
}

# 🔵 **판정에 안 쓰고 찍기만 하는 곁들이.**
#    🔴 이 판의 곁들이 둘은 **export 이름**이라 번들에 남는지 모른다 — 그래서
#       ✗ 를 안 내고 값만 남긴다. 다음 판이 「그때 번들에 남았나」를 이 로그에서
#       읽을 수 있다(71번이 TONE_COUNT 로 같은 일을 했고, 그 값은 **0** 이었다).
bundle_note() { # 1 태그 2 글자 3 사람이 부르는 말
  local v s t
  v=$(dockr run --rm -e M="$2" --entrypoint sh "$1" -c \
    'printf "%s %s\n" "$(grep -rlF "$M" /app/.next/server 2>/dev/null | wc -l)" "$(grep -rlF "$M" /app/.next/static 2>/dev/null | wc -l)"' 2>/dev/null | tr -d '\r')
  s=$(printf '%s' "$v" | awk '{print $1}'); t=$(printf '%s' "$v" | awk '{print $2}')
  printf '      [%s] — server %s개 · static %s개 (🔵 **판정에 안 씀** — %s)\n' "$2" "${s:-?}" "${t:-?}" "$3"
}

# 🔴 npm 명령을 **값으로 받아 본다** — Missing script 와 Cannot find module 을 가른다.
npm_probe() { # 1 태그 2 명령
  local v
  v=$(dockr run --rm --entrypoint sh "$1" -c "cd /app && npm run $2 2>&1 | head -40" 2>&1 | tr -d '\r')
  if printf '%s' "$v" | grep -qE 'Missing script|missing script'; then
    printf '  ✗ npm run %s — **Missing script** (41번과 같은 실패다)\n' "$2"; IMGFAIL=1
    printf '%s\n' "$v" | head -15 | sed 's/^/        /'
  elif printf '%s' "$v" | grep -qE 'Cannot find module|ERR_MODULE_NOT_FOUND|Cannot find package'; then
    printf '  ✗ npm run %s 가 모듈을 못 찾는다 — 이미지에 담긴 것이 모자란다\n' "$2"; IMGFAIL=1
    printf '%s\n' "$v" | head -15 | sed 's/^/        /'
  elif printf '%s' "$v" | grep -qiE 'DATABASE_URL|환경변수|connection string|ECONNREFUSED|getaddrinfo|AUTH_|PORTAL_'; then
    printf '  ✓ npm run %s 가 import 까지 갔고 바깥에는 안 닿았다 (기대한 답)\n' "$2"
  else
    printf '  ⚠️ npm run %s 의 답이 기대와 다르다 — 아래 15줄을 사람이 보세요\n' "$2"
    printf '%s\n' "$v" | head -15 | sed 's/^/        /'
  fi
}

# ══════════════════════════════════════════════════════════════════════
# ══ 🔴 이미지 **안**을 세는 함수 — 굽기와 --verify 가 **함께 쓴다** ══
# ══════════════════════════════════════════════════════════════════════
#   🔴 **두 벌로 적지 않는다.** 두 벌이면 한쪽만 고쳐져 어긋난다.
#   🔵 바깥에 IMGFAIL 을 남긴다(local 로 가리지 않는다).
inside_check() { # 1 열쇠(as|astools) 2 태그 3 타깃(-=앱)
  # 🔴 **몇 번 실제로 돌았는지 센다.** [실측 2026-11-18] 이 함수를 쓰는 자리보다
  #    **뒤에** 정의해 두었더니 「command not found」만 한 줄 찍히고 --verify 가
  #    **✗ 0 으로 통과**했다. 아무것도 안 재는 ✓ 의 실물이다.
  INSIDE_RAN=$((INSIDE_RAN + 1))
  KEY=$1; TAG=$2; TGT=$3
  IMGFAIL=0
  RK=$(repo_key_of "$KEY")
  PR=$(row_by_key "$PUBLIC_WANT" "$RK")
  PW=$(field "$PR" 2); PN_WANT=$(field "$PR" 3); PMIN=$(field "$PR" 4)
  if [ "$TGT" = "-" ]; then
    # ── 앱 이미지 (번들이다 — 소스가 없다)
    printf '\n    ── %s 안을 센다 (**번들**이다 — 소스가 없다)\n' "$TAG"
    v=$(dock "$TAG" -c "test -f /app/server.js && echo yes || echo no")
    printf '      /app/server.js: %s (기대 yes)\n' "${v:-못 읽음}"
    if [ "${v:-}" = "yes" ]; then printf '  ✓ runner 스테이지가 맞다 (node server.js 를 안다)\n'
    else printf '  ✗ /app/server.js 가 없다 — **runner 가 아닌 것을 구웠다.** 올리지 마세요\n'; IMGFAIL=1; fi
    # 🔴🔴 **public/ 의 기대값이 집마다 다르다**(PUBLIC_WANT 의 주석).
    #    A/S 는 9개쯤 있어야 하고, 재고는 **있는데 비어 보이는 것이 정상**이다
    #    (.gitkeep 한 장뿐 — ls -1 은 숨은 파일을 안 센다). 🔴 A/S 잣대를 재고에
    #    들이대면 **멀쩡한 이미지가 ✗** 다(62번이 그 가짜 ✗ 를 냈고 69번이 고쳤다).
    v=$(dock "$TAG" -c 'if [ -d /app/public ]; then printf "yes %s\n" "$(ls -1 /app/public 2>/dev/null | wc -l)"; else printf "no 0\n"; fi')
    pst=$(printf '%s' "$v" | awk '{print $1}'); pn=$(printf '%s' "$v" | awk '{print $2}')
    printf '      /app/public: %s (파일 %s개 · 기대 %s · 참고 %s개 · 판정 최솟값 %s)\n' \
      "${pst:-못 읽음}" "${pn:-?}" "${PW:-?}" "${PN_WANT:-?}" "${PMIN:-?}"
    if [ "${pst:-}" != "${PW:-}" ]; then
      printf '  ✗ /app/public 이 %s 다 — %s 를 기대했다\n' "${pst:-못 읽음}" "${PW:-?}"; IMGFAIL=1
      printf '%s\n' "      🔵 없으면 정적 파일이 404 가 되고 COPY 가 멈춘 것입니다."
    elif [ "${pn:-0}" -ge "${PMIN:-1}" ] 2>/dev/null; then
      if [ "${PMIN:-1}" = "0" ]; then
        printf '  ✓ public/ 폴더가 있다 (%s개 — 🔵 **이 집은 비어 보이는 것이 정상**이다)\n' "$pn"
        printf '%s\n' "      🔵 .gitkeep 한 장뿐이고 ls -1 은 숨은 파일을 안 셉니다 — A/S 의 9개를"
        printf '%s\n' "         여기 들이대면 **가짜 ✗** 가 납니다(69-build.sh 의 그 자리)."
      else
        printf '  ✓ public/ 이 담겼다 (%s개 · 참고 %s개)\n' "$pn" "${PN_WANT:-?}"
      fi
    else
      printf '  ✗ public/ 은 있는데 파일이 %s개다 — %s개 이상(참고 %s)을 기대했다\n' \
        "${pn:-?}" "${PMIN:-1}" "${PN_WANT:-?}"; IMGFAIL=1
    fi
    # 🔴 **표식을 APPMARKS 표에서 그 집 것만 꺼내 돈다** — 집마다 다르다.
    #    🔵 이 판은 기능 4 + 뒷걸음 14 + 곁들이 3 이고 **판정에 쓰는 것은 18** 이다.
    SIDE=$(rows_of "$APPMARKS" | while IFS='|' read -r R K M N; do
             [ "$R" = "$RK" ] && [ "$K" = "side" ] && printf '%s\n' "$M"; done | head -1)
    MKRAN=0
    while IFS='|' read -r R K M N; do
      [ -n "${R:-}" ] || continue
      [ "$R" = "$RK" ] || continue
      case "$K" in
        feature)
          MKRAN=$((MKRAN+1))
          bundle_mark "$TAG" "$M" "번들에 **이번 판의 글자**가 있다 ($N)" "${SIDE:-}"
          ;;
        keep)
          MKRAN=$((MKRAN+1))
          bundle_mark "$TAG" "$M" "지난 판이 올린 글자가 그대로 있다 — 뒷걸음친 나무가 아니다 ($N)"
          ;;
        side)
          bundle_note "$TAG" "$M" "$N"
          ;;
      esac
    done <<ENDBM
$(rows_of "$APPMARKS")
ENDBM
    # 🔴 **집마다 기대 수가 다르다** — 한 수로 뭉뚱그리면 둘 중 하나가 늘 ✗ 다.
    #    🔵 이 판은 집이 하나지만 **꼴을 그대로 뒀다**(73번은 A/S 14 · 재고 6 이었다).
    if [ "$RK" = "as" ]; then MKWANT=$AS_MARKS_JUDGE_WANT; else MKWANT=0; fi
    printf '      이 집에서 **판정에 쓴 표식** %s개 (기대 %s)\n' "$MKRAN" "$MKWANT"
    if [ "$MKRAN" = "$MKWANT" ]; then
      printf '  ✓ %s 번들 표식 %s개를 다 돌았다 (표본이 비지 않았다)\n' "$RK" "$MKWANT"
      printf '%s\n' "      🔵 **이번 판은 두 갈래가 다 여기서 가려집니다** — ㄱ(권한 열쇠 문자열)과"
      printf '%s\n' "         ㄴ(칸 이름 셋)이 전부 번들에 글자 그대로 남습니다(74번의 DATA 갈래와 다릅니다)."
      printf '%s\n' "         🔵 위 곁들이 넷의 수를 **다음 판이 읽습니다**(export 이름이 남는가)."
    else
      printf '  ✗ %s 번들 표식을 %s개만 돌았다 — %s개를 기대했다. APPMARKS 표가 깨졌다\n' "$RK" "$MKRAN" "$MKWANT"; IMGFAIL=1
    fi
  else
    # ── 도구 이미지 (소스가 글자 그대로 있다)
    printf '\n    ── %s 안을 센다 (**소스가 글자 그대로** 있다)\n' "$TAG"
    v=$(dock "$TAG" -c "test -f /app/package.json && echo yes || echo no")
    printf '      /app/package.json: %s (기대 yes)\n' "${v:-못 읽음}"
    if [ "${v:-}" = "yes" ]; then printf '  ✓ tools 스테이지가 맞다\n'
    else printf '  ✗ /app/package.json 이 없다 — **runner 를 구웠다.** --target tools 를 빠뜨렸다\n'; IMGFAIL=1; fi
    v=$(dock "$TAG" -c "test -d /app/node_modules/tsx && echo yes || echo no")
    printf '      /app/node_modules/tsx: %s (기대 yes)\n' "${v:-못 읽음}"
    if [ "${v:-}" = "yes" ]; then printf '  ✓ tsx 가 있다\n'
    else printf '  ✗ tsx 가 없다 — tsx 로 도는 도구가 그 자리에서 죽는다\n'; IMGFAIL=1; fi
    # 🔴🔴 **도구 표식이 둘이라 고리로 돈다** — 71번은 row_by_key 로 **한 줄만**
    #    꺼냈다. 그 함수는 맞는 줄을 **이어 붙여** 돌려주므로 두 줄이면 글자가
    #    통째로 깨진다. 🔴 **몇 개를 돌았는지 끝에서 단언한다**(고리가 한 바퀴만
    #    돌면 ㄱ 갈래만 재고 ㄷ 갈래는 **아무 검사도 안 받는다**).
    #    🔵 경로를 **상대로 넘기고** /app/ 를 컨테이너 안에서 붙인다(함정 ⑪).
    #    🔵 yes/no 가 아니라 **센 줄 수**를 받는다 — 0 과 「못 읽음」을 가른다.
    TMRAN=0
    while IFS='|' read -r TK TMK TMF TMWAS TMW; do
      [ -n "${TK:-}" ] || continue
      [ "$TK" = "$KEY" ] || continue
      TMRAN=$((TMRAN+1))
      v=$(dockr run --rm -e M="$TMK" -e F="$TMF" --entrypoint sh "$TAG" -c \
        'p="/app/$F"; if [ -f "$p" ]; then printf "hit %s\n" "$(grep -cF -- "$M" "$p")"; else printf "missing 0\n"; fi' 2>/dev/null | tr -d '\r')
      tst=$(printf '%s' "$v" | awk '{print $1}'); tn=$(printf '%s' "$v" | awk '{print $2}')
      printf '      도구 표식 [%s] in %s — 파일 %s · 그 글자 %s줄 (기대 hit · %s)\n' \
        "$TMK" "$TMF" "${tst:-못 읽음}" "${tn:-?}" "${TMW:-1}"
      if [ "${tst:-}" = "hit" ] && [ "${tn:-0}" -ge 1 ] 2>/dev/null; then
        printf '  ✓ **그 갈래의 코드가 담겼다** (%s줄)\n' "$tn"
        printf '%s\n' "      🔵 앱 이미지는 **같은 작업본에서 같은 실행으로** 굽습니다 — 2절이 그"
        printf '%s\n' "         작업본의 HEAD 와 미커밋 0 을 확인했으므로 앱에도 들어 있습니다."
      elif [ "${tst:-}" = "hit" ]; then
        printf '  ✗ 그 파일은 있는데 그 글자가 **0줄**이다 — **옛 소스가 담긴 이미지다**\n'; IMGFAIL=1
      elif [ "${tst:-}" = "missing" ]; then
        printf '  ✗ 그 파일 자체가 이미지에 없다 — src/ 가 온전히 안 담겼다\n'; IMGFAIL=1
        printf '%s\n' "      🔵 **경로 번역부터 의심하세요** — 1-ㄴ 절이 ✓ 였는지 보세요."
      else
        printf '  ✗ 못 읽었다 (받은 값 [%s])\n' "${v:-}"; IMGFAIL=1
      fi
    done <<ENDTMIMG
$(rows_of "$TOOLMARKS")
ENDTMIMG
    printf '      이 이미지에서 돈 도구 표식 %s개 (기대 %s)\n' "$TMRAN" "$TOOLMARKS_PER_IMAGE_WANT"
    if [ "$TMRAN" = "$TOOLMARKS_PER_IMAGE_WANT" ]; then
      printf '  ✓ 도구 표식 %s개를 다 돌았다 (이 집의 두 자리를 다 가렸다)\n' "$TOOLMARKS_PER_IMAGE_WANT"
    else
      printf '  ✗ 도구 표식을 %s개만 돌았다 — %s개를 기대했다. **한 자리가 아무 검사도 안 받았다**\n' \
        "$TMRAN" "$TOOLMARKS_PER_IMAGE_WANT"; IMGFAIL=1
    fi
    # ── 🔴🔴 여기부터 **집마다 갈린다 — 정반대인 자리가 셋이다:**
    #       drizzle(A/S **0장** ↔ 재고 **28장**) · vendor(A/S **있어야** ↔ 재고 **없어야**) ·
    #       /templates(A/S 만 — 재고와는 아무 상관이 없다).
    #    🔴 **한 가지로 뭉뚱그리지 마라** — 둘 중 하나가 반드시 가짜 ✗ 가 된다
    #       (62-build.sh:34-35 와 69-build.sh 가 같은 경고를 적어 두었다).
    case "$KEY" in
      astools)
        ask_files "$TAG" "$AS_KEY_FILES" "$AS_KEY_FILES_WANT" "A/S 의 핵심 파일"
        printf '%s\n' "      🔵 그 열한 장 중 **끝의 셋이 글롭 잣대**입니다 — 둘은 괄호+대괄호,"
        printf '%s\n' "         하나는 괄호만입니다. 길이 끊기면 **그 셋이 먼저 no 로** 떨어져"
        printf '%s\n' "         「옛 소스가 담겼다」와 갈립니다."
        printf '%s\n' "      🔵 **이번에는 셋 다 범위 안입니다**(74번은 둘을 범위 밖에서 끌어왔습니다)."
        # 🔵 **ㄷ 잣대가 살아 있는 자리** — import 하는 scripts/ 둘이 이미지 안에도 있는가.
        v=$(dockr run --rm --entrypoint sh "$TAG" -c \
          'set -f; n=0; for f in scripts/lib/delivered-date-sync-survey.ts scripts/lib/requested-due-date-sync-survey.ts; do [ -f "/app/$f" ] && n=$((n+1)); done; echo "n=$n"' 2>/dev/null | tr -d '\r')
        g=$(printf '%s' "$v" | sed -n 's/^n=//p')
        printf '      ㄷ 잣대의 scripts/ 둘: %s개 (기대 2)\n' "${g:-?}"
        if [ "${g:-x}" = "2" ]; then printf '  ✓ 그 둘이 이미지에 담겼다 (scripts/ 가 온전히 담겼다)\n'
        else printf '  ✗ 그 둘이 %s/2 개다 — scripts/ 가 온전히 안 담겼다\n' "${g:-?}"; IMGFAIL=1; fi
        # 🔴 A/S 는 drizzle 을 **안 담아야** 한다 — 볼륨이 붙는 자리다.
        v=$(dock "$TAG" -c "ls /app/drizzle/*.sql 2>/dev/null | wc -l"); v=$(printf '%s' "$v" | tr -d ' ')
        printf '      /app/drizzle 안 .sql: %s개 (기대 0 — 볼륨이 붙지 않은 맨 이미지다)\n' "${v:-?}"
        if isnum "${v:-}" && [ "${v:-1}" = "0" ]; then
          printf '  ✓ drizzle/ 이 비어 있다 (볼륨이 정본이다)\n'
          printf '%s\n' "      🔵 **이번 판은 올릴 .sql 이 0건이라 묶음을 안 만듭니다** — 운영의 볼륨은"
          printf '%s\n' "         일흔째가 만들어 둔 ${AS_SQL_WANT}장 **그대로**입니다."
        else printf '  ✗ drizzle/ 에 .sql 이 들었다 — 볼륨과 이미지 중 어느 것이 도는지 못 가른다\n'; IMGFAIL=1; fi
        # 🔴 **공용 스키마가 담겼는가** — 핀이 맞아도 **빈 서브모듈이 담길 수 있다**.
        v=$(dock "$TAG" -c 'd=/app/vendor/dss-core/src/schema; if [ -d "$d" ]; then echo "miss=0"; echo "n=$(ls -1 "$d" | wc -l)"; else echo "miss=1"; fi')
        v=$(printf '%s\n' "$v" | tr -d ' ')
        printf '%s\n' "$v" | sed 's/^/        /'
        c=$(printf '%s\n' "$v" | sed -n 's/^miss=//p'); g=$(printf '%s\n' "$v" | sed -n 's/^n=//p')
        if [ "${c:-1}" != "0" ]; then printf '  ✗ 이미지에 vendor/dss-core 의 스키마 폴더가 **없다** — Cannot find module 이 난다\n'; IMGFAIL=1
        elif [ "${g:-0}" -ge 1 ] 2>/dev/null; then printf '  ✓ 공용 스키마가 담겼다 (파일 %s개)\n' "$g"
        else printf '  ✗ 공용 스키마 폴더가 비었다 — **빈 서브모듈이 담겼다.** 올리지 마세요\n'; IMGFAIL=1; fi
        # 🔴 **일곱 그대로 둔다** — 71번이 셋에서 일곱으로 늘린 자리다. 🔵 이 판에서도
        #    **일곱이 전부 뒷걸음**이다(이번 판이 더한 것은 바로 아래에서 따로 센다).
        #    🔴 **하나라도 빼지 마라** — 서브모듈이 되감긴 날 이 줄만이 그것을 잡는다.
        v=$(dock "$TAG" -c 'for pair in "portal_approval_delegations /app/vendor/dss-core/src/schema/portal-approval-delegations.ts" "portal-approval-delegations /app/vendor/dss-core/src/schema/index.ts" "fault_tags /app/vendor/dss-core/src/schema/repair-case-flowcharts.ts" "confirmed_at /app/vendor/dss-core/src/schema/domestic-order-due-dates.ts" "confirmed_by /app/vendor/dss-core/src/schema/domestic-order-due-dates.ts" "share_doc_relative_path /app/vendor/dss-core/src/schema/procedure-template-nodes.ts" "share_doc_relative_path /app/vendor/dss-core/src/schema/repair-case-flowchart-nodes.ts"; do set -- $pair; if grep -q "$1" "$2" 2>/dev/null; then echo "yes $1"; else echo "no  $1 $2"; fi; done')
        printf '%s\n' "$v" | sed 's/^/        /'
        g=$(printf '%s\n' "$v" | grep -c '^yes ' || true)
        if [ "${g:-0}" = "7" ]; then
          printf '  ✓ **공용 스키마가 일곱 다 담겼다** (🔵 이 판에서는 일곱이 전부 **뒷걸음**이다)\n'
        else
          printf '  ✗ 일곱 중 %s개만 있다 — **옛 공용 스키마가 담겼다.** 올리지 마세요\n' "${g:-0}"; IMGFAIL=1
          printf '%s\n' "      🔴 뒤의 넷(confirmed_* · share_doc_*)만 no 면 **서브모듈이 예순여섯째"
          printf '%s\n' "         핀으로 되감긴 것**입니다 — 그 기능이 통째로 사라집니다(3-ㄱ)."
        fi
        # 🔴🔴 **일흔째가 공용 스키마에 더한 것이 이미지에 아직 있는가** (뒷걸음)
        #    🔴 **위 일곱 고리에 끼워 넣지 않았다** — 그 고리는 「공백 없는 낱말 쌍」을
        #       set -- 로 쪼개 읽어서 따옴표가 든 글자를 못 넘긴다. 그래서 TOOLMARKS 와
        #       **같은 길**(-e 로 넘기기)로 따로 묻는다.
        #    🔵 **74번에서 한 글자도 안 바꿨다** — 뜻만 「이번에 더했는가」에서
        #       「**아직 있는가**」로 뒤집혔다. 🔴 **지우지 마라** — 운영 DB 의 enum 에는
        #       그 값이 있는데 코드가 그 값을 모르는 날, 그 날을 잡는 자리가 여기다.
        v=$(dockr run --rm -e M='"DATA",' -e F=vendor/dss-core/src/schema/attachments.ts --entrypoint sh "$TAG" -c \
          'p="/app/$F"; if [ -f "$p" ]; then printf "hit %s\n" "$(grep -cF -- "$M" "$p")"; else printf "missing 0\n"; fi' 2>/dev/null | tr -d '\r')
        cst=$(printf '%s' "$v" | awk '{print $1}'); csn=$(printf '%s' "$v" | awk '{print $2}')
        printf '      공용 스키마의 enum 값 ["DATA",] in attachments.ts — 파일 %s · 그 글자 %s줄 (기대 hit · 1)\n' \
          "${cst:-못 읽음}" "${csn:-?}"
        if [ "${cst:-}" = "hit" ] && [ "${csn:-0}" -ge 1 ] 2>/dev/null; then
          printf '  ✓ **공용 스키마에 일흔째의 enum 값이 아직 담겨 있다** (%s줄)\n' "$csn"
        elif [ "${cst:-}" = "hit" ]; then
          printf '  ✗ 그 값이 **0줄**이다 — **서브모듈이 되감긴 채로 구웠다.** 올리지 마세요\n'; IMGFAIL=1
          printf '%s\n' "      🔴 3-ㄱ 과 3-ㅁ 을 다시 보세요 — 포인터는 맞는데 담긴 것이 옛 것일 수 있습니다."
        elif [ "${cst:-}" = "missing" ]; then
          printf '  ✗ attachments.ts 자체가 이미지에 없다 — vendor 가 온전히 안 담겼다\n'; IMGFAIL=1
        else
          printf '  ✗ 못 읽었다 (받은 값 [%s])\n' "${v:-}"; IMGFAIL=1
          printf '%s\n' "      🔵 **경로 번역부터 의심하세요** — 1-ㄴ 절이 ✓ 였는지 보세요."
        fi
        # 🔴🔴 **일흔째가 지운 둘이 이미지에도 아직 없는가** (뒷걸음)
        #    🔴 작업본에서 없어진 것과 **이미지에 없는 것**은 다른 질문이다 — 옛 소스를
        #       구우면 작업본은 깨끗한데 이미지에만 되살아난다.
        #    🔵 **같은 줄에서 반대쪽도 센다** — 대신 선 파일은 **있어야** 한다.
        TGI_SEEN=0; TGI_OK=0
        while IFS='|' read -r TK GF RF; do
          [ -n "${TK:-}" ] || continue
          [ "$TK" = "$KEY" ] || continue
          TGI_SEEN=$((TGI_SEEN+1))
          v=$(dockr run --rm -e G="$GF" -e R="$RF" --entrypoint sh "$TAG" -c \
            'set -f; a=no; b=no; [ -f "/app/$G" ] && a=yes; [ -f "/app/$R" ] && b=yes; printf "%s %s\n" "$a" "$b"' 2>/dev/null | tr -d '\r')
          ga=$(printf '%s' "$v" | awk '{print $1}'); gb=$(printf '%s' "$v" | awk '{print $2}')
          printf '      지운 것 [%s] %s (기대 no) · 대신 선 것 [%s] %s (기대 yes)\n' \
            "$GF" "${ga:-못 읽음}" "$RF" "${gb:-못 읽음}"
          if [ "${ga:-}" = "no" ] && [ "${gb:-}" = "yes" ]; then TGI_OK=$((TGI_OK+1))
          elif [ "${ga:-}" = "yes" ]; then
            printf '  ✗ %s 이 **이미지에 되살아났다** — 옛 소스를 구웠다. 올리지 마세요\n' "$GF"; IMGFAIL=1
          else
            printf '  ✗ %s 이 **이미지에 없다** — 지운 자리를 대신할 파일이 안 담겼다\n' "$RF"; IMGFAIL=1
          fi
        done <<ENDTGI
$(rows_of "$TOOLMARK_GONE")
ENDTGI
        printf '      지운 파일 검사 %s개 (기대 %s)\n' "$TGI_SEEN" "$TOOLMARK_GONE_WANT"
        if [ "$TGI_SEEN" = "$TOOLMARK_GONE_WANT" ] && [ "$TGI_OK" = "$TOOLMARK_GONE_WANT" ]; then
          printf '  ✓ 일흔째가 지운 %s장이 **이미지에도 아직 없고** 대신 선 파일이 다 담겼다\n' "$TOOLMARK_GONE_WANT"
        else
          printf '  ✗ 본 것 %s · 맞는 것 %s 다 — %s 를 기대했다\n' "$TGI_SEEN" "$TGI_OK" "$TOOLMARK_GONE_WANT"; IMGFAIL=1
        fi
        # 🔵 양식이 이미지에 안 들어갔는가 — 들어갔으면 도장과 계좌번호가 구워진 것이다.
        v=$(dock "$TAG" -c "ls /templates 2>/dev/null | wc -l"); v=$(printf '%s' "$v" | tr -d ' ')
        printf '      /templates 안 파일: %s개 (기대 0 — 양식은 볼륨으로 붙는다)\n' "${v:-?}"
        if isnum "${v:-}" && [ "${v:-1}" = "0" ]; then printf '  ✓ 양식이 이미지에 안 들어갔다\n'
        else printf '  ✗ 이미지 안에 /templates 가 %s개 있다 — 도장·계좌번호가 구워졌다. 사람이 보세요\n' "${v:-?}"; IMGFAIL=1; fi
        v=$(dock "$TAG" -c "test -d /app/node_modules/drizzle-kit && echo yes || echo no")
        printf '      /app/node_modules/drizzle-kit: %s (기대 yes)\n' "${v:-못 읽음}"
        if [ "${v:-}" = "yes" ]; then printf '  ✓ drizzle-kit 이 있다 (db:preflight·db:migrate 가 이것으로 돈다)\n'
        else printf '  ✗ drizzle-kit 이 없다 — **db:preflight 가 그 자리에서 죽는다.** 올리지 마세요\n'; IMGFAIL=1; fi
        npm_probe "$TAG" db:preflight
        npm_probe "$TAG" db:migrate
        printf '%s\n' "      🔵 **이번 판은 db:migrate 가 올릴 것이 0건입니다**(74번은 1건이었습니다)."
        printf '%s\n' "         🔴 **여기서는 어차피 안 올라갑니다** — 개발 PC 에서는 운영 DB 에"
        printf '%s\n' "            못 닿고, 여기서 재는 것은 「그 명령이 **import 까지 가는가**」뿐입니다."
        printf '%s\n' "            src/ 39장이 바뀐 판에서 그 길이 끊기면 **Cannot find module** 로"
        printf '%s\n' "            여기서 드러납니다."
        printf '%s\n' "         🔵 DATABASE_URL 쪽 답이 기대한 답입니다(바깥에 안 닿았다는 뜻입니다)."
        printf '%s\n' "         🔴 **db:migrate 는 오류를 삼키고 exit 1 만 남기는 성질이 있습니다** —"
        printf '%s\n' "            그래서 75-deploy.sh 는 --migrate 뒤에 **수를 다시 세어** ${AS_SQL_WANT} 인지 봅니다."
        ;;
      # 🔵 **inventorytools 가지가 없다** — 재고가 이번 판에 없다(머리말 「왜 없는가」 ①).
      #    🔴 되살릴 때는 **73-build.sh:2742-2822 을 통째로** 가져와라. 거기서 A/S 와
      #       **정반대**인 자리가 셋이다: drizzle(0장 ↔ 28장) · vendor(있어야 ↔ 없어야) ·
      #       /templates(A/S 만 — 그 볼륨은 A/S 양식이고 재고와 아무 상관이 없다).
      #       🔴 그리고 그 집에는 **db:preflight 가 없다** — 부르면 Missing script 다.
    esac
  fi
}

# ══ 재기 ══════════════════════════════════════════════════════════════
check_all
if [ "$MODE" = "--check" ]; then
  if [ "$FAIL" = "0" ] && [ "$UNK" = "0" ]; then
    printf '\n%s\n' "✅ 전부 ✓ 입니다. 구우려면 --go 로 다시 부르세요."
    exit 0
  fi
  printf '\n%s\n' "🔴 ✗ 나 ? 가 있습니다. 위를 보세요 — 고친 뒤 --go 로 가세요."
  printf '%s\n' "   🔵 **검사 자신을 먼저 의심하세요** — 처음 도는 코드라 기대값이 틀릴 확률이"
  printf '%s\n' "      굽기만큼 높습니다. 기대값의 출처는 이 파일 머리말에 적혀 있습니다."
  exit 1
fi

# ══════════════════════════════════════════════════════════════════════
# ══ 🔴 묶음 안을 세는 함수 — --go 와 --verify 가 **함께 쓴다** ═══════
# ══════════════════════════════════════════════════════════════════════
#   🔴 **71-build.sh:2430-2513 에서 되살렸다**(73번에는 이 함수가 통째로 없었다 —
#      거기는 마이그레이션이 0건이었다). 🔴 **MIGTAR 변수 · 이 함수 · 「다섯째
#      산출물」 절 · --verify 의 묶음 절이 한 벌이다** — 하나만 되살리면 묶음을
#      만들고도 **안을 한 번도 안 세게** 된다.
#   🔴 **두 벌로 적지 않는다.** 66번은 --go 쪽과 --verify 쪽에 따로 적어 두어
#      기대값이 어긋날 자리가 있었다 — 여기서는 한 함수로 모았다.
#   🔴 tar 를 **grep -q 에 물리지 않는다**(함정 ⑦). 전부 세어서 담는다.
#   🔴🔴 **옛 묶음(2026-11-25 · 134장)과 가르는 줄이 이 함수의 끝에 있다** —
#      크기와 md5 를 **그 값과 맞대어** 같으면 ✗ 를 낸다.
MIGCHK_FAIL=0
migtar_inside() { # 1 묶음 경로
  local a b s j n m sz m5
  MIGCHK_FAIL=0
  s=$(tar -tzf "$1" 2>/dev/null | grep -cE '^drizzle/[0-9]{4}_.*[.]sql$' || true)
  j=$(tar -xzOf "$1" drizzle/meta/_journal.json 2>/dev/null | grep -o '"idx"' | wc -l | tr -d ' ')
  printf '    묶음 안 — .sql %s장 · meta/_journal.json 의 idx %s개 (기대 %s · %s)\n' \
    "${s:-?}" "${j:-?}" "$AS_SQL_WANT" "$AS_SQL_WANT"
  if [ "${s:-x}" = "$AS_SQL_WANT" ] && [ "${j:-x}" = "$AS_SQL_WANT" ]; then
    printf '  ✓ 묶음 안이 %s장이고 목록도 %s개다 (목록에서 빠진 .sql 이 없다)\n' "$AS_SQL_WANT" "$AS_SQL_WANT"
  else
    printf '  ✗ 묶음 안이 .sql %s · idx %s 다 — %s·%s 를 기대했다\n' "${s:-?}" "${j:-?}" "$AS_SQL_WANT" "$AS_SQL_WANT"
    printf '%s\n' "      🔴 목록에 없는 .sql 은 drizzle 이 **아예 모르고**, 적용이 0건으로 조용히 끝납니다."
    printf '%s\n' "      🔴 **134 가 나오면 옛 묶음을 보고 있는 것**입니다(2026-11-25 의 것)."
    MIGCHK_FAIL=$((MIGCHK_FAIL+1))
  fi
  # 🔴 **이번 판이 올릴 장**이 .sql·스냅샷 **짝으로** 들어 있는가.
  n=0; m=0
  for t in $AS_NEW_MIGS; do
    n=$((n+1))
    a=$(tar -tzf "$1" 2>/dev/null | grep -cE "^drizzle/${t}_.*[.]sql" || true)
    b=$(tar -tzf "$1" 2>/dev/null | grep -cE "^drizzle/meta/${t}_snapshot[.]json" || true)
    printf '    묶음 안의 %s — .sql %s개 · 스냅샷 %s개 (기대 1 · 1)\n' "$t" "${a:-?}" "${b:-?}"
    [ "${a:-0}" = "1" ] && [ "${b:-0}" = "1" ] && m=$((m+1))
  done
  if [ "$n" = "$AS_NEW_MIGS_WANT" ] && [ "$m" = "$AS_NEW_MIGS_WANT" ]; then
    printf '  ✓ **이번 판이 올릴 %s장이 묶음 안에 짝으로 있다**\n' "$AS_NEW_MIGS_WANT"
  else
    printf '  ✗ 본 장 %s · 짝으로 있는 장 %s 다 — %s 를 기대했다. **보내지 마세요**\n' "$n" "$m" "$AS_NEW_MIGS_WANT"
    MIGCHK_FAIL=$((MIGCHK_FAIL+1))
  fi
  a=$(tar -tzf "$1" 2>/dev/null | grep -cE "^drizzle/${AS_NEXT_MIG}_.*[.]sql" || true)
  printf '    묶음 안의 %s: %s개 (기대 0)\n' "$AS_NEXT_MIG" "${a:-?}"
  if [ "${a:-1}" = "0" ]; then
    printf '  ✓ 묶음에 %s 가 없다 (마지막이 %s — 적용 대기가 %s건이 된다)\n' "$AS_NEXT_MIG" "$AS_LAST_MIG" "$AS_NEW_MIGS_WANT"
  else
    printf '  ✗ 묶음에 %s 가 **있다** — 이 배포는 %s 까지를 전제로 쓰였다. 멈추고 알릴 것\n' "$AS_NEXT_MIG" "$AS_LAST_MIG"
    MIGCHK_FAIL=$((MIGCHK_FAIL+1))
  fi
  # 🔵 창 안 여덟 — 폴더를 통째로 갈아 끼우므로 .sql 과 스냅샷이 짝인지 본다.
  KEEPIN_MISS=""; KEEPIN_SEEN=0
  for t in $AS_KEEP_MIGS; do
    KEEPIN_SEEN=$((KEEPIN_SEEN+1))
    a=$(tar -tzf "$1" 2>/dev/null | grep -cE "^drizzle/${t}_.*[.]sql" || true)
    b=$(tar -tzf "$1" 2>/dev/null | grep -cE "^drizzle/meta/${t}_snapshot[.]json" || true)
    printf '      %-6s .sql %s · 스냅샷 %s\n' "$t" "${a:-0}" "${b:-0}"
    [ "${a:-0}" -ge 1 ] 2>/dev/null || KEEPIN_MISS="$KEEPIN_MISS $t(sql)"
    [ "${b:-0}" -ge 1 ] 2>/dev/null || KEEPIN_MISS="$KEEPIN_MISS $t(snapshot)"
  done
  if [ "$KEEPIN_SEEN" = "$AS_KEEP_MIGS_WANT" ] && [ -z "${KEEPIN_MISS:-}" ]; then
    printf '  ✓ 묶음에 창 안 %s장의 .sql 과 스냅샷이 다 있다 (폴더를 통째로 갈아 끼워도 안전하다)\n' "$AS_KEEP_MIGS_WANT"
  else
    printf '  ✗ 본 것 %s장 · 묶음에서 빠진 것:%s\n' "$KEEPIN_SEEN" "${KEEPIN_MISS:- 없음}"
    MIGCHK_FAIL=$((MIGCHK_FAIL+1))
  fi
  # 🔴 묶음 안의 장이 기대한 생김새인가 — **보내는 것은 저장소가 아니라 이 묶음이다.**
  #    🔴🔴 과녁이 **ADD VALUE** 다(71번은 ADD COLUMN 이었다) — 그대로 베끼면 멀쩡한
  #       판이 ✗ 가 된다. 🔵 **ADD COLUMN 은 0 을 같은 줄에서 함께** 센다.
  n=0; m=0
  for t in $AS_NEW_MIGS; do
    n=$((n+1))
    NM=$(tar -tzf "$1" 2>/dev/null | grep -E "^drizzle/${t}_.*[.]sql" | head -1)
    if [ -z "${NM:-}" ]; then
      printf '  ✗ 묶음 안의 %s 을 못 읽었다\n' "$t"; MIGCHK_FAIL=$((MIGCHK_FAIL+1)); continue
    fi
    TB=$(tar -xzOf "$1" "$NM" 2>/dev/null)
    traw=$(printf '%s\n' "$TB" | grep -ciE "$DESTRUCTIVE_RE" || true)
    tnet=$(printf '%s\n' "$TB" | grep -v "$SQL_COMMENT_RE" | grep -ciE "$DESTRUCTIVE_RE" || true)
    tins=$(printf '%s\n' "$TB" | grep -v "$SQL_COMMENT_RE" | grep -c 'INSERT INTO' || true)
    tupd=$(printf '%s\n' "$TB" | grep -v "$SQL_COMMENT_RE" | grep -c 'UPDATE ' || true)
    tct=$(printf '%s\n' "$TB" | grep -v "$SQL_COMMENT_RE" | grep -c 'CREATE TABLE' || true)
    tac=$(printf '%s\n' "$TB" | grep -v "$SQL_COMMENT_RE" | grep -c 'ADD COLUMN' || true)
    tav=$(printf '%s\n' "$TB" | grep -v "$SQL_COMMENT_RE" | grep -c 'ADD VALUE' || true)
    trn=$(printf '%s\n' "$TB" | grep -ciE 'RENAME' || true)
    ten=$(printf '%s\n' "$TB" | grep -cF "$AS_ENUM_NAME" || true)
    tev=$(printf '%s\n' "$TB" | grep -cF "$AS_ENUM_VALUE" || true)
    printf '    묶음 안 %s — 지우는 문장 날것 %s/걷은뒤 %s(기대 0) · ADD VALUE %s(기대 1 이상) · ADD COLUMN %s(기대 0)\n' \
      "$t" "${traw:-?}" "${tnet:-?}" "${tav:-?}" "${tac:-?}"
    printf '      INSERT %s(기대 0) · UPDATE %s(기대 0) · CREATE TABLE %s(기대 0) · RENAME %s(기대 0) · enum 이름 %s · 값 %s\n' \
      "${tins:-?}" "${tupd:-?}" "${tct:-?}" "${trn:-?}" "${ten:-?}" "${tev:-?}"
    if [ "${tnet:-x}" = "0" ] && [ "${tins:-1}" = "0" ] && [ "${tupd:-1}" = "0" ] \
       && [ "${tct:-1}" = "0" ] && [ "${trn:-1}" = "0" ] \
       && [ "${tav:-0}" -ge 1 ] 2>/dev/null && [ "${tac:-1}" = "$AS_ADDCOL_WANT" ] \
       && [ "${ten:-0}" -ge 1 ] 2>/dev/null && [ "${tev:-0}" -ge 1 ] 2>/dev/null; then
      m=$((m+1))
    else
      printf '  ✗ 묶음 안의 %s 이 기대와 다르다 — 보내지 마세요\n' "$t"; MIGCHK_FAIL=$((MIGCHK_FAIL+1))
    fi
  done
  if [ "$n" = "$AS_NEW_MIGS_WANT" ] && [ "$m" = "$AS_NEW_MIGS_WANT" ]; then
    printf '  ✓ 묶음 안의 %s장이 **enum 값을 더하기만 한다** (자료를 안 건드린다)\n' "$AS_NEW_MIGS_WANT"
    printf '%s\n' "      🔵 **같은 판에서 그 값을 안 씁니다**(INSERT·UPDATE 가 0) — 그래서"
    printf '%s\n' "         「새 enum 값을 같은 트랜잭션에서 쓰면 멈춘다」에 안 걸립니다."
  fi
  # 🔴🔴 **옛 묶음(2026-11-25 · 134장)과 가른다** — 지문으로만 갈린다.
  sz=$(stat -c %s "$1" 2>/dev/null || wc -c < "$1")
  m5=$(md5sum "$1" | awk '{print $1}')
  printf '    지문 — %s바이트 · md5 %s\n' "${sz:-?}" "${m5:-?}"
  printf '    옛 묶음(2026-11-25 · 134장) — %s바이트 · md5 %s\n' "$OLD_MIGTAR_SIZE" "$OLD_MIGTAR_MD5"
  if [ "${m5:-x}" = "$OLD_MIGTAR_MD5" ]; then
    printf '  ✗ 🔴🔴 **이것은 2026-11-25 의 묶음입니다**(134장) — 이번 것이 아닙니다. 보내지 마세요\n'
    MIGCHK_FAIL=$((MIGCHK_FAIL+1))
  elif isnum "${sz:-}" && [ "${sz:-0}" -gt "$OLD_MIGTAR_SIZE" ] 2>/dev/null; then
    printf '  ✓ 옛 묶음과 md5 가 다르고 **크기도 더 크다** (0134 와 그 스냅샷이 늘었다)\n'
  else
    printf '  ⚠️ md5 는 다른데 크기가 %s 로 옛 것(%s)보다 안 큽니다 — **사람이 보세요**\n' "${sz:-?}" "$OLD_MIGTAR_SIZE"
    printf '%s\n' "      🔵 gzip 의 압축률 때문에 드물게 그럴 수 있습니다. 🔴 다만 위의 「.sql 135장」이"
    printf '%s\n' "         ✓ 였는지 **꼭 다시 보세요** — 그 줄이 진짜 판정입니다."
  fi
}

# ══════════════════════════════════════════════════════════════════════
# ── 🔴 --verify : **이미 구운 둘을 다시 재기만 한다** ────────────────
# ══════════════════════════════════════════════════════════════════════
#   🔴 **아무것도 굽지 않고 아무 파일도 만들지 않는다.** docker build 도
#      docker save 도 한 줄 없다 — 구운 지문(md5)이 바뀌면 안 되기 때문이다.
if [ "$MODE" = "--verify" ]; then
  printf '\n%s\n' "════════ --verify — 이미 구운 $HOWMANY 을 **다시 잰다** (굽지 않는다) ════════"
  printf '%s\n' "🔴 docker build 도 docker save 도 돌리지 않습니다 — 지문이 바뀌면 안 됩니다."
  VFAIL=0; VSEEN=0; TARTABLE=""; INSIDE_RAN=0
  # 🔴 **함수가 정말 있는가** — 없으면 「command not found」 한 줄만 찍히고
  #    나머지가 통째로 건너뛰어진다(2026-11-18 에 실제로 그렇게 통과했다).
  if ! command -v inside_check >/dev/null 2>&1; then
    printf '  ✗ inside_check 함수가 **없다** — 이 파일의 차례가 깨졌다. 아무것도 안 쟀다\n'
    exit 1
  fi
  # 🔴 **묶음 함수도 같은 까닭으로 묻는다** — 71번에서 되살린 것이라 자리가 어긋나기 쉽다.
  if ! command -v migtar_inside >/dev/null 2>&1; then
    printf '  ✗ migtar_inside 함수가 **없다** — 묶음을 한 번도 안 세게 된다. 아무것도 안 쟀다\n'
    exit 1
  fi
  while IFS= read -r row; do
    [ -n "$row" ] || continue
    KEY=$(field "$row" 1); TAG=$(field "$row" 3); TGT=$(field "$row" 4)
    VSEEN=$((VSEEN+1))
    printf '\n── %s\n' "$TAG"
    if ! docker image inspect "$TAG" >/dev/null 2>&1; then
      printf '  ✗ %s 가 없다 — 굽지 않았거나 지웠다\n' "$TAG"; VFAIL=$((VFAIL+1)); continue
    fi
    IMGFAIL=0
    inside_check "$KEY" "$TAG" "$TGT"
    if [ "$IMGFAIL" != 0 ]; then
      printf '%s\n' "🔴 $TAG 의 안이 온전하지 않다."
      VFAIL=$((VFAIL+1))
    fi
    # 🔵 tar 가 아직 있으면 지문 줄을 **다시 찍어 준다** — 굽지 않고도 TARS 를 채울 수 있다.
    FILE=$(tar_name "$TAG")
    if [ -f "$OUT/$FILE" ]; then
      sz=$(stat -c %s "$OUT/$FILE" 2>/dev/null || wc -c < "$OUT/$FILE")
      m5=$(md5sum "$OUT/$FILE" | awk '{print $1}')
      cfg=$(tar_config_id "$OUT/$FILE")
      TARTABLE="$TARTABLE$FILE|$sz|$m5|${cfg:-없음}
"
    fi
  done <<ENDVERIFY
$(rows_of "$IMAGES")
ENDVERIFY
  printf '\n%s\n' "────────────────────────────────────────────────────────────"
  printf '  본 이미지 %s / %s · **안을 실제로 센 횟수 %s** · 안이 온전하지 않은 것 %s\n' \
    "$VSEEN" "$HOWMANY" "$INSIDE_RAN" "$VFAIL"
  if [ "$VSEEN" != "$HOWMANY" ]; then
    printf '  ✗ 이미지를 %s개만 봤다 — %s개를 기대했다. IMAGES 표가 깨졌다\n' "$VSEEN" "$HOWMANY"
    VFAIL=$((VFAIL+1))
  fi
  # 🔴 **표본이 비어서 공짜로 통과하지 않게** 한다.
  if [ "$INSIDE_RAN" != "$HOWMANY" ]; then
    printf '  ✗ 이미지 안을 %s번만 쟀다 — %s번을 기대했다. **아무것도 안 잰 통과다**\n' "$INSIDE_RAN" "$HOWMANY"
    VFAIL=$((VFAIL+1))
  else
    printf '  ✓ 이미지 안을 %s번 다 쟀다 (표본이 비지 않았다)\n' "$INSIDE_RAN"
  fi
  if [ -n "${TARTABLE:-}" ]; then
    printf '\n%s\n' "════════ 75-deploy.sh 의 TARS 에 넣을 줄 (tar 에서 다시 쟀습니다) ════════"
    printf '%s' "$TARTABLE"
  fi
  # 🔴 **묶음도 다시 만들지 않는다** — 만들면 md5 가 바뀐다. 있으면 **열어서 재고**
  #    지문 줄만 찍는다. 🔵 71-build.sh:2574-2588 에서 되살린 절이다.
  #    🔵 **이번 판은 묶음을 안 만든다** — 그래서 여기서 재는 것은 「**있으면 안 되는
  #       것이 있는가**」다. 🔴 migtar_inside 는 **지우지 않았다**(1건이 생기는 날 돈다).
  printf '\n%s\n' "════════ 묶음 — 🔵 **이번 판은 안 만듭니다** ════════"
  if [ -f "$MIGTAR" ]; then
    msz=$(stat -c %s "$MIGTAR" 2>/dev/null || wc -c < "$MIGTAR")
    mm5=$(md5sum "$MIGTAR" | awk '{print $1}')
    printf '    as-migrations.tar.gz %s바이트 · md5 %s\n' "${msz:-?}" "${mm5:-?}"
    if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
      printf '  ✗ 🔴 **이번 판은 묶음을 안 보냅니다** — 산출물 폴더의 그 파일을 지우세요\n'
      printf '%s\n' "      → rm \"$MIGTAR\""
      VFAIL=$((VFAIL+1))
    else
      migtar_inside "$MIGTAR"
      if [ "$MIGCHK_FAIL" != "0" ]; then VFAIL=$((VFAIL + MIGCHK_FAIL)); fi
      printf '\n%s\n' "════════ 75-deploy.sh 의 묶음 값 둘 (묶음에서 다시 쟀습니다) ════════"
      printf '%s\n' "MIGTAR_SIZE=${msz}"
      printf '%s\n' "MIGTAR_MD5=${mm5}"
    fi
  else
    if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
      printf '  ✓ 묶음이 **없다** (🔵 이번 판은 안 만드는 것이 맞다 — 올릴 .sql 이 0건이다)\n'
    else
      printf '  ⚠️ 묶음이 아직 없습니다 (--go 전이면 정상입니다) — %s\n' "$MIGTAR"
    fi
  fi
  printf '\n'
  if [ "$FAIL" = "0" ] && [ "$UNK" = "0" ] && [ "$VFAIL" = "0" ]; then
    printf '%s\n' "✅ --verify 전부 통과입니다. **아무것도 안 굽고 안 바꿨습니다.**"
    exit 0
  fi
  printf '%s\n' "🔴 ✗ 가 남아 있습니다 (앞 절 ✗ $FAIL · ? $UNK · 이미지·묶음 $VFAIL)"
  printf '%s\n' "   🔵 **검사 자신을 먼저 의심하세요** — 1-ㄴ 절(경로 번역)이 ✓ 였는지 보세요."
  exit 1
fi

if [ "$FAIL" != "0" ] || [ "$UNK" != "0" ]; then
  printf '\n%s\n' "🔴 ✗ 나 ? 가 있어 **굽지 않습니다.** (✗ $FAIL · ? $UNK)"
  printf '%s\n' "   구운 이미지는 그때 그 작업 폴더의 사진입니다 — 어긋난 채로 구우면"
  printf '%s\n' "   나중에 같은 이미지를 다시 못 만듭니다."
  exit 1
fi

mkdir -p "$OUT" || { printf '%s\n' "🔴 $OUT 를 못 만들었다"; exit 1; }

# ══ 굽기 ══════════════════════════════════════════════════════════════
printf '\n%s\n' "════════ 굽는다 ($HOWMANY) ════════"
printf '%s\n' "🔵 **둘입니다.** 10~20분쯤 걸릴 수 있습니다 — 중간에 끊지 마세요."
printf '%s\n' "🔵 **묶음은 안 만듭니다**(올릴 .sql 이 0건) — 둘을 구우면 산출물이 끝입니다."
printf '%s\n' "🔴🔴 **다만 양식 넷을 따로 보내야 합니다** — 8-ㄱ 이 그 넷을 쟀고, 꼬리말의"
printf '%s\n' "   ③번 차례가 보낼 명령을 찍어 줍니다."
printf '%s\n' "🔵 dev 서버(3000)와 DB(5442·5444)는 **켜 둔 채로 둬도 됩니다** — .dockerignore 가"
printf '%s\n' "   .next 를 막고(5-ㄴ), 이 파일은 호스트의 npm run build 를 한 번도 안 부릅니다."
BUILT=0; BFAIL=0; TARTABLE=""; BUILD_SEEN=0
while IFS= read -r row; do
  [ -n "$row" ] || continue
  KEY=$(field "$row" 1); REPO=$(field "$row" 2); TAG=$(field "$row" 3)
  TGT=$(field "$row" 4); PREVTAR=$(field "$row" 5); PREVSZ=$(field "$row" 6)
  STRICT=$(field "$row" 7)
  DIR="$DEV/$REPO"
  BUILD_SEEN=$((BUILD_SEEN+1))
  FILE=$(tar_name "$TAG")
  LOG="$OUT/build-$(printf '%s' "$TAG" | tr ':' '-').log"
  printf '\n── %s/%s  %s  (%s)\n' "$BUILD_SEEN" "$HOWMANY" "$TAG" "$REPO"

  # 🔴 도구 이미지만 --target tools 다. 안 주면 **runner 가 구워지고** 그 안에는
  #    scripts/ 도 package.json 도 없어 오류 없이 쓸모없는 이미지가 된다.
  if [ "$TGT" = "-" ]; then
    printf '    스테이지: 기본(runner)\n'
    ( cd "$DIR" && docker build -t "$TAG" . ) </dev/null 2>&1 | tee "$LOG" | tail -3
    RC=${PIPESTATUS[0]}
  else
    printf '    스테이지: --target %s\n' "$TGT"
    ( cd "$DIR" && docker build --target "$TGT" -t "$TAG" . ) </dev/null 2>&1 | tee "$LOG" | tail -3
    RC=${PIPESTATUS[0]}
  fi
  if [ "${RC:-1}" = "0" ]; then
    printf '  ✓ 구웠다\n'
  else
    printf '  ✗ 굽기 실패 — %s 를 보세요\n' "$LOG"; BFAIL=$((BFAIL+1))
    printf '%s\n' "      🔵 **vendor 를 먼저 의심하세요** — vendor/dss-core 나 vendor/dss-ui 가"
    printf '%s\n' "         비어 있으면 Module not found 로 죽습니다(3-ㄷ)."
    printf '%s\n' "         → git -C \"$DIR\" submodule update --init --recursive"
    continue
  fi

  # 🔴 docker save 는 작업 폴더로 들어가 **상대경로**로 쓴다(tar 의 드라이브 문자 함정).
  if ( cd "$OUT" && docker save "$TAG" -o "$FILE" ) </dev/null; then
    sz=$(stat -c %s "$OUT/$FILE" 2>/dev/null || wc -c < "$OUT/$FILE")
    printf '  ✓ tar %s (%s바이트)\n' "$FILE" "$sz"
  else
    printf '  ✗ tar 내보내기 실패\n'; BFAIL=$((BFAIL+1)); continue
  fi

  # 🔴 tar 의 Config 를 **빌드 로그의 exporting config** 와 맞댄다.
  #    'docker image inspect' 의 .Id 와는 **애초에 다른 값**이다.
  cfg=$(tar_config_id "$OUT/$FILE")
  exp=$(tr -d '\000' < "$LOG" | grep -oE "exporting config sha256:[0-9a-f]+" | tail -1 | grep -oE "sha256:[0-9a-f]+")
  printf '    tar  %s\n' "${cfg:-못 읽음}"
  printf '    로그 %s\n' "${exp:-없음}"
  if [ -n "$cfg" ] && [ -n "$exp" ] && [ "$cfg" = "$exp" ]; then printf '  ✓ 지문이 빌드 로그와 같다\n'
  elif [ -z "$exp" ]; then printf '  ⚠️ 빌드 로그에 exporting config 가 없다 (buildx 판에 따라 안 찍힌다)\n'
  else printf '  ✗ 지문이 다르다\n'; BFAIL=$((BFAIL+1)); continue; fi

  # ── 🔴 크기 견주기 ① — **지난 판 tar 와** ────────────────────────────
  if [ "$STRICT" = "none" ]; then
    printf '  ⚠️ 지난 판 %s 의 바이트가 **이 저장소에 적힌 곳이 없다** — ①번 견주기를 건너뛴다\n' "$PREVTAR"
    printf '%s\n' "      🔵 0 을 기대값으로 쓰면 「차이 무한%」로 **가짜 ✗** 가 납니다."
  else
    p=$(pct_diff "$sz" "$PREVSZ")
    if [ -n "${p:-}" ]; then
      printf '    지난 판 %s %s바이트 → 이번 %s바이트 (차이 %s%%)\n' "$PREVTAR" "$PREVSZ" "$sz" "$p"
      if [ "$p" -le 25 ]; then
        printf '  ✓ 지난 판 tar 와 크기가 비슷하다 (차이 %s%% · 25%% 이내)\n' "$p"
      elif [ "$STRICT" = "loose" ] && [ "$p" -le 60 ]; then
        printf '  ⚠️ 지난 판 tar 와 %s%% 다르다 — 이 줄은 loose 라 막지 않습니다\n' "$p"
      else
        printf '  ✗ 지난 판 tar 와 크기가 %s%% 다르다 — %s 에서는 그만큼이면 멈춘다\n' "$p" "$STRICT"
        printf '%s\n' "      🔵 **검사 자신을 먼저 의심하세요.** 라이브러리가 늘거나 베이스 이미지가"
        printf '%s\n' "         바뀌면 정상적으로도 이만큼 뜁니다. 🔴 다만 이번 판은 package.json ·"
        printf '%s\n' "         package-lock.json 이 **0줄** 바뀌었습니다(5-ㄷ) — 그래서 strict 입니다."
        printf '%s\n' "         🔵 **지난 판 바이트는 74번(2026-11-26) 것**이라 하루 차이입니다 —"
        printf '%s\n' "            그 사이 베이스 이미지가 바뀌었을 확률이 낮습니다. 까닭을 모르면"
        printf '%s\n' "            **멈추고 알리세요.**"
        BFAIL=$((BFAIL+1)); continue
      fi
    else
      printf '  ✗ 크기를 못 쟀다 (이번 %s · 지난 판 %s)\n' "${sz:-없음}" "${PREVSZ:-없음}"
      BFAIL=$((BFAIL+1)); continue
    fi
  fi

  # ── 🔴 크기 견주기 ② — **그 이미지 자신과** (가지를 둘로 나눈다) ───
  isz=$(docker image inspect "$TAG" --format '{{.Size}}' 2>/dev/null)
  if isnum "${isz:-}" && [ "${isz:-0}" -gt 0 ]; then
    rr=$((sz * 100 / isz))
    printf '    이미지 inspect .Size %s바이트 · tar 는 그 %s%%\n' "$isz" "$rr"
    if [ "$rr" -ge 90 ] && [ "$rr" -le 110 ]; then
      printf '  ✓ tar 가 이미지 내용 크기와 거의 같다 (%s%% — containerd 저장소다)\n' "$rr"
    elif [ "$rr" -ge 10 ] && [ "$rr" -le 45 ]; then
      printf '  ✓ tar 가 이미지의 1/4 쯤이다 (%s%% — 고전 저장소다)\n' "$rr"
    else
      printf '  ✗ tar 가 이미지의 %s%% 다 — 90~110%% 나 10~45%% 를 기대했다\n' "$rr"
      printf '%s\n' "      🔵 **검사 자신을 먼저 의심하세요.** 이 비는 docker 의 저장소 방식이 정합니다."
      BFAIL=$((BFAIL+1)); continue
    fi
  else
    printf '  ? 이미지 크기를 못 쟀다 — docker image inspect 가 수를 안 돌려줬다\n'
    BFAIL=$((BFAIL+1)); continue
  fi

  m5=$(md5sum "$OUT/$FILE" | awk '{print $1}')
  printf '    md5  %s\n' "$m5"
  TARTABLE="$TARTABLE$FILE|$sz|$m5|${cfg:-없음}
"
  BUILT=$((BUILT+1))

  # ══ 🔴 이미지 **안**을 센다 — 겉이 아니라 결과 ═══════════════════════
  inside_check "$KEY" "$TAG" "$TGT"
  if [ "$IMGFAIL" != 0 ]; then
    printf '%s\n' "🔴 $TAG 의 안이 온전하지 않다. 올리지 마세요."
    BFAIL=$((BFAIL+1))
  fi
done <<ENDBUILD
$(rows_of "$IMAGES")
ENDBUILD

# ══════════════════════════════════════════════════════════════════════
# ── 🔴🔴 **셋째 산출물 — A/S 마이그레이션 묶음** (🔵 이번 판은 안 만든다) ──
# ══════════════════════════════════════════════════════════════════════
#   🔴 **A/S 만 그렇다.** A/S 도구의 /app/drizzle 은 **비어 있고**(inside_check 가 값으로
#      쟀다) 운영에서는 거기에 /volume1/dss/as-migrations 가 붙는다 — 새 .sql 은
#      **묶음으로만** 간다. 🔴 안 보내면 적용이 0건으로 **조용히** 끝나고 겉으로는
#      성공으로 보인다(31·39번이 겪었다).
#   🔵 **이번 판은 올릴 .sql 이 0건이라 묶음을 안 만든다.** 🔴 **절은 지우지 않았다** —
#      AS_NEW_MIGS_WANT 가 0 이면 **안 만들고**, 대신 **산출물 폴더에 옛 묶음이 섞여
#      있지 않은지**를 값으로 잰다. 🔴 1건이 생기는 날 그 수만 올리면 아래가 그대로 돈다.
#   🔵 71번은 「다섯째 산출물」이었다(그때는 이미지가 넷이었다) — 이미지가 둘이라
#      **셋째**다. 하는 일은 같다.
#   🔵 **재고는 묶음을 아예 안 쓴다** — 그 집의 .sql 은 **도구 이미지 안에** 구워져 간다.
MIGOK=1; msz=""; mm5=""
if [ "$AS_NEW_MIGS_WANT" = "0" ]; then
  printf '\n%s\n' "════════ 셋째 산출물 — 🔵 **묶음을 안 만듭니다** (올릴 .sql 0건) ════════"
  printf '%s\n' "🔵 운영의 볼륨은 일흔째가 만들어 둔 ${AS_SQL_WANT}장 **그대로**입니다 — 이번 판은 안 건드립니다."
  printf '%s\n' "🔴 **그래서 보낼 것은 tar 둘과 양식 넷뿐입니다** — 묶음을 보내면 **이미 적용된"
  printf '%s\n' "   판**(또는 더 옛 판)이 볼륨을 덮습니다."
  if [ -f "$MIGTAR" ]; then
    printf '  ✗ 🔴 산출물 폴더에 묶음이 **있습니다** — 지우세요: rm "%s"\n' "$MIGTAR"
    BFAIL=$((BFAIL+1)); MIGOK=0
  else
    printf '  ✓ 산출물 폴더에 묶음이 **없다** (보낼 것이 셋으로 보이지 않는다)\n'
  fi
else
  printf '\n%s\n' "════════ 셋째 산출물 — A/S 마이그레이션 묶음 ($AS_SQL_WANT 장) ════════"
  printf '%s\n' "🔴 **A/S 는 .sql 이 볼륨에서 돕니다** — 이미지로 안 가므로 이 묶음이 **유일한 길**입니다."
  # 🔴 옛 판의 묶음이 남아 있을 수 있다 — **지우고 다시 만든다.**
  rm -f "$MIGTAR" 2>/dev/null
  # 🔴 **tar 는 상대경로로 묶는다** — 작업 폴더로 들어가 drizzle 만 넘긴다.
  #    드라이브 문자가 섞이면 tar 가 그것을 **원격 호스트 이름**으로 읽어 깨진다.
  if ( cd "$ASD" && tar -czf "$MIGTAR" drizzle ) </dev/null; then
    msz=$(stat -c %s "$MIGTAR" 2>/dev/null || wc -c < "$MIGTAR")
    mm5=$(md5sum "$MIGTAR" | awk '{print $1}')
    printf '  ✓ as-migrations.tar.gz (%s바이트)\n' "$msz"
    printf '    md5  %s\n' "$mm5"
    printf '%s\n' "    🔵 지난 판의 묶음은 ${OLD_MIGTAR_SIZE}바이트였습니다 — 새 장과 그 스냅샷이"
    printf '%s\n' "       늘어 **그보다 큰 것이 정상**입니다(아래가 값으로 가릅니다)."
  else
    printf '  ✗ 묶음을 못 만들었다 — 🔴 **A/S 는 묶음이 필수다**\n'
    BFAIL=$((BFAIL+1)); MIGOK=0
  fi
  if [ "$MIGOK" = "1" ]; then
    migtar_inside "$MIGTAR"
    if [ "$MIGCHK_FAIL" != "0" ]; then BFAIL=$((BFAIL + MIGCHK_FAIL)); fi
    MIGLINE="as-migrations.tar.gz|${msz}|${mm5}|-"
  fi
fi

printf '\n%s\n' "────────────────────────────────────────────────────────────"
printf '  본 줄 %s / %s · 구운 것 %s / %s · **안을 실제로 센 횟수 %s** · 묶음 %s · 실패 %s\n' \
  "$BUILD_SEEN" "$HOWMANY" "$BUILT" "$HOWMANY" "$INSIDE_RAN" "$MIGOK" "$BFAIL"
# 🔴 **표본이 비어서 공짜로 통과하지 않게** 한다 — 고리가 한 바퀴만 돌아도 잡힌다.
if [ "$BUILD_SEEN" != "$HOWMANY" ]; then
  printf '  ✗ IMAGES 표를 %s줄만 돌았다 — %s줄을 기대했다. **고리가 끊겼다**\n' "$BUILD_SEEN" "$HOWMANY"
  BFAIL=$((BFAIL+1))
fi
if [ "$INSIDE_RAN" != "$HOWMANY" ]; then
  printf '  ✗ 이미지 안을 %s번만 쟀다 — %s번을 기대했다. **아무것도 안 잰 통과다**\n' "$INSIDE_RAN" "$HOWMANY"
  BFAIL=$((BFAIL+1))
fi

# ══ 🔴 **✗ 가 나도 지문 줄만은 찍는다** ═══════════════════════════════
#   🔴 쉰세째·쉰네째에 **두 번 연속으로 지문을 못 받았다.** 그래서 **세 자리**에서 찍는다.
if [ "$BFAIL" != "0" ]; then
  printf '\n%s\n' "🔴🔴🔴 **실패가 있지만 지금까지 만든 산출물의 지문은 아래가 전부입니다**"
  printf '%s\n' "       (이름|바이트|md5|Config 지문 — 75-deploy.sh 의 TARS 에 넣을 꼴입니다)"
  if [ -n "${TARTABLE:-}" ]; then printf '%s' "$TARTABLE"
  else printf '%s\n' "       (tar 가 한 줄도 없습니다 — 하나도 안 구워졌다는 뜻입니다.)"; fi
  if [ -n "${MIGLINE:-}" ]; then
    printf '%s\n' "       MIGTAR_SIZE=${msz}"
    printf '%s\n' "       MIGTAR_MD5=${mm5}"
  else
    printf '%s\n' "       (묶음 줄이 없습니다 — 🔵 **이번 판은 묶음을 안 만듭니다.** 그것이 맞습니다.)"
  fi
  printf '%s\n' "🔴🔴🔴 **실패를 고친 뒤 다시 구우면 지문이 바뀝니다** — 위 값을 그대로 쓰지"
  printf '%s\n' "       마시고, 다시 구운 뒤의 값을 쓰세요."
  printf '%s\n' "       🔵 **검사 쪽이 틀린 것이면 다시 굽지 말고 --verify 를 쓰세요** —"
  printf '%s\n' "          지문이 바뀌지 않습니다."
  printf '\n%s\n' "🔴 실패가 있다. 위를 보세요."
  exit 1
fi

# 🔴 **굽고 나서 저장소가 더러워졌는가** — next build 가 tsconfig.json 을 다시 접는다.
printf '\n%s\n' "════════ 구운 뒤 저장소가 그대로인가 ════════"
printf '%s\n' "🔴 next build 가 tsconfig.json 을 다시 접은 적이 있습니다(눈에 안 띕니다)."
DIRTY_SEEN=0
while IFS= read -r r; do
  [ -n "$r" ] || continue
  DIRTY_SEEN=$((DIRTY_SEEN+1))
  RD="$DEV/$(field "$r" 2)"; RN=$(field "$r" 3)
  d=$(git -C "$RD" status --porcelain=v1 2>/dev/null | wc -l | tr -d ' ')
  if [ "${d:-1}" = "0" ]; then printf '  ✓ %s 미커밋 0줄\n' "$RN"
  else
    printf '  ⚠️ %s 에 미커밋이 %s줄 생겼다 — **사람에게 알리세요**\n' "$RN" "$d"
    git -C "$RD" status --porcelain=v1 2>/dev/null | head -6 | sed 's/^/        /'
  fi
done <<ENDDIRTY
$(rows_of "$REPOS")
ENDDIRTY
printf '  (본 저장소 %s / %s)\n' "$DIRTY_SEEN" "$REPOS_WANT"
# 🔴 **서브모듈 둘도 본다** — dss-ui 가 빠지면 다음에 안 구워진다.
#    🔵 73번은 셋이었다(셋째가 재고의 dss-ui) — 되살릴 때 그 줄을 함께 가져와라.
for p in "$COREDIR:vendor/dss-core(A/S)" "$UIDIR:vendor/dss-ui(A/S)"; do
  pd=${p%%:*}; pn=${p#*:}
  d=$(git -C "$pd" status --porcelain=v1 2>/dev/null | wc -l | tr -d ' ')
  if [ "${d:-1}" = "0" ]; then printf '  ✓ %s 미커밋 0줄\n' "$pn"
  else printf '  ⚠️ %s 에 미커밋이 %s줄 생겼다 — 사람에게 알리세요\n' "$pn" "$d"; fi
done
printf '%s\n' "  🔵 **tar 는 이미 구워졌습니다** — 되돌릴지 그대로 둘지는 사람이 정하세요."

